def write_release_test_report(root: Path, results: list[ReleaseCommandResult], public_checks: list[Check], *, public: bool, started_at: str, finished_at: str, elapsed_seconds: float, trace_smokes: bool = False) -> None:
    report_dir = root / ".pf" / "runtime" / "release-test"
    report_dir.mkdir(parents=True, exist_ok=True)
    data = {
        "schema_version": 1,
        "public": public,
        "started_at": started_at,
        "finished_at": finished_at,
        "elapsed_seconds": round(elapsed_seconds, 3),
        "result": "FAIL" if any(item.status == "FAIL" for item in results) or any(item.level == "FAIL" for item in public_checks) else "PASS",
        "checks": [
            {
                "label": item.label,
                "status": item.status,
                "exit_code": item.code,
                "started_at": item.started_at,
                "finished_at": item.finished_at,
                "elapsed_seconds": round(item.elapsed_seconds, 3),
                "timeout_seconds": item.timeout_seconds,
                "timeout_reason": "timeout" if item.code == 124 else None,
                "command": item.command,
                "layer": item.layer,
                "public_gate": item.public_gate,
            }
            for item in results
        ],
        "public_checks": [{"level": item.level, "message": item.message} for item in public_checks],
    }
    (report_dir / "latest-report.json").write_text(ensure_trailing_newline(json.dumps(data, indent=2, sort_keys=True)), encoding="utf-8")
    lines = [
        "# Release Test Report",
        "",
        f"- result: `{data['result']}`",
        f"- public: `{str(public).lower()}`",
        f"- started_at: `{started_at}`",
        f"- finished_at: `{finished_at}`",
        f"- elapsed_seconds: `{elapsed_seconds:.2f}`",
        "",
        "## Checks",
        "",
        "| Check | Layer | Public Gate | Status | Exit | Elapsed | Timeout |",
        "|---|---|---:|---:|---:|---:|---:|",
    ]
    for item in results:
        lines.append(f"| `{item.label}` | `{item.layer}` | {str(item.public_gate).lower()} | {item.status} | {item.code} | {item.elapsed_seconds:.2f}s | {item.timeout_seconds}s |")
    if public_checks:
        lines.extend(["", "## Public Checks", ""])
        lines.extend(f"- {item.level}: {item.message}" for item in public_checks)
    (report_dir / "latest-report.md").write_text("\n".join(lines) + "\n", encoding="utf-8")
    if trace_smokes:
        trace_lines = []
        for item in results:
            trace_lines.append(
                json.dumps(
                    {
                        "label": item.label,
                        "status": item.status,
                        "elapsed_seconds": round(item.elapsed_seconds, 3),
                        "timeout_seconds": item.timeout_seconds,
                        "timeout_reason": "timeout" if item.code == 124 else None,
                        "command": item.command,
                    },
                    sort_keys=True,
                )
            )
        (report_dir / "latest-trace.ndjson").write_text(ensure_trailing_newline("\n".join(trace_lines)), encoding="utf-8")


def command_release_test(args: argparse.Namespace) -> int:
    root = Path(args.root).expanduser().resolve()
    timeout_scale = float(getattr(args, "timeout_scale", 1.0) or 1.0)
    if timeout_scale <= 0:
        print("FAIL: --timeout-scale must be greater than 0")
        return 1
    clean_first = not getattr(args, "no_clean", False)
    if getattr(args, "clean_first", False):
        clean_first = True
    public_requested = bool(getattr(args, "public", False))
    commands = release_test_commands(root, clean_first=clean_first, public=public_requested)
    only = set(getattr(args, "only", []) or [])
    skip = set(getattr(args, "skip", []) or [])
    if getattr(args, "list", False):
        for item in commands:
            print(f"{item.label}\tlayer={item.layer}\tpublic_gate={str(item.public_gate).lower()}")
        print("public-gate")
        print("git diff --check")
        return 0
    if only:
        known = {item.label for item in commands}
        known.update({"public-gate", "git diff --check"})
        unknown = sorted(only - known)
        if unknown:
            print("FAIL: unknown --only check(s): " + ", ".join(unknown))
            return 1
        public_group_selected = "public-gate" in only
        public_requested = public_requested or public_group_selected
        commands = [
            item
            for item in commands
            if item.label in only or (public_group_selected and item.public_gate)
        ]
        if not commands and "git diff --check" not in only:
            print("FAIL: --only selection resolved to no release commands")
            return 1
    if "public-gate" in skip:
        public_requested = False
    if skip:
        commands = [
            item
            for item in commands
            if item.label not in skip
            and not ("public-gate" in skip and item.public_gate)
        ]
    git_check_selected = (
        (root / ".git").exists()
        and (not only or "git diff --check" in only)
        and "git diff --check" not in skip
    )
    if not commands and not git_check_selected:
        print("FAIL: release-test selection resolved to no runnable checks")
        return 1
    print("ProcessForge release-test")
    started_at = now_utc()
    started = time.perf_counter()
    failed = False
    warned = False
    results: list[ReleaseCommandResult] = []
    for item in commands:
        scaled_timeout = max(1, int(item.timeout * timeout_scale))
        result = run_release_command(item.label, item.command, root, timeout=scaled_timeout, allow_warn=item.allow_warn, layer=item.layer, public_gate=item.public_gate)
        print_release_command_output(result)
        results.append(result)
        failed = failed or result.status == "FAIL"
        warned = warned or result.status == "WARN"
        if failed and getattr(args, "fail_fast", False):
            break
    if not failed or not getattr(args, "fail_fast", False):
        git_dir = root / ".git"
        if git_dir.exists() and (not only or "git diff --check" in only) and "git diff --check" not in skip:
            result = run_release_command("git diff --check", ["git", "diff", "--check"], root, timeout=max(1, int(60 * timeout_scale)))
            print_release_command_output(result)
            results.append(result)
            failed = failed or result.status == "FAIL"
            warned = warned or result.status == "WARN"
        elif not git_dir.exists():
            print("WARN git diff --check skipped: not a git repo")
            warned = True
    else:
        print("SKIP git diff --check: fail-fast")
    public_checks: list[Check] = []
    if public_requested:
        public_checks = public_release_checks(root)
        public_status = print_checks(public_checks)
        failed = failed or public_status != 0
    finished_at = now_utc()
    elapsed = time.perf_counter() - started
    write_release_test_report(root, results, public_checks, public=public_requested, started_at=started_at, finished_at=finished_at, elapsed_seconds=elapsed, trace_smokes=bool(getattr(args, "trace_smokes", False)))
    print(f"REPORT: {rel(root / '.pf' / 'runtime' / 'release-test' / 'latest-report.json', root)}")
    print(f"REPORT: {rel(root / '.pf' / 'runtime' / 'release-test' / 'latest-report.md', root)}")
    if getattr(args, "trace_smokes", False):
        print(f"TRACE: {rel(root / '.pf' / 'runtime' / 'release-test' / 'latest-trace.ndjson', root)}")
    print(f"ELAPSED: {elapsed:.2f}s")
    if failed:
        print("RESULT: FAIL")
        return 1
    print("RESULT: PASS with warnings" if warned else "RESULT: PASS")
    return 0


def command_dev_test(args: argparse.Namespace) -> int:
    root = Path(args.root).expanduser().resolve()
    runner = root / ".pf" / "dogfooding" / "run_dogfooding_tests.py"
    if not runner.is_file():
        print(f"FAIL: dogfooding runner missing: {rel(runner, root)}")
        return 1
    command = [sys.executable, str(runner)]
    if getattr(args, "list", False):
        command.append("--list")
    for suite in getattr(args, "suite", []) or []:
        command.extend(["--suite", suite])
    for test in getattr(args, "test", []) or []:
        command.extend(["--test", test])
    if getattr(args, "fail_fast", False):
        command.append("--fail-fast")
    timeout_scale = float(getattr(args, "timeout_scale", 1.0) or 1.0)
    if timeout_scale <= 0:
        print("FAIL: --timeout-scale must be greater than 0")
        return 1
    command.extend(["--timeout-scale", str(timeout_scale)])
    result = run_subprocess_command(command, cwd=root, timeout=max(1, int(1200 * timeout_scale)))
    output = "\n".join(part for part in [result.stdout, result.stderr] if part)
    if output:
        print(output, end="" if output.endswith("\n") else "\n")
    if result.timed_out:
        print("RESULT: FAIL")
        print(diagnostic_text(result))
        return 1
    return int(result.returncode or 0)


def command_version(args: argparse.Namespace) -> int:
    version_file = ROOT / "VERSION"
    version = version_file.read_text(encoding="utf-8", errors="replace").strip() if version_file.is_file() else PROCESSFORGE_VERSION
    print(f"ProcessForge {version}")
    print(f"Spec: {PROCESSFORGE_SPEC_VERSION}")
    print(f"Schema bundle: {PROCESSFORGE_SCHEMA_BUNDLE_VERSION}")
    return 0


HEX40_RE = re.compile(r"^[0-9a-f]{40}$")
HEX64_RE = re.compile(r"^[0-9a-f]{64}$")
ZIP_MINIMUM_EPOCH = 315532800


def git_release_output(root: Path, *args: str) -> str:
    result = subprocess.run(
        ["git", *args],
        cwd=root,
        text=True,
        encoding="utf-8",
        errors="replace",
        capture_output=True,
        check=False,
    )
    if result.returncode != 0:
        detail = (result.stderr or result.stdout or "").strip()
        raise SystemExit(f"FAIL: git {' '.join(args)} failed: {detail}")
    return result.stdout.rstrip("\r\n")


def release_git_provenance(root: Path) -> dict[str, Any]:
    if not (root / ".git").exists():
        raise SystemExit("FAIL: release-pack requires a Git source checkout for release manifest provenance")
    dirty = git_release_output(root, "status", "--porcelain=v1", "--untracked-files=all").splitlines()
    blocking_dirty = [line for line in dirty if not release_git_dirty_is_allowed_projection(line)]
    if blocking_dirty:
        sample = ", ".join(line.strip() for line in blocking_dirty[:20])
        suffix = f"; +{len(blocking_dirty) - 20} more" if len(blocking_dirty) > 20 else ""
        raise SystemExit(f"FAIL: release-pack requires clean git source before publishing: {sample}{suffix}")
    commit = git_release_output(root, "rev-parse", "HEAD")
    tree = git_release_output(root, "rev-parse", "HEAD^{tree}")
    if not HEX40_RE.fullmatch(commit) or not HEX40_RE.fullmatch(tree):
        raise SystemExit("FAIL: release-pack could not capture valid git commit/tree provenance")
    commit_epoch_text = git_release_output(root, "show", "-s", "--format=%ct", "HEAD")
    try:
        commit_epoch = int(commit_epoch_text)
    except ValueError as exc:
        raise SystemExit(f"FAIL: invalid git commit timestamp: {commit_epoch_text}") from exc
    source_epoch_text = os.environ.get("SOURCE_DATE_EPOCH")
    if source_epoch_text:
        try:
            source_epoch = int(source_epoch_text)
        except ValueError as exc:
            raise SystemExit(f"FAIL: invalid SOURCE_DATE_EPOCH: {source_epoch_text}") from exc
    else:
        source_epoch = commit_epoch
    if source_epoch < ZIP_MINIMUM_EPOCH:
        raise SystemExit("FAIL: release-pack source date is before the ZIP timestamp lower bound 1980-01-01")
    generated_at = datetime.fromtimestamp(source_epoch, timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
    return {
        "source_date_epoch": source_epoch,
        "generated_at": generated_at,
        "source": {
            "vcs": "git",
            "commit": commit,
            "tree": tree,
            "dirty": False,
        },
    }


def official_release_pack_entries(root: Path) -> list[dict[str, Any]]:
    entries: list[dict[str, Any]] = []
    official_root = root / "packs" / "official"
    if not official_root.is_dir():
        return entries
    for manifest in sorted(official_root.glob("*/package.yaml")):
        data = load_yaml_document(manifest)
        if not isinstance(data, dict) or data.get("origin") != "official":
            continue
        entries.append(
            {
                "id": str(data.get("id") or ""),
                "version": str(data.get("version") or ""),
                "manifest_path": rel(manifest, root),
                "manifest_sha256": sha256_file(manifest),
            }
        )
    return sorted(entries, key=lambda item: item["id"])


def release_zip_datetime(source_epoch: int) -> tuple[int, int, int, int, int, int]:
    moment = datetime.fromtimestamp(source_epoch, timezone.utc)
    return (moment.year, moment.month, moment.day, moment.hour, moment.minute, moment.second)


def release_file_content(source_path: Path) -> bytes:
    """Canonicalize text line endings so archives do not depend on checkout settings."""
    content = source_path.read_bytes()
    return content if b"\0" in content else content.replace(b"\r\n", b"\n")


def release_core_manifest(files: list[tuple[str, Path]], *, version: str, source: dict[str, Any] | None, generated_at: str | None = None) -> dict[str, Any]:
    from processforge_core.core_update import CORE_MANIFEST_NAME, make_core_manifest

    entries = []
    for archive_path, source_path in files:
        if archive_path == CORE_MANIFEST_NAME:
            continue
        content = release_file_content(source_path)
        entries.append({"relative_path": archive_path, "size": len(content), "sha256": hashlib.sha256(content).hexdigest()})
    return make_core_manifest(version=version, source=source, files=entries, generated_at=generated_at)


def write_release_zip(output: Path, files: list[tuple[str, Path]], source_epoch: int, extra_entries: list[tuple[str, bytes]] | None = None) -> list[dict[str, Any]]:
    manifest_files: list[dict[str, Any]] = []
    zip_datetime = release_zip_datetime(source_epoch)
    entries: list[tuple[str, Path | None, bytes | None]] = [(archive_path, source_path, None) for archive_path, source_path in files]
    entries.extend((archive_path, None, content) for archive_path, content in extra_entries or [])
    with zipfile.ZipFile(output, "w", compression=zipfile.ZIP_DEFLATED, compresslevel=9) as archive:
        for archive_path, source_path, generated_content in sorted(entries, key=lambda item: item[0]):
            content = release_file_content(source_path) if source_path is not None else generated_content
            if content is None:
                raise SystemExit(f"FAIL: release-pack entry has no content: {archive_path}")
            info = zipfile.ZipInfo(archive_path, date_time=zip_datetime)
            info.compress_type = zipfile.ZIP_DEFLATED
            info.external_attr = 0o100644 << 16
            archive.writestr(info, content, compress_type=zipfile.ZIP_DEFLATED, compresslevel=9)
            manifest_files.append(
                {
                    "path": archive_path,
                    "size": len(content),
                    "sha256": hashlib.sha256(content).hexdigest(),
                }
            )
    return manifest_files


def release_manifest_payload(
    root: Path,
    output: Path,
    manifest_files: list[dict[str, Any]],
    provenance: dict[str, Any],
) -> dict[str, Any]:
    return {
        "schema_version": 1,
        "name": RELEASE_NAME,
        "version": RELEASE_ARCHIVE_VERSION,
        "schema_bundle_version": PROCESSFORGE_SCHEMA_BUNDLE_VERSION,
        "release_eligible": True,
        "build": {
            "source_date_epoch": provenance["source_date_epoch"],
            "generated_at": provenance["generated_at"],
            "deterministic": True,
        },
        "source": provenance["source"],
        "archive": {
            "filename": output.name,
            "format": "zip",
            "size": output.stat().st_size,
            "sha256": sha256_file(output),
            "entry_count": len(manifest_files),
        },
        "official_packs": official_release_pack_entries(root),
        "files": manifest_files,
    }


def command_release_pack(args: argparse.Namespace) -> int:
    root = Path(args.root).expanduser().resolve()
    output = Path(args.output).expanduser()
    if not output.is_absolute():
        output = (root / output).resolve()
    manifest_path = output.with_suffix(".manifest.json")
    checks = release_checks(root)
    failures = [item for item in checks if item.level == "FAIL"]
    if failures:
        for item in failures:
            print(f"FAIL: {item.message}")
        return 1
    for label, script in [
        ("public cleanliness", root / "tools" / "validate-public-cleanliness.py"),
        ("checksum inventory", root / "tools" / "validate-process-forge-checksums.py"),
    ]:
        command = [sys.executable, str(script), "--root", str(root)]
        if label == "checksum inventory":
            command.append("--check")
        result = subprocess.run(command, cwd=root, text=True, encoding="utf-8", errors="replace", capture_output=True, check=False)
        if result.returncode != 0:
            print(f"FAIL: release-pack preflight {label}")
            print((result.stdout or result.stderr).strip())
            return 1
    patterns = release_ignore_patterns(root)
    files = [(archive_path, path) for archive_path, path in release_source_files(root) if not release_ignore_match(archive_path, patterns) and not release_path_is_forbidden(archive_path)]
    if args.dry_run:
        print(f"DRY-RUN: would write {output}")
        print(f"DRY-RUN: would write {manifest_path}")
        print(f"FILES: {len(files) + 1}")
        print("INCLUDE: processforge-core.manifest.json [generated]")
        for archive_path, _path in files[:50]:
            print(f"INCLUDE: {archive_path}")
        if len(files) > 50:
            print(f"... {len(files) - 50} more files")
        return 0
    provenance = release_git_provenance(root)
    from processforge_core.core_update import CORE_MANIFEST_NAME, manifest_bytes

    core_manifest = release_core_manifest(files, version=RELEASE_ARCHIVE_VERSION, source=provenance["source"], generated_at=provenance["generated_at"])
    output.parent.mkdir(parents=True, exist_ok=True)
    manifest_files = write_release_zip(output, files, int(provenance["source_date_epoch"]), extra_entries=[(CORE_MANIFEST_NAME, manifest_bytes(core_manifest))])
    manifest = release_manifest_payload(root, output, manifest_files, provenance)
    manifest_path.write_text(ensure_trailing_newline(json.dumps(manifest, indent=2, sort_keys=True)), encoding="utf-8")
    consumer_checks = inspect_release_archive(output, manifest_path)
    consumer_failures = [item for item in consumer_checks if item.level == "FAIL"]
    if consumer_failures:
        for item in consumer_failures:
            print(f"FAIL: {item.message}")
        return 1
    print(f"WROTE: {rel(output, root)}")
    print(f"WROTE: {rel(manifest_path, root)}")
    print(f"FILES: {len(manifest_files)}")
    return 0


def archive_manifest_path(archive_path: Path) -> Path:
    return archive_path.with_suffix(".manifest.json")


def release_manifest_path_error(name: str) -> str | None:
    if not name or "\x00" in name or any(ord(char) < 32 for char in name):
        return "empty, NUL, or control-character archive path"
    normalized = name.replace("\\", "/")
    if "\\" in name:
        return "archive path contains backslash"
    if normalized.startswith("/") or re.match(r"^[A-Za-z]:", normalized) or normalized.startswith("//"):
        return "absolute, drive-qualified, or UNC archive path"
    parts = normalized.split("/")
    if any(part in {"", ".", ".."} for part in parts):
        return "archive path contains empty, current, or parent segment"
    if Path(normalized).is_absolute():
        return "absolute archive path"
    return None


def validate_release_manifest_contract(
    data: Any,
    archive_path: Path,
    infos: list[zipfile.ZipInfo],
) -> list[Check]:
    checks: list[Check] = []
    actual_size = archive_path.stat().st_size
    actual_sha = sha256_file(archive_path)
    if not isinstance(data, dict):
        return [check("FAIL", "release manifest v1 is an object")]
    top_keys = {"schema_version", "name", "version", "schema_bundle_version", "release_eligible", "build", "source", "archive", "official_packs", "files"}
    unexpected = sorted(set(data) - top_keys)
    missing = sorted(top_keys - set(data))
    checks.append(check("PASS" if not unexpected else "FAIL", "release manifest v1 has no unexpected top-level keys"))
    checks.append(check("PASS" if not missing else "FAIL", "release manifest v1 required keys present"))
    for key in unexpected[:10]:
        checks.append(check("FAIL", f"release manifest unexpected key: {key}"))
    for key in missing[:10]:
        checks.append(check("FAIL", f"release manifest missing key: {key}"))
    checks.append(check("PASS" if data.get("schema_version") == 1 else "FAIL", "release manifest schema_version is 1"))
    checks.append(check("PASS" if data.get("name") == RELEASE_NAME else "FAIL", "release manifest name is processforge"))
    checks.append(check("PASS" if data.get("release_eligible") is True else "FAIL", "release manifest marks public release eligible"))

    build = data.get("build") if isinstance(data.get("build"), dict) else {}
    source_epoch = build.get("source_date_epoch")
    generated_at = build.get("generated_at")
    expected_generated_at = None
    if isinstance(source_epoch, int) and source_epoch >= ZIP_MINIMUM_EPOCH:
        expected_generated_at = datetime.fromtimestamp(source_epoch, timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
    checks.append(check("PASS" if isinstance(source_epoch, int) and source_epoch >= ZIP_MINIMUM_EPOCH else "FAIL", "release manifest source_date_epoch is valid"))
    checks.append(check("PASS" if generated_at == expected_generated_at else "FAIL", "release manifest generated_at matches source_date_epoch"))
    checks.append(check("PASS" if build.get("deterministic") is True else "FAIL", "release manifest declares deterministic build"))

    source = data.get("source") if isinstance(data.get("source"), dict) else {}
    checks.append(check("PASS" if source.get("vcs") == "git" else "FAIL", "release manifest source vcs is git"))
    checks.append(check("PASS" if isinstance(source.get("commit"), str) and HEX40_RE.fullmatch(source["commit"]) else "FAIL", "release manifest source commit is 40 lowercase hex"))
    checks.append(check("PASS" if isinstance(source.get("tree"), str) and HEX40_RE.fullmatch(source["tree"]) else "FAIL", "release manifest source tree is 40 lowercase hex"))
    checks.append(check("PASS" if source.get("dirty") is False else "FAIL", "release manifest source dirty is false"))

    archive_data = data.get("archive") if isinstance(data.get("archive"), dict) else {}
    checks.append(check("PASS" if archive_data.get("filename") == archive_path.name else "FAIL", "release manifest archive filename matches sidecar zip"))
    checks.append(check("PASS" if archive_data.get("format") == "zip" else "FAIL", "release manifest archive format is zip"))
    checks.append(check("PASS" if archive_data.get("size") == actual_size else "FAIL", "release manifest archive size matches zip bytes"))
    checks.append(check("PASS" if archive_data.get("sha256") == actual_sha else "FAIL", "release manifest archive sha256 matches zip bytes"))
    checks.append(check("PASS" if archive_data.get("entry_count") == len(infos) else "FAIL", "release manifest archive entry_count matches physical zip entries"))

    files = data.get("files")
    if not isinstance(files, list):
        checks.append(check("FAIL", "release manifest files is a list"))
        return checks
    manifest_names = [str(item.get("path")) for item in files if isinstance(item, dict) and item.get("path")]
    sorted_unique = manifest_names == sorted(manifest_names) and len(manifest_names) == len(set(manifest_names))
    checks.append(check("PASS" if sorted_unique else "FAIL", "release manifest files are sorted and unique by path"))
    checks.append(check("PASS" if len(files) == len(infos) else "FAIL", "release manifest files length matches physical zip entries"))

    physical_names = [info.filename for info in infos]
    unsafe: list[str] = []
    normalized_seen: set[str] = set()
    for info in infos:
        error = release_manifest_path_error(info.filename)
        normalized = unicodedata.normalize("NFC", info.filename).casefold()
        if normalized in normalized_seen:
            error = error or "archive path collides after Unicode/case normalization"
        normalized_seen.add(normalized)
        if info.flag_bits & 0x1:
            error = error or "encrypted archive member"
        mode = (info.external_attr >> 16) & 0o170000
        if mode and mode != 0o100000:
            error = error or "non-regular archive member"
        if error:
            unsafe.append(f"{info.filename}: {error}")
    checks.append(check("PASS" if not unsafe else "FAIL", "release archive physical members are safe regular files"))
    for item in unsafe[:20]:
        checks.append(check("FAIL", f"unsafe archive member: {item}"))

    checks.append(check("PASS" if sorted(physical_names) == manifest_names else "FAIL", "release manifest file list matches zip entries"))
    file_map = {str(item.get("path")): item for item in files if isinstance(item, dict) and item.get("path")}
    with zipfile.ZipFile(archive_path) as archive:
        mismatches: list[str] = []
        for info in infos:
            item = file_map.get(info.filename)
            if not isinstance(item, dict):
                continue
            content = archive.read(info)
            if item.get("size") != len(content):
                mismatches.append(f"{info.filename}: size")
            if item.get("sha256") != hashlib.sha256(content).hexdigest():
                mismatches.append(f"{info.filename}: sha256")
            if not isinstance(item.get("sha256"), str) or not HEX64_RE.fullmatch(str(item.get("sha256"))):
                mismatches.append(f"{info.filename}: sha256 format")
    checks.append(check("PASS" if not mismatches else "FAIL", "release manifest file size/hash entries match zip payloads"))
    for item in mismatches[:20]:
        checks.append(check("FAIL", f"release manifest file mismatch: {item}"))

    official_packs = data.get("official_packs")
    if isinstance(official_packs, list):
        ids = [str(item.get("id")) for item in official_packs if isinstance(item, dict)]
        valid = ids == sorted(ids) and len(ids) == len(set(ids))
        for item in official_packs:
            valid = valid and isinstance(item, dict)
            if isinstance(item, dict):
                valid = valid and isinstance(item.get("id"), str) and bool(item.get("id"))
                valid = valid and isinstance(item.get("version"), str) and bool(item.get("version"))
                valid = valid and isinstance(item.get("manifest_path"), str) and bool(item.get("manifest_path"))
                valid = valid and isinstance(item.get("manifest_sha256"), str) and bool(HEX64_RE.fullmatch(item["manifest_sha256"]))
        checks.append(check("PASS" if valid else "FAIL", "release manifest official_packs are sorted v1 provenance entries"))
    else:
        checks.append(check("FAIL", "release manifest official_packs is a list"))
    return checks


def inspect_release_archive(archive_path: Path, manifest_path: Path | None = None) -> list[Check]:
    checks: list[Check] = []
    checks.append(check("PASS" if archive_path.is_file() else "FAIL", f"archive exists: {archive_path}"))
    if not archive_path.is_file():
        return checks
    manifest = manifest_path or archive_manifest_path(archive_path)
    checks.append(check("PASS" if manifest.is_file() else "FAIL", f"manifest exists: {manifest}"))
    with zipfile.ZipFile(archive_path) as archive:
        infos = [info for info in archive.infolist() if not info.filename.endswith("/")]
        names = sorted(info.filename for info in infos)
        forbidden = [name for name in names if release_path_is_forbidden(name) or name.startswith(".serena/") or name.startswith(".idea/") or name.startswith(".vscode/")]
        checks.append(check("PASS" if not forbidden else "FAIL", f"archive forbidden entries: {len(forbidden)}"))
        for name in forbidden[:20]:
            checks.append(check("FAIL", f"forbidden archive entry: {name}"))
        if manifest.is_file():
            data = json.loads(manifest.read_text(encoding="utf-8"))
            checks.extend(validate_release_manifest_contract(data, archive_path, infos))
            manifest_files = data.get("files") if isinstance(data, dict) else None
            manifest_names = sorted(str(item.get("path")) for item in manifest_files if isinstance(item, dict) and item.get("path")) if isinstance(manifest_files, list) else []
            checks.append(check("PASS" if manifest_names == names else "FAIL", "manifest file list matches zip entries"))
            if manifest_names == names:
                checks.append(check("PASS", f"manifest files: {len(manifest_names)}"))
            else:
                missing = sorted(set(names) - set(manifest_names))
                extra = sorted(set(manifest_names) - set(names))
                for name in missing[:10]:
                    checks.append(check("FAIL", f"zip entry missing from manifest: {name}"))
                for name in extra[:10]:
                    checks.append(check("FAIL", f"manifest entry missing from zip: {name}"))
    return checks


def expected_release_files_from_root(root: Path) -> list[tuple[str, Path]]:
    patterns = release_ignore_patterns(root)
    expected: list[tuple[str, Path]] = []
    for archive_path, source_path in release_source_files(root):
        if release_ignore_match(archive_path, patterns):
            continue
        if release_path_is_forbidden(archive_path):
            continue
        expected.append((archive_path, source_path))
    return expected


def expected_release_manifest_from_root(root: Path, manifest_data: dict[str, Any] | None = None) -> dict[str, str]:
    expected_files = expected_release_files_from_root(root)
    expected = {archive_path: hashlib.sha256(release_file_content(source_path)).hexdigest() for archive_path, source_path in expected_files}
    if manifest_data:
        from processforge_core.core_update import CORE_MANIFEST_NAME, manifest_bytes

        build = manifest_data.get("build") if isinstance(manifest_data.get("build"), dict) else {}
        source = manifest_data.get("source") if isinstance(manifest_data.get("source"), dict) else None
        core_manifest = release_core_manifest(
            expected_files,
            version=str(manifest_data.get("version") or RELEASE_ARCHIVE_VERSION),
            source=source,
            generated_at=str(build.get("generated_at") or ""),
        )
        expected[CORE_MANIFEST_NAME] = hashlib.sha256(manifest_bytes(core_manifest)).hexdigest()
    return expected


def archive_manifest_freshness_checks(root: Path, archive_path: Path, manifest_path: Path) -> list[Check]:
    checks: list[Check] = []
    manifest_data: dict[str, Any] | None = None
    if manifest_path.is_file():
        loaded_manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
        manifest_data = loaded_manifest if isinstance(loaded_manifest, dict) else None
    expected = expected_release_manifest_from_root(root, manifest_data)
    if not archive_path.is_file():
        return [check("FAIL", f"archive exists for root freshness check: {archive_path}")]
    with zipfile.ZipFile(archive_path) as archive:
        archive_names = sorted(name for name in archive.namelist() if not name.endswith("/"))
        archive_hashes = {name: hashlib.sha256(archive.read(name)).hexdigest() for name in archive_names}
    if sorted(expected) != archive_names:
        checks.append(check("FAIL", "archive entries match current root release file set"))
        for name in sorted(set(expected) - set(archive_names))[:20]:
            checks.append(check("FAIL", f"current root file missing from archive: {name}"))
        for name in sorted(set(archive_names) - set(expected))[:20]:
            checks.append(check("FAIL", f"archive entry not present in current root release set: {name}"))
    else:
        checks.append(check("PASS", f"archive entries match current root release file set: {len(expected)}"))
    stale_hashes = [name for name, sha in expected.items() if archive_hashes.get(name) != sha]
    if stale_hashes:
        checks.append(check("FAIL", "archive file hashes match current root"))
        for name in stale_hashes[:20]:
            checks.append(check("FAIL", f"stale archive entry hash: {name}"))
    else:
        checks.append(check("PASS", "archive file hashes match current root"))
    if manifest_data:
        manifest_files = manifest_data.get("files")
        manifest_hashes = {str(item.get("path")): str(item.get("sha256")) for item in manifest_files if isinstance(item, dict) and item.get("path")} if isinstance(manifest_files, list) else {}
        checks.append(check("PASS" if manifest_hashes == expected else "FAIL", "manifest hashes match current root release file set"))
    return checks


def command_release_archive_test(args: argparse.Namespace) -> int:
    archive_path = Path(args.archive).expanduser().resolve()
    manifest_path = Path(args.manifest).expanduser().resolve() if args.manifest else archive_manifest_path(archive_path)
    checks = inspect_release_archive(archive_path, manifest_path)
    if getattr(args, "root", None):
        root = Path(args.root).expanduser().resolve()
        checks.extend(archive_manifest_freshness_checks(root, archive_path, manifest_path))
    if print_checks(checks) != 0:
        return 1
    extracted_test = str(getattr(args, "extracted_test", "full") or "full")
    if extracted_test == "skip":
        print("SKIP: extracted archive release-test")
        print("RESULT: PASS")
        return 0
    timeout_scale = float(getattr(args, "timeout_scale", 1.0) or 1.0)
    if timeout_scale <= 0:
        print("FAIL: --timeout-scale must be greater than 0")
        return 1
    with tempfile.TemporaryDirectory(prefix="processforge-release-archive-") as temp:
        extract_root = Path(temp)
        with zipfile.ZipFile(archive_path) as archive:
            archive.extractall(extract_root)
        cli = extract_root / "tools" / "processforge.py"
        if not cli.is_file():
            print(f"FAIL: extracted archive has no CLI: {cli}")
            return 1
        for label, target in [("bin/pf.py --help", extract_root / "bin" / "pf.py"), ("tools/processforge.py --help", cli)]:
            result = run_release_command(label, [sys.executable, str(target), "--help"], extract_root, timeout=30)
            print_release_command_output(result)
            if result.status != "PASS":
                print("RESULT: FAIL")
                return 1
        command = [sys.executable, str(cli), "release-test", "--root", str(extract_root)]
        if extracted_test == "quick":
            command.extend([
                "--only", "py_compile",
                "--only", "schema validation",
                "--only", "public cleanliness",
                "--only", "checksum",
                "--only", "smoke_processforge_core_package_bootstrap",
                "--only", "smoke_central_event_ingress",
                "--only", "smoke_conversation_completeness",
                "--only", "smoke_central_event_replay",
            ])
        else:
            command.append("--public")
        result = run_release_command(
            "release-test extracted archive",
            command,
            extract_root,
            timeout=max(1, int(1200 * timeout_scale)),
        )
        print_release_command_output(result)
        if result.status != "PASS":
            print("RESULT: FAIL")
            return 1
    print("RESULT: PASS")
    return 0


def find_local_workplace_manifest(local_text: str) -> Path | None:
    manifest_pattern = r"(?m)^\s*" + "manifest:" + r"\s*(.+?)\s*$"
    match = re.search(manifest_pattern, local_text)
    if not match:
        return None
    value = match.group(1).strip().strip('"').strip("'")
    return Path(value)


def resolve_workplace_manifest(local_manifest: Path) -> Path | None:
    workplace = find_local_workplace_manifest(local_manifest.read_text(encoding="utf-8", errors="replace"))
    if not workplace:
        return None
    if not workplace.is_absolute():
        workplace = (local_manifest.parent / workplace).resolve()
    return workplace


def resolve_registry_path(workplace_manifest: Path, registry_key: str, default_name: str) -> Path:
    workplace = load_yaml_document(workplace_manifest)
    registries = workplace.get("registries", {}) if isinstance(workplace, dict) and isinstance(workplace.get("registries"), dict) else {}
    raw_path = str(registries.get(registry_key) or f"registries/{default_name}")
    return resolve_registry_relative_path(workplace_manifest.parent, raw_path, workplace_manifest)


def distribution_registry_entries(workplace_manifest: Path) -> list[dict[str, Any]]:
    registry = resolve_registry_path(workplace_manifest, "distributions", "distributions.yaml")
    data = load_yaml_document(registry)
    entries = data.get("distributions") if isinstance(data, dict) else None
    return [item for item in entries if isinstance(item, dict)] if isinstance(entries, list) else []


def resolve_distribution_path(workplace_manifest: Path, distribution_id: str = "processforge") -> Path | None:
    for entry in distribution_registry_entries(workplace_manifest):
        if str(entry.get("id")) != distribution_id:
            continue
        raw_path = entry.get("path")
        if not raw_path:
            return None
        return resolve_registry_relative_path(workplace_manifest.parent, str(raw_path), workplace_manifest)
    return None


def distribution_checks(distribution_root: Path | None) -> list[Check]:
    checks: list[Check] = []
    if not distribution_root:
        return [check("FAIL", "processforge distribution path is not configured")]
    checks.append(check("PASS" if distribution_root.is_dir() else "FAIL", "processforge distribution exists"))
    for dirname in ["tools", "schemas", "processes", "packages", "templates"]:
        path = distribution_root / dirname
        checks.append(check("PASS" if path.is_dir() else "FAIL", f"processforge distribution has {dirname}/"))
    return checks


def report_has_missing_required_capabilities(path: Path) -> bool:
    return report_section_has_items(path, "## Missing Required Capabilities")


def report_section_items(path: Path, marker: str) -> list[str]:
    if not path.is_file():
        return []
    text = path.read_text(encoding="utf-8", errors="replace")
    if marker not in text:
        return []
    section = text.split(marker, 1)[1].split("\n## ", 1)[0]
    items: list[str] = []
    for line in section.splitlines():
        stripped = line.strip()
        if stripped.startswith("- ") and stripped != "- None.":
            items.append(stripped[2:].strip())
    return items


def report_section_has_items(path: Path, marker: str) -> bool:
    return bool(report_section_items(path, marker))


def active_capability_waivers(project_root: Path) -> dict[str, list[dict[str, Any]]]:
    flow_root = locate_flow_root(project_root)
    paths = [
        flow_root / "capability-waivers.yaml",
        flow_root / "artifacts" / "capability-waivers.yaml",
    ]
    active: dict[str, list[dict[str, Any]]] = {}
    now = datetime.now(timezone.utc)
    for path in paths:
        if not path.is_file():
            continue
        data = load_yaml_document(path)
        if not isinstance(data, dict) or yaml_error(data):
            continue
        records = data.get("capability_waivers")
        if not isinstance(records, list):
            records = data.get("waivers")
        if not isinstance(records, list):
            continue
        for record in records:
            if not isinstance(record, dict):
                continue
            capability = str(record.get("capability") or "").strip()
            if not capability:
                continue
            status = str(record.get("status") or "active")
            if status not in {"active", "waived", "verified"}:
                continue
            expires_at = parse_snapshot_timestamp(record.get("expires_at"))
            if expires_at is not None and expires_at < now:
                continue
            active.setdefault(capability, []).append({**record, "path": rel(path, project_root)})
    return active


def capability_waiver_help() -> str:
    return """create .pf/artifacts/capability-waivers.yaml with explicit evidence, for example:
schema_version: 1
capability_waivers:
  - capability: filesystem.read
    status: active
    reason: runtime access verified; registry provider declaration is pending
    evidence: .pf/artifacts/delivery-report.md"""


def public_snapshot_path_checks(project_root: Path) -> list[Check]:
    snapshot_yaml, snapshot_md = project_context_snapshot_paths(project_root)
    checks: list[Check] = []
    for path in [snapshot_yaml, snapshot_md]:
        if not path.is_file():
            checks.append(check("WARN", f"{rel(path, project_root)} missing"))
            continue
        text = path.read_text(encoding="utf-8", errors="replace")
        checks.append(
            check(
                "PASS" if is_public_path_safe(text) else "FAIL",
                f"{rel(path, project_root)} contains no local absolute paths",
            )
        )
    return checks


def now_utc() -> str:
    return datetime.now(timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")


def sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(65536), b""):
            digest.update(chunk)
    return digest.hexdigest()


def yaml_list_values(text: str, key: str) -> list[str]:
    values: list[str] = []
    lines = text.splitlines()
    key_pattern = re.compile(rf"^(\s*){re.escape(key)}\s*:\s*$")
    inline_pattern = re.compile(rf"^\s*{re.escape(key)}\s*:\s*\[(.*?)\]\s*$")
    for index, line in enumerate(lines):
        inline = inline_pattern.match(line)
        if inline:
            values.extend(item.strip().strip('"').strip("'") for item in inline.group(1).split(",") if item.strip())
            continue
        match = key_pattern.match(line)
        if not match:
            continue
        indent = len(match.group(1))
        for child in lines[index + 1 :]:
            if not child.strip():
                continue
            child_indent = len(child) - len(child.lstrip(" "))
            if child_indent <= indent:
                break
            stripped = child.strip()
            if stripped.startswith("- "):
                values.append(stripped[2:].strip().strip('"').strip("'"))
    return values


def source_record(path: Path, root: Path, kind: str, required: bool, selection_reason: str, load_policy: str) -> dict[str, Any]:
    exists = path.is_file()
    record: dict[str, Any] = {
        "path": rel(path, root),
        "kind": kind,
        "required": required,
        "exists": exists,
        "selection_reason": selection_reason,
        "load_policy": load_policy,
    }
    if exists:
        checksum = sha256_file(path)
        record["checksum"] = checksum
        record["fingerprint"] = checksum
    else:
        record["checksum"] = "missing"
        record["fingerprint"] = "missing"
    return record


def resolve_flow_reference(project_root: Path, value: str) -> Path:
    path = Path(value)
    if path.is_absolute():
        return path
    return (locate_flow_root(project_root) / path).resolve()


def manifest_path_refs(project_root: Path, key: str) -> list[Path]:
    manifest = locate_flow_root(project_root) / "process-forge.yaml"
    data = load_yaml_document(manifest)
    refs = data.get(key) if isinstance(data, dict) else None
    paths: list[Path] = []
    if not isinstance(refs, list):
        return paths
    for item in refs:
        if isinstance(item, dict) and item.get("path"):
            paths.append(resolve_flow_reference(project_root, str(item["path"])))
    return paths


def collect_context_sources(project_root: Path, assignment: Path | None = None) -> list[dict[str, Any]]:
    flow_root = locate_flow_root(project_root)
    candidates: list[tuple[Path, str, bool]] = [
        (flow_root / "AGENTS.md", "agent-boot", True),
        (flow_root / "process-forge.yaml", "project-flow", True),
        (flow_root / "process-forge.local.yaml", "local-config", False),
        (project_root / "tools" / "processforge.py", "tool", False),
    ]
    candidates.extend((path, "process", False) for path in manifest_path_refs(project_root, "processes"))
    candidates.extend((path, "package", False) for path in manifest_path_refs(project_root, "packages"))
    for dirname, kind in [("processes", "process"), ("packages", "package")]:
        root = flow_root / dirname
        if root.is_dir():
            candidates.extend((path, kind, False) for path in sorted(root.glob("*.yaml")))
    template_root = flow_root / "templates"
    if template_root.is_dir():
        candidates.extend((path, "template", False) for path in sorted(template_root.glob("*.yaml")))
        candidates.extend((path, "template", False) for path in sorted(template_root.glob("*.md")))
    if assignment is not None:
        candidates.append((assignment, "assignment", True))

    seen: set[Path] = set()
    records: list[dict[str, Any]] = []
    for path, kind, required in candidates:
        resolved = path.resolve()
        if resolved in seen:
            continue
        seen.add(resolved)
        if required:
            reason = "required for session bootstrap" if kind != "assignment" else "required by context compile assignment"
            policy = "read_required"
        elif kind in {"process", "package", "template"}:
            reason = "available in broad project context; not loaded by default for workers"
            policy = "available"
        elif kind == "local-config":
            reason = "optional private local config"
            policy = "recommended_if_present"
        else:
            reason = "supporting context source"
            policy = "recommended"
        records.append(source_record(path, project_root, kind, required, reason, policy))
    return records


def source_fingerprints(sources: list[dict[str, Any]]) -> dict[str, str]:
    return {str(item["path"]): str(item.get("fingerprint", "missing")) for item in sources}


def source_texts(project_root: Path, sources: list[dict[str, Any]]) -> dict[str, str]:
    texts: dict[str, str] = {}
    for item in sources:
        path = project_root / str(item["path"])
        if path.is_file():
            texts[str(item["path"])] = path.read_text(encoding="utf-8", errors="replace")
    return texts


def values_from_registry_entry(entry: Any) -> list[str]:
    values: list[str] = []
    if not isinstance(entry, dict):
        return values
    for key in ("capability", "capabilities", "provides", "provides_capabilities"):
        value = entry.get(key)
        if isinstance(value, str):
            values.append(value)
        elif isinstance(value, list):
            values.extend(str(item) for item in value if isinstance(item, (str, int, float)))
        elif isinstance(value, dict):
            nested = value.get("capabilities")
            if isinstance(nested, list):
                values.extend(str(item) for item in nested if isinstance(item, (str, int, float)))
    return values


def load_registry_capability_providers(project_root: Path, workplace_manifest: Path | None = None) -> dict[str, str]:
    providers: dict[str, str] = {}

    def collect(registry_root: Path, scope: str) -> None:
        for rel_path, collection_key in [
            ("registries/tools.yaml", "tools"),
            ("registries/mcp.yaml", "mcp_servers"),
        ]:
            path = registry_root / rel_path
            if not path.is_file():
                continue
            try:
                data = load_answers(path)
            except SystemExit:
                continue
            entries = data.get(collection_key) if isinstance(data, dict) else None
            if not isinstance(entries, list):
                continue
            for entry in entries:
                if not isinstance(entry, dict):
                    continue
                if str(entry.get("status") or "available") in {"disabled", "missing"}:
                    continue
                provider_id = str(entry.get("id", rel_path))
                provider_ref = provider_id if scope == "project" else f"{scope}:{provider_id}"
                for capability in values_from_registry_entry(entry):
                    providers[capability] = provider_ref

    if workplace_manifest and workplace_manifest.is_file():
        collect(workplace_manifest.parent, "workplace")
    collect(locate_flow_root(project_root), "project")
    return providers


def resolve_capabilities(texts: dict[str, str], project_root: Path) -> dict[str, Any]:
    required: list[str] = []
    optional: list[str] = []
    for text in texts.values():
        required.extend(yaml_list_values(text, "required_capabilities"))
        optional.extend(yaml_list_values(text, "optional_capabilities"))
    required = sorted(set(item for item in required if item))
    optional = sorted(set(item for item in optional if item))
    registry_providers = load_registry_capability_providers(project_root)
    available = set(registry_providers)
    missing_required = [item for item in required if item not in available]
    missing_optional = [item for item in optional if item not in available]
    return {
        "required": required,
        "optional": optional,
        "missing_required": missing_required,
        "missing_optional": missing_optional,
        "providers": registry_providers,
    }


def load_yaml_document(path: Path) -> dict[str, Any]:
    if not path.is_file():
        return {}
    text = path.read_text(encoding="utf-8", errors="replace")
    try:
        import yaml  # type: ignore

        data = yaml.safe_load(text)
        return data if isinstance(data, dict) else {}
    except ModuleNotFoundError:
        return parse_simple_yaml(text)
    except Exception as exc:
        return {"__yaml_error__": f"{exc.__class__.__name__}: {exc}"}


def yaml_error(data: Any) -> str | None:
    if isinstance(data, dict) and isinstance(data.get("__yaml_error__"), str):
        return str(data["__yaml_error__"])
    return None


def load_policy_document(name: str, root: Path | None = None) -> dict[str, Any]:
    path = (root or ROOT) / "policies" / name
    if not path.is_file():
        return {}
    data = load_yaml_document(path)
    return data if isinstance(data, dict) and not yaml_error(data) else {}


def policy_entries(policy: dict[str, Any], key: str) -> list[dict[str, Any]]:
    values = policy.get(key)
    if not isinstance(values, list):
        return []
    entries: list[dict[str, Any]] = []
    for item in values:
        if isinstance(item, str):
            entries.append({"id": item})
        elif isinstance(item, dict):
            entries.append(item)
    return entries


def policy_id_matches(identifier: str, entry: dict[str, Any]) -> bool:
    if str(entry.get("id", "")) == identifier:
        return True
    pattern = entry.get("pattern")
    return bool(pattern and re.fullmatch(str(pattern), identifier))


def fingerprint_record(path: Path, project_root: Path, source_id: str, kind: str, *, private: bool = False, display_path: str | None = None) -> dict[str, Any]:
    exists = path.is_file()
    record: dict[str, Any] = {
        "id": source_id,
        "path": display_path or rel(path, project_root),
        "kind": kind,
        "checksum": sha256_file(path) if exists else "missing",
    }
    if private:
        record["private"] = True
    if not exists:
        record["exists"] = False
    return record


def collect_project_snapshot_sources(project_root: Path) -> list[dict[str, Any]]:
    flow_root = locate_flow_root(project_root)
    sources: list[dict[str, Any]] = [
        fingerprint_record(flow_root / "process-forge.yaml", project_root, "project_manifest", "manifest"),
    ]
    local_config = flow_root / "process-forge.local.yaml"
    if local_config.is_file():
        sources.append(fingerprint_record(local_config, project_root, "local_config", "local-config", private=True))
        workplace = find_local_workplace_manifest(local_config.read_text(encoding="utf-8", errors="replace"))
        if workplace:
            workplace_path = workplace.expanduser()
            if not workplace_path.is_absolute():
                workplace_path = (local_config.parent / workplace_path).resolve()
            sources.append(
                fingerprint_record(
                    workplace_path,
                    project_root,
                    "workplace_manifest",
                    "workplace",
                    private=True,
                    display_path="<private-workplace-manifest-ref>",
                )
            )
            workplace_root = workplace_path.parent
            for rel_path, kind in [
                ("registries/specializations.yaml", "workplace-specialization-registry"),
                ("registries/project-classifiers.yaml", "workplace-project-classifier-registry"),
                ("registries/process-packs.yaml", "workplace-process-pack-registry"),
                ("registries/tools.yaml", "workplace-tool-registry"),
                ("registries/mcp.yaml", "workplace-mcp-registry"),
                ("registries/templates.yaml", "workplace-template-registry"),
                ("registries/parameters.yaml", "workplace-parameter-registry"),
            ]:
                path = workplace_root / rel_path
                if path.is_file():
                    sources.append(
                        fingerprint_record(
                            path,
                            project_root,
                            safe_id(f"{kind}-{rel_path}", kind),
                            kind,
                            private=True,
                            display_path=f"<private-workplace-ref>/{rel_path}",
                        )
                    )
            for manifest_path, manifest in active_official_pack_records(workplace_path):
                pack_id = str(manifest.get("id") or manifest_path.parent.name)
                pack_sources = [manifest_path]
                pack_sources.extend(sorted((manifest_path.parent / "project-classifiers").glob("*.yaml")))
                for path in pack_sources:
                    sources.append(
                        fingerprint_record(
                            path,
                            project_root,
                            safe_id(f"official-pack-{pack_id}-{path.stem}", "official-pack"),
                            "official-process-pack",
                            private=True,
                            display_path=f"<distribution-pack>/{pack_id}/{path.relative_to(manifest_path.parent).as_posix()}",
                        )
                    )
            for dirname, kind in [
                ("specializations", "workplace-specialization"),
                ("specializations/user", "workplace-specialization"),
                ("specializations/custom", "workplace-specialization"),
                ("project-classifiers", "workplace-project-classifier"),
            ]:
                root = workplace_root / dirname
                if root.is_dir():
                    for path in sorted(item for item in root.glob("*.y*ml") if item.is_file()):
                        sources.append(
                            fingerprint_record(
                                path,
                                project_root,
                                safe_id(f"{kind}-{dirname}-{path.name}", kind),
                                kind,
                                private=True,
                                display_path=f"<private-workplace-ref>/{dirname}/{path.name}",
                            )
                        )

    for path in manifest_path_refs(project_root, "processes"):
        source_id = safe_id(f"process-{rel(path, project_root)}", "process-source")
        sources.append(fingerprint_record(path, project_root, source_id, "process"))
    for path in manifest_path_refs(project_root, "packages"):
        source_id = safe_id(f"package-{rel(path, project_root)}", "package-source")
        sources.append(fingerprint_record(path, project_root, source_id, "package"))

    if project_overrides_path(project_root).is_file():
        sources.append(fingerprint_record(project_overrides_path(project_root), project_root, "project-overrides", "project-overrides"))
    for parameter_path_candidate, source_id, private in [
        (flow_root / "parameters.yaml", "project-parameters", False),
        (flow_root / "parameters.local.yaml", "project-local-parameters", True),
    ]:
        if parameter_path_candidate.is_file():
            sources.append(fingerprint_record(parameter_path_candidate, project_root, source_id, "project-parameters", private=private))
    for dirname, kind in [
        ("processes", "process-override"),
        ("packages", "package-override"),
        ("registries", "registry"),
        ("project-classifiers", "project-classifier"),
        ("templates", "template-override"),
        ("specializations", "specialization"),
        ("specializations/overrides", "specialization-override"),
        ("tools/overrides", "tool-override"),
        ("mcp/overrides", "mcp-override"),
        ("knowledge", "project-knowledge"),
        ("rules", "project-rules"),
    ]:
        root = flow_root / dirname
        if root.is_dir():
            for path in sorted(item for item in root.rglob("*") if item.is_file() and item.suffix.lower() in {".yaml", ".yml", ".json", ".md"}):
                source_id = safe_id(f"{kind}-{rel(path, flow_root)}", f"{kind}-source")
                sources.append(fingerprint_record(path, project_root, source_id, kind))
    return sources


def scan_policy_from_manifest(manifest_data: dict[str, Any]) -> dict[str, Any]:
    policy = dict(DEFAULT_SCAN_POLICY)
    configured = manifest_data.get("scan_policy") if isinstance(manifest_data.get("scan_policy"), dict) else {}
    if "enabled" in configured:
        policy["enabled"] = bool(configured.get("enabled"))
    if isinstance(configured.get("exclude_roles"), list):
        policy["exclude_roles"] = [str(item) for item in configured["exclude_roles"] if item]
    if isinstance(configured.get("default_excludes"), list):
        policy["default_excludes"] = [str(item) for item in configured["default_excludes"] if item]
    allow_core = configured.get("allow_processforge_core_as_project") if isinstance(configured.get("allow_processforge_core_as_project"), dict) else {}
    merged_allow_core = dict(DEFAULT_SCAN_POLICY["allow_processforge_core_as_project"])
    merged_allow_core.update(allow_core)
    policy["allow_processforge_core_as_project"] = merged_allow_core
    return policy


def path_role_record(role: str, path: Path, project_root: Path, *, source: str, status: str = "available", path_id: str | None = None) -> dict[str, Any]:
    return {
        "role": role,
        "id": path_id or role,
        "path": rel(path.resolve(), project_root),
        "source": source,
        "status": status,
    }


def project_path_roles(project_root: Path, distribution_root: Path | None, workplace_manifest: Path | None, manifest_data: dict[str, Any]) -> list[dict[str, Any]]:
    flow_root = locate_flow_root(project_root)
    roles: list[dict[str, Any]] = [
        path_role_record("project_root", project_root, project_root, source="project"),
        path_role_record("project_pf_root", flow_root, project_root, source="project"),
        path_role_record("runtime_root", flow_root / "runtime", project_root, source="project", status="available" if (flow_root / "runtime").exists() else "missing"),
    ]
    if distribution_root:
        roles.append(path_role_record("distribution_root", distribution_root, project_root, source="workplace" if workplace_manifest else "project", status="available" if distribution_root.exists() else "missing"))
    elif looks_like_processforge_distribution(project_root):
        roles.append(path_role_record("distribution_root", project_root, project_root, source="project", status="available"))
    if workplace_manifest:
        workplace_root = workplace_manifest.parent
        roles.append(path_role_record("workplace_root", workplace_root, project_root, source="local-config", status="available" if workplace_root.exists() else "missing"))
        roles.append(path_role_record("package_cache", workplace_root / "cache", project_root, source="workplace", status="available" if (workplace_root / "cache").exists() else "missing"))
        knowledge_roots = load_workplace_registry(workplace_manifest, "knowledge_roots", "knowledge-roots.yaml")
        knowledge_entries = knowledge_roots.get("knowledge_roots") if isinstance(knowledge_roots, dict) else []
        if isinstance(knowledge_entries, list):
            for item in knowledge_entries:
                if not isinstance(item, dict):
                    continue
                raw_path = str(item.get("path") or item.get("path_ref") or "")
                if not raw_path:
                    continue
                knowledge_path = resolve_registry_relative_path(workplace_root, raw_path, workplace_manifest)
                roles.append(
                    path_role_record(
                        "knowledge_root",
                        knowledge_path,
                        project_root,
                        source="workplace-registry",
                        status="available" if knowledge_path.exists() else "missing",
                        path_id=str(item.get("id") or "knowledge-root"),
                    )
                )
    for configured in manifest_data.get("knowledge_roots", []) if isinstance(manifest_data.get("knowledge_roots"), list) else []:
        if not isinstance(configured, dict):
            continue
        raw_path = str(configured.get("path") or "")
        if raw_path:
            path = Path(raw_path).expanduser()
            if not path.is_absolute():
                path = (project_root / path).resolve()
            roles.append(path_role_record("knowledge_root", path, project_root, source="project-manifest", status="available" if path.exists() else "missing", path_id=str(configured.get("id") or "knowledge-root")))
    unique: list[dict[str, Any]] = []
    seen: set[tuple[str, str, str]] = set()
    for item in roles:
        key = (str(item["role"]), str(item["id"]), str(item["path"]))
        if key not in seen:
            seen.add(key)
            unique.append(item)
    return unique


def project_source_inventory_exclusion(path: Path, project_root: Path, roles: list[dict[str, Any]], policy: dict[str, Any], manifest_data: dict[str, Any]) -> dict[str, Any] | None:
    rel_path = rel(path, project_root)
    for pattern in policy.get("default_excludes", []):
        if fnmatch.fnmatch(rel_path, str(pattern)) or fnmatch.fnmatch("/" + rel_path, str(pattern).removeprefix("**")):
            return {"reason": "default_exclude", "pattern": str(pattern)}
    exclude_roles = set(policy.get("exclude_roles", []))
    allow_pf_core = project_type_allows_processforge_core(manifest_data)
    for role in roles:
        role_name = str(role.get("role"))
        if role_name not in exclude_roles:
            continue
        role_path_text = str(role.get("path") or "")
        role_path = Path(role_path_text)
        if not role_path.is_absolute():
            role_path = (project_root / role_path).resolve()
        if not path_is_relative_to(path, role_path):
            continue
        if role_name == "distribution_root" and role_path.resolve() == project_root.resolve() and allow_pf_core:
            continue
        return {"reason": "excluded_role", "role": role_name, "role_id": role.get("id"), "role_path": rel(role_path, project_root)}
    return None


def collect_project_source_inventory(project_root: Path, distribution_root: Path | None = None, workplace_manifest: Path | None = None, manifest_data: dict[str, Any] | None = None) -> dict[str, Any]:
    flow_root = locate_flow_root(project_root)
    if manifest_data is None:
        manifest_data = load_yaml_document(flow_root / "process-forge.yaml")
    policy = scan_policy_from_manifest(manifest_data)
    roles = project_path_roles(project_root, distribution_root, workplace_manifest, manifest_data)
    included: list[dict[str, Any]] = []
    excluded: list[dict[str, Any]] = []
    for path in sorted(item for item in project_root.rglob("*") if item.is_file()):
        exclusion = None if policy.get("enabled", True) else None
        if policy.get("enabled", True):
            exclusion = project_source_inventory_exclusion(path, project_root, roles, policy, manifest_data)
        record = {"path": rel(path, project_root)}
        if exclusion:
            excluded.append({**record, **exclusion})
        else:
            included.append(record)
    return {"scan_policy": policy, "path_roles": roles, "included": included, "excluded": excluded}


def available_platform_contract_records(workplace_manifest: Path | None, project_root: Path | None = None) -> list[dict[str, Any]]:
    if not workplace_manifest or not workplace_manifest.is_file():
        return []
    registry = load_workplace_registry(workplace_manifest, "platforms", "platforms.yaml")
    entries = registry.get("platforms") if isinstance(registry, dict) else []
    records: list[dict[str, Any]] = []
    if not isinstance(entries, list):
        return records
    for entry in entries:
        if not isinstance(entry, dict):
            continue
        if str(entry.get("status", "available")) in {"missing", "disabled"}:
            continue
        raw_id = str(entry.get("package_id") or entry.get("id") or "")
        if not raw_id:
            continue
        platform_id, contract_id = normalize_platform_id(raw_id)
        records.append(
            {
                "id": contract_id,
                "platform": platform_id,
                "registry_entry": str(entry.get("id") or platform_id),
                "source": str(entry.get("path") or ""),
                "status": "available",
            }
        )
    return sorted(records, key=lambda item: item["id"])


def package_root_entries(workplace_root: Path) -> list[dict[str, Any]]:
    registry = load_yaml_document(workplace_root / "registries" / "package-roots.yaml")
    entries = registry.get("package_roots") if isinstance(registry, dict) else None
    return [entry for entry in entries if isinstance(entry, dict)] if isinstance(entries, list) else []


def package_root_resolution_from_entry(workplace_root: Path, entry: dict[str, Any]) -> PackageRootResolution:
    root_id = str(entry.get("id", "package-root"))
    original = str(entry.get("path", ""))
    resolution = workplace_path_resolution(workplace_root, original)
    warnings = [str(item) for item in resolution.get("errors", [])]
    return PackageRootResolution(
        root_id=root_id,
        original_path=original,
        resolved_path=path_resolution_to_path(resolution),
        status=str(entry.get("status", "available")),
        warnings=warnings,
        fallback=False,
        entry=entry,
    )


def resolve_package_root(workplace_root: Path, package_root_id: str | None = None, *, mode: str = "read") -> PackageRootResolution:
    entries = package_root_entries(workplace_root)
    fallback = PackageRootResolution(
        root_id="fallback",
        original_path="packages",
        resolved_path=workplace_root / "packages",
        status="fallback",
        warnings=["WARN: registries/package-roots.yaml is missing or empty; using fallback <workplace-root>/packages"],
        fallback=True,
        entry=None,
    )
    if not entries:
        return fallback
    if package_root_id:
        for entry in entries:
            if str(entry.get("id")) == package_root_id:
                selected = package_root_resolution_from_entry(workplace_root, entry)
                break
        else:
            raise SystemExit(f"FAIL: package root '{package_root_id}' not found in registries/package-roots.yaml")
    else:
        available = [entry for entry in entries if str(entry.get("status", "available")) == "available"]
        default_entries = [entry for entry in available if bool(entry.get("default", False))]
        selected_entry = default_entries[0] if default_entries else (available[0] if available else None)
        if selected_entry is None:
            existing = [
                entry for entry in entries
                if entry.get("path") and package_root_resolution_from_entry(workplace_root, entry).resolved_path.exists()
            ]
            selected_entry = existing[0] if existing else entries[0]
        selected = package_root_resolution_from_entry(workplace_root, selected_entry)
    if selected.warnings:
        if mode == "write":
            if not selected.fallback:
                raise SystemExit("FAIL: package root path cannot be resolved: " + "; ".join(selected.warnings))
    if not selected.fallback and not selected.resolved_path.is_dir():
        selected.warnings.append(f"WARN: package root '{selected.root_id}' path does not exist: {selected.resolved_path.as_posix()}")
    if selected.entry is not None and str(selected.entry.get("writable", True)).lower() == "false" and mode == "write":
        raise SystemExit(f"FAIL: package root '{selected.root_id}' is not writable")
    if mode == "write" and not selected.fallback and not selected.resolved_path.is_dir():
        raise SystemExit(f"FAIL: selected package root '{selected.root_id}' path does not exist: {selected.resolved_path.as_posix()}")
    return selected


def package_path_candidates(root_path: Path, package_id: str) -> list[Path]:
    validated_id = validate_resource_id(package_id, "knowledge package")
    return [
        contained_resource_path(
            root_path,
            root_path / validated_id / "package.yaml",
            "knowledge package",
        ),
        contained_resource_path(
            root_path,
            root_path / f"{validated_id}.yaml",
            "knowledge package",
        ),
    ]


def resolve_package_path(workplace_root: Path, package_id: str, package_root_id: str | None = None, *, mode: str = "read") -> tuple[PackageRootResolution, Path]:
    validated_id = validate_resource_id(package_id, "knowledge package")
    root = resolve_package_root(workplace_root, package_root_id, mode=mode)
    return root, contained_resource_path(
        root.resolved_path,
        root.resolved_path / validated_id / "package.yaml",
        "knowledge package",
    )


def workplace_package_roots(workplace_manifest: Path | None) -> list[PackageRootResolution]:
    if not workplace_manifest or not workplace_manifest.is_file():
        return []
    workplace_root = workplace_manifest.parent
    return [package_root_resolution_from_entry(workplace_root, entry) for entry in package_root_entries(workplace_root)]


def workplace_package_root_paths(workplace_manifest: Path | None) -> list[Path]:
    return [root.resolved_path for root in workplace_package_roots(workplace_manifest)]


def package_manifest_candidates(project_root: Path, distribution_root: Path | None, workplace_manifest: Path | None = None) -> list[Path]:
    flow_root = locate_flow_root(project_root)
    candidates: list[Path] = []
    candidates.extend(manifest_path_refs(project_root, "packages"))
    roots: list[Path | None] = [
        flow_root / "packages",
        distribution_root / "packages" if distribution_root else None,
        (distribution_root or ROOT) / "seeds" / "knowledge-packages",
    ]
    roots.extend(workplace_package_root_paths(workplace_manifest))
    for root in roots:
        if root and root.is_dir():
            candidates.extend(sorted(root.glob("*.yaml")))
            candidates.extend(sorted(root.glob("*.yml")))
            candidates.extend(sorted(root.glob("*/package.yaml")))
            candidates.extend(sorted(root.glob("*/package.yml")))
    for process_pack_path, process_pack in active_official_pack_records(workplace_manifest):
        provided = process_pack.get("provides") if isinstance(process_pack.get("provides"), dict) else {}
        for package_id in as_list(provided.get("knowledge_packages")):
            if not package_id:
                continue
            package_path = process_pack_path.parent / "knowledge-packages" / f"{package_id}.yaml"
            if package_path.is_file():
                candidates.append(package_path)
    unique: list[Path] = []
    seen: set[Path] = set()
    for path in candidates:
        resolved = path.resolve()
        if resolved not in seen:
            seen.add(resolved)
            unique.append(resolved)
    return unique


def package_manifest_index(project_root: Path, distribution_root: Path | None, workplace_manifest: Path | None = None) -> dict[str, dict[str, Any]]:
    index: dict[str, dict[str, Any]] = {}
    duplicates: dict[str, list[str]] = {}
    workplace_roots = workplace_package_roots(workplace_manifest)
    for path in package_manifest_candidates(project_root, distribution_root, workplace_manifest):
        data = load_yaml_document(path)
        if not data or yaml_error(data):
            continue
        package_id = data.get("id")
        if not package_id:
            continue
        record = dict(data)
        record["__manifest_path"] = path
        for root in workplace_roots:
            try:
                path.relative_to(root.resolved_path)
                record["__package_root_id"] = root.root_id
                break
            except ValueError:
                continue
        if str(package_id) in index:
            duplicates.setdefault(str(package_id), [index[str(package_id)]["__manifest_path"].as_posix()]).append(path.as_posix())
        index[str(package_id)] = record
    if duplicates:
        index["__duplicates__"] = {"packages": duplicates}
    return index


def resource_record_from_package(package_id: str, resource: dict[str, Any], requirement: str, package_root_id: str | None = None) -> dict[str, Any]:
    resource_id = str(resource.get("id", "resource"))
    record: dict[str, Any] = {
        "id": f"{package_id}:{resource_id}",
        "resource_id": resource_id,
        "package": package_id,
        "requirement": requirement,
        "kind": str(resource.get("kind", "reference")),
        "title": str(resource.get("title", resource_id)),
        "load_policy": str(resource.get("load_policy", "on_demand")),
        "index_policy": str(resource.get("index_policy", "metadata")),
        "status": "indexed",
    }
    if "path_ref" in resource:
        record["path_ref"] = resource["path_ref"]
    elif "path" in resource:
        raw_path = str(resource.get("path", ""))
        if raw_path and Path(raw_path).is_absolute():
            record["path_ref"] = {"registry": "private_resource_paths", "id": resource_id}
            record["path_status"] = "private_absolute_path_redacted"
        elif raw_path:
            if package_root_id:
                record["path_ref"] = {"registry": "package_roots", "id": package_root_id, "relative_path": f"{package_id}/{raw_path}"}
            else:
                record["path_ref"] = {"package": package_id, "relative_path": raw_path}
    for key in ["version", "description", "versioning", "retention", "snapshot_behavior", "generation", "fingerprint", "instance_id", "current_marker_path_ref", "indexing", "selection"]:
        if key in resource:
            record[key] = resource[key]
    return record


def resolve_package_resources(
    project_root: Path,
    distribution_root: Path | None,
    workplace_manifest: Path | None,
    package_ids: list[str],
    required_package_ids: list[str] | None = None,
) -> list[dict[str, Any]]:
    package_index = package_manifest_index(project_root, distribution_root, workplace_manifest)
    resources: list[dict[str, Any]] = []
    required_set = set(required_package_ids or [])
    for package_id in package_ids:
        manifest = package_index.get(package_id)
        if not manifest:
            continue
        requirement = "required" if package_id in required_set else "recommended"
        package_resources = manifest.get("resources")
        if not isinstance(package_resources, list):
            continue
        for resource in package_resources:
            if isinstance(resource, dict):
                resources.append(resource_record_from_package(package_id, resource, requirement, manifest.get("__package_root_id")))
    return resources


RESOURCE_VERSIONING_MODES = {"multi_version", "single_current", "rolling_index", "external_live"}
RESOURCE_RETENTION_POLICIES = {"keep_versions", "keep_last_n", "replace_in_place", "external_only"}
SNAPSHOT_FRESHNESS_STATUSES = {"fresh", "fresh_with_updates", "stale", "broken"}


def deep_merge_dicts(base: dict[str, Any], override: dict[str, Any]) -> dict[str, Any]:
    result = dict(base)
    for key, value in override.items():
        if isinstance(value, dict) and isinstance(result.get(key), dict):
            result[key] = deep_merge_dicts(result[key], value)
        else:
            result[key] = value
    return result


def parameter_path(base: str, key: str) -> str:
    return f"{base}.{key}" if base else key


def parameter_list_item_path(base: str, item_id: str) -> str:
    return f"{base}[id={item_id}]" if base else f"[id={item_id}]"


def parameter_list_merges_by_id(base: Any, override: Any) -> bool:
    if not isinstance(base, list) or not isinstance(override, list):
        return False
    if not base or not override:
        return False
    combined = [*base, *override]
    return all(isinstance(item, dict) and item.get("id") not in (None, "") for item in combined)


def merge_parameter_value(base: Any, override: Any, source_id: str, path: str, provenance: dict[str, Any]) -> Any:
    if isinstance(base, dict) and isinstance(override, dict):
        return merge_parameter_maps(base, override, source_id, path, provenance)
    if parameter_list_merges_by_id(base, override):
        result = [copy.deepcopy(item) for item in base]
        index = {str(item["id"]): idx for idx, item in enumerate(result) if isinstance(item, dict) and item.get("id") not in (None, "")}
        for item in override:
            item_id = str(item["id"])
            item_path = parameter_list_item_path(path, item_id)
            if item.get("__delete__") is True or item.get("_delete") is True:
                if item_id in index:
                    del result[index[item_id]]
                    provenance[item_path] = {"source": source_id, "action": "delete"}
                    index = {str(value["id"]): idx for idx, value in enumerate(result) if isinstance(value, dict) and value.get("id") not in (None, "")}
                continue
            if item_id in index:
                result[index[item_id]] = merge_parameter_maps(result[index[item_id]], item, source_id, item_path, provenance)
            else:
                result.append(copy.deepcopy(item))
                provenance[item_path] = {"source": source_id, "action": "add"}
        return result
    provenance[path or "<root>"] = {"source": source_id, "action": "replace"}
    return copy.deepcopy(override)


def merge_parameter_maps(base: dict[str, Any], override: dict[str, Any], source_id: str, path: str = "", provenance: dict[str, Any] | None = None) -> dict[str, Any]:
    provenance = provenance if provenance is not None else {}
    result = copy.deepcopy(base)
    for key, value in override.items():
        key_text = str(key)
        key_path = parameter_path(path, key_text)
        if value is None:
            if key_text in result:
                del result[key_text]
                provenance[key_path] = {"source": source_id, "action": "delete"}
            continue
        if key_text in result:
            result[key_text] = merge_parameter_value(result[key_text], value, source_id, key_path, provenance)
        else:
            result[key_text] = copy.deepcopy(value)
            provenance[key_path] = {"source": source_id, "action": "add"}
    return result


def parameter_payload(data: dict[str, Any]) -> dict[str, Any]:
    parameters = data.get("parameters") if isinstance(data, dict) else {}
    return parameters if isinstance(parameters, dict) else {}


def parameter_source_record(source_id: str, layer: str, parameters: dict[str, Any], *, path: Path | None = None, project_root: Path | None = None, private: bool = False, display_path: str | None = None) -> dict[str, Any]:
    record: dict[str, Any] = {
        "id": source_id,
        "layer": layer,
        "keys": sorted(str(key) for key in parameters),
        "private": private,
    }
    if path:
        # Private workplace sources may contribute metadata to a public
        # snapshot, but never their absolute filesystem location. Callers can
        # supply a more specific stable marker through `display_path`.
        record["path"] = display_path or (
            rel(path, project_root)
            if project_root and path_is_relative_to(path, project_root)
            else "<private-source-ref>"
            if private
            else str(path)
        )
        record["checksum"] = "sha256:" + sha256_file(path) if path.is_file() else "missing"
    return record


def workplace_parameter_paths(workplace_manifest: Path | None) -> list[Path]:
    if not workplace_manifest or not workplace_manifest.is_file():
        return []
    workplace_root = workplace_manifest.parent
    workplace_data = load_yaml_document(workplace_manifest)
    registries = workplace_data.get("registries") if isinstance(workplace_data.get("registries"), dict) else {}
    paths: list[Path] = []
    raw_registry = registries.get("parameters") if isinstance(registries, dict) else None
    if raw_registry:
        paths.append(resolve_registry_relative_path(workplace_root, str(raw_registry), workplace_manifest))
    default_path = workplace_root / "registries" / "parameters.yaml"
    if default_path not in paths:
        paths.append(default_path)
    return paths


def add_parameter_source(
    result: dict[str, Any],
    *,
    source_id: str,
    layer: str,
    parameters: dict[str, Any],
    path: Path | None = None,
    project_root: Path | None = None,
    private: bool = False,
    display_path: str | None = None,
) -> None:
    if not parameters:
        return
    result["sources"].append(parameter_source_record(source_id, layer, parameters, path=path, project_root=project_root, private=private, display_path=display_path))
    result["resolved_parameters"] = merge_parameter_maps(result["resolved_parameters"], parameters, source_id, provenance=result["provenance"])


def process_parameters_from_path(path: Path) -> tuple[dict[str, Any], dict[str, dict[str, Any]]]:
    data = load_yaml_document(path)
    stages = data.get("stages") if isinstance(data.get("stages"), list) else []
    stage_parameters: dict[str, dict[str, Any]] = {}
    for stage in stages:
        if not isinstance(stage, dict) or not stage.get("id"):
            continue
        params = parameter_payload(stage)
        if params:
            stage_parameters[str(stage["id"])] = params
    return parameter_payload(data), stage_parameters


def resolve_project_parameters(
    project_root: Path,
    workplace_manifest: Path | None,
    manifest_data: dict[str, Any],
    platform_resolution: dict[str, Any],
    specialization_ids: list[str],
    platform_ids: list[str],
    process_id: str | None,
    process_paths: list[Path],
) -> dict[str, Any]:
    flow_root = locate_flow_root(project_root)
    result: dict[str, Any] = {
        "status": "resolved",
        "resolved_parameters": {},
        "sources": [],
        "provenance": {},
        "conflicts": [],
    }
    if workplace_manifest and workplace_manifest.is_file():
        workplace_data = load_yaml_document(workplace_manifest)
        add_parameter_source(
            result,
            source_id="workplace-manifest",
            layer="workplace",
            parameters=parameter_payload(workplace_data),
            path=workplace_manifest,
            project_root=project_root,
            private=True,
            display_path="<private-workplace-manifest-ref>",
        )
        for index, path in enumerate(workplace_parameter_paths(workplace_manifest)):
            data = load_yaml_document(path)
            add_parameter_source(
                result,
                source_id=f"workplace-parameters-{index + 1}",
                layer="workplace",
                parameters=parameter_payload(data),
                path=path,
                project_root=project_root,
                private=True,
                display_path=f"<private-workplace-ref>/{path.relative_to(workplace_manifest.parent).as_posix()}" if path_is_relative_to(path, workplace_manifest.parent) else "<private-workplace-parameters-ref>",
            )
    for contract in platform_resolution.get("contracts", []) if isinstance(platform_resolution.get("contracts"), list) else []:
        if isinstance(contract, dict):
            add_parameter_source(
                result,
                source_id=f"platform:{contract.get('id', 'unknown')}",
                layer="platform",
                parameters=parameter_payload(contract),
            )
    index = specialization_manifest_index(workplace_manifest, project_root)
    for specialization_id in [specialization_resource_id(item) for item in specialization_ids if str(item)]:
        spec = index.get(specialization_id)
        if not isinstance(spec, dict):
            continue
        for override_entry in project_specialization_override_entries(project_root, specialization_id):
            mode = str(override_entry.get("mode") or "extension")
            if mode not in PROJECT_OVERRIDE_MODES:
                result["conflicts"].append({"id": specialization_id, "kind": "specialization", "reason": f"unsupported project override mode: {mode}"})
                continue
            overlay = load_project_override_document(project_root, override_entry)
            if overlay:
                spec, _overlay_notes = apply_specialization_overlay(spec, overlay, mode)
        add_parameter_source(
            result,
            source_id=f"specialization:{specialization_id}",
            layer="specialization",
            parameters=parameter_payload(spec),
            path=spec.get("__manifest_path") if isinstance(spec.get("__manifest_path"), Path) else None,
            project_root=project_root,
            private=str(spec.get("__source") or "") == "workplace",
        )
        for binding_index, binding in enumerate(spec.get("platform_bindings", []) if isinstance(spec.get("platform_bindings"), list) else []):
            if isinstance(binding, dict) and platform_binding_matches(binding, platform_ids, platform_resolution.get("platform_stack", []), process_id):
                add_parameter_source(
                    result,
                    source_id=f"specialization:{specialization_id}:binding:{binding_index + 1}",
                    layer="specialization",
                    parameters=parameter_payload(binding),
                )
    add_parameter_source(result, source_id="project-manifest", layer="project", parameters=parameter_payload(manifest_data), path=flow_root / "process-forge.yaml", project_root=project_root)
    project_parameters = flow_root / "parameters.yaml"
    add_parameter_source(result, source_id="project-parameters", layer="project", parameters=parameter_payload(load_yaml_document(project_parameters)), path=project_parameters, project_root=project_root)
    local_config = flow_root / "process-forge.local.yaml"
    local_data = load_yaml_document(local_config)
    local_overrides = local_data.get("overrides") if isinstance(local_data.get("overrides"), dict) else {}
    add_parameter_source(result, source_id="project-local-overrides", layer="project", parameters=parameter_payload(local_overrides), path=local_config, project_root=project_root, private=True)
    project_local_parameters = flow_root / "parameters.local.yaml"
    add_parameter_source(result, source_id="project-local-parameters", layer="project", parameters=parameter_payload(load_yaml_document(project_local_parameters)), path=project_local_parameters, project_root=project_root, private=True)
    for index, path in enumerate(process_paths):
        parameters, _stage_parameters = process_parameters_from_path(path)
        add_parameter_source(result, source_id=f"process:{path.stem}:{index + 1}", layer="process", parameters=parameters, path=path, project_root=project_root)
    if result["conflicts"]:
        result["status"] = "conflict"
    return result


def resolve_assignment_parameters(project_root: Path, snapshot: dict[str, Any], assignment_metadata: dict[str, Any]) -> dict[str, Any]:
    base = snapshot.get("resolved_parameters") if isinstance(snapshot.get("resolved_parameters"), dict) else {}
    snapshot_resolution = snapshot.get("parameter_resolution") if isinstance(snapshot.get("parameter_resolution"), dict) else {}
    result: dict[str, Any] = {
        "status": "resolved",
        "resolved_parameters": copy.deepcopy(base),
        "sources": copy.deepcopy(snapshot_resolution.get("sources", [])) if isinstance(snapshot_resolution.get("sources"), list) else [],
        "provenance": copy.deepcopy(snapshot_resolution.get("provenance", {})) if isinstance(snapshot_resolution.get("provenance"), dict) else {},
        "conflicts": copy.deepcopy(snapshot_resolution.get("conflicts", [])) if isinstance(snapshot_resolution.get("conflicts"), list) else [],
    }
    process_ref = assignment_metadata.get("process")
    process_id = str(process_ref.get("id") if isinstance(process_ref, dict) else process_ref or "")
    stage_id = str(assignment_metadata.get("stage") or "")
    if process_id:
        try:
            process_path = resolve_process_definition(project_root, process_id).path
            process_parameters, stage_parameters = process_parameters_from_path(process_path)
            add_parameter_source(result, source_id=f"assignment-process:{process_id}", layer="process", parameters=process_parameters, path=process_path, project_root=project_root)
            if stage_id and stage_id in stage_parameters:
                add_parameter_source(result, source_id=f"assignment-stage:{process_id}:{stage_id}", layer="stage", parameters=stage_parameters[stage_id], path=process_path, project_root=project_root)
        except SystemExit:
            result["conflicts"].append({"id": process_id, "kind": "process", "reason": "assignment process parameters could not be loaded"})
    add_parameter_source(result, source_id="assignment", layer="task", parameters=parameter_payload(assignment_metadata))
    if result["conflicts"]:
        result["status"] = "conflict"
    return result


def default_context_policy(manifest_data: dict[str, Any]) -> dict[str, Any]:
    coordination = manifest_data.get("coordination") if isinstance(manifest_data.get("coordination"), dict) else {}
    organized = str(coordination.get("mode") or "inherit") == "organized"
    policy = {
        "on_session_start": {
            "check_freshness": True,
            "check_update_candidates": "if_due",
            "if_fresh": "continue",
            "if_fresh_with_updates": "notify",
            "if_stale": "notify_director" if organized else "ask_operator",
            "if_broken": "block",
        },
        "auto_refresh": {
            "enabled": False,
            "allow_patch": True,
            "allow_minor": False,
            "allow_major": False,
            "allow_rolling_resources": False,
        },
        "active_run_behavior": {
            "existing_capsules": "pin_existing",
            "new_capsules": "require_fresh_snapshot",
        },
        "organized_mode": {
            "stale_snapshot_action": "notify_director" if organized else "needs_operator",
        },
    }
    project_policy = manifest_data.get("context_policy") if isinstance(manifest_data.get("context_policy"), dict) else {}
    return deep_merge_dicts(policy, project_policy)


def requirements_fingerprints(flow_root: Path, project_root: Path) -> dict[str, str]:
    result: dict[str, str] = {}
    for key, path in {
        "process_forge_yaml": flow_root / "process-forge.yaml",
        "process_forge_local_yaml": flow_root / "process-forge.local.yaml",
    }.items():
        result[key] = "sha256:" + sha256_file(path) if path.is_file() else "missing"
    return result


def resource_versioning_policy(resource: dict[str, Any]) -> tuple[dict[str, Any], dict[str, Any], dict[str, Any]]:
    versioning = resource.get("versioning") if isinstance(resource.get("versioning"), dict) else {}
    mode = str(versioning.get("mode") or ("multi_version" if resource.get("version") else "rolling_index"))
    if mode not in RESOURCE_VERSIONING_MODES:
        mode = "rolling_index"
    versioning = {
        "mode": mode,
        "version_field": str(versioning.get("version_field") or "version"),
        "instance_id_template": str(versioning.get("instance_id_template") or "{id}@{version}"),
    }
    retention = resource.get("retention") if isinstance(resource.get("retention"), dict) else {}
    default_retention = "keep_versions" if mode == "multi_version" else ("external_only" if mode == "external_live" else "replace_in_place")
    policy = str(retention.get("policy") or default_retention)
    if policy not in RESOURCE_RETENTION_POLICIES:
        policy = default_retention
    retention = {"policy": policy, "keep_last_n": retention.get("keep_last_n")}
    behavior = resource.get("snapshot_behavior") if isinstance(resource.get("snapshot_behavior"), dict) else {}
    reproducibility = "exact" if mode == "multi_version" and policy == "keep_versions" else ("non_reproducible" if mode == "external_live" else "best_effort")
    snapshot_behavior = {
        "on_new_version": str(behavior.get("on_new_version") or ("notify_only" if mode == "multi_version" else "mark_stale")),
        "on_current_generation_changed": str(behavior.get("on_current_generation_changed") or ("notify_only" if mode == "multi_version" else "mark_stale")),
        "on_instance_missing": str(behavior.get("on_instance_missing") or "broken"),
        "reproducibility": str(behavior.get("reproducibility") or reproducibility),
    }
    return versioning, retention, snapshot_behavior


def resource_declared_version(resource: dict[str, Any], versioning: dict[str, Any]) -> str:
    field = str(versioning.get("version_field") or "version")
    value = resource.get(field)
    if value is None:
        value = resource.get("version") or resource.get("resolved_version")
    return str(value or "")


def resource_generation(resource: dict[str, Any]) -> str:
    for key in ["generation", "resolved_generation", "updated_at", "generated_at"]:
        if resource.get(key) is not None:
            return str(resource.get(key))
    fingerprint = resource.get("fingerprint") if isinstance(resource.get("fingerprint"), dict) else {}
    if fingerprint.get("value"):
        return str(fingerprint.get("value"))
    return ""


def resource_fingerprint(resource: dict[str, Any], versioning: dict[str, Any], generation: str) -> dict[str, str]:
    fingerprint = resource.get("fingerprint") if isinstance(resource.get("fingerprint"), dict) else {}
    if fingerprint.get("value"):
        value = str(fingerprint.get("value"))
        return {"type": str(fingerprint.get("type") or "declared"), "value": value if value.startswith("sha256:") else "sha256:" + value}
    stable = {
        "id": resource.get("id"),
        "kind": resource.get("kind"),
        "version": resource_declared_version(resource, versioning),
        "generation": generation,
        "path_ref": resource.get("path_ref"),
    }
    return {"type": "resource_record_sha256", "value": "sha256:" + hashlib.sha256(json.dumps(stable, sort_keys=True, ensure_ascii=False).encode("utf-8")).hexdigest()}


def resource_instance_id(resource: dict[str, Any], versioning: dict[str, Any], version: str, generation: str) -> str:
    explicit = resource.get("instance_id")
    if isinstance(explicit, str) and explicit.strip():
        return explicit
    template = str(versioning.get("instance_id_template") or "{id}@{version}")
    token_value = version or generation or "current"
    try:
        return template.format(id=resource.get("id"), version=token_value, generation=generation or token_value)
    except (KeyError, ValueError):
        return f"{resource.get('id')}@{token_value}"


def resolved_resource_instance(resource: dict[str, Any]) -> dict[str, Any]:
    versioning, retention, behavior = resource_versioning_policy(resource)
    public_id = str(resource.get("id") or resource.get("resource_id") or "")
    version = resource_declared_version(resource, versioning)
    generation = resource_generation(resource)
    fingerprint = resource_fingerprint(resource, versioning, generation)
    reproducibility = str(behavior.get("reproducibility") or "best_effort")
    result: dict[str, Any] = {
        "id": public_id,
        "kind": str(resource.get("kind") or "reference"),
        "package_id": str(resource.get("package") or resource.get("package_id") or ""),
        "requirement": str(resource.get("requirement") or "recommended"),
        "versioning_mode": versioning["mode"],
        "retention_policy": retention["policy"],
        "instance_id": resource_instance_id({**resource, "id": public_id}, versioning, version, generation),
        "path_ref": resource.get("path_ref"),
        "fingerprint": fingerprint,
        "reproducibility": {"level": reproducibility},
        "snapshot_behavior": behavior,
    }
    if version:
        result["resolved_version"] = version
    if generation:
        result["resolved_generation"] = generation
        result["current_marker_path_ref"] = resource.get("current_marker_path_ref") or resource.get("path_ref")
    if reproducibility != "exact":
        result["reproducibility"]["reason"] = f"resource retention policy is {retention['policy']}"
    for key in ("resource_id", "title", "description", "load_policy", "index_policy", "indexing", "selection"):
        if key in resource:
            result[key] = copy.deepcopy(resource[key])
    return result


def context_requirements_from_manifest(manifest_data: dict[str, Any]) -> dict[str, Any]:
    requirements = manifest_data.get("context_requirements") if isinstance(manifest_data.get("context_requirements"), dict) else {}
    return {
        "knowledge_packages": requirements.get("knowledge_packages", []) if isinstance(requirements.get("knowledge_packages"), list) else [],
        "knowledge_resources": requirements.get("knowledge_resources", []) if isinstance(requirements.get("knowledge_resources"), list) else [],
        "resource_selection": requirements.get("resource_selection", {}) if isinstance(requirements.get("resource_selection"), dict) else {},
        "template_packages": requirements.get("template_packages", []) if isinstance(requirements.get("template_packages"), list) else [],
        "templates": requirements.get("templates", []) if isinstance(requirements.get("templates"), list) else [],
        "tools": requirements.get("tools", []) if isinstance(requirements.get("tools"), list) else [],
        "platform_contracts": requirements.get("platform_contracts", []) if isinstance(requirements.get("platform_contracts"), list) else [],
    }


def version_satisfies_simple_constraint(version: str, constraint: str) -> bool:
    text = (constraint or "").strip()
    if not text or text in {"*", "latest"}:
        return True
    version_key = semantic_version_key(version)
    if version_key[0] != 0:
        return version == text
    version_tuple = version_key[1]
    assert isinstance(version_tuple, tuple)
    for part in text.split():
        if part.startswith(">="):
            other = semantic_version_key(part[2:])[1]
            if isinstance(other, tuple) and version_tuple < other:
                return False
        elif part.startswith(">"):
            other = semantic_version_key(part[1:])[1]
            if isinstance(other, tuple) and version_tuple <= other:
                return False
        elif part.startswith("<="):
            other = semantic_version_key(part[2:])[1]
            if isinstance(other, tuple) and version_tuple > other:
                return False
        elif part.startswith("<"):
            other = semantic_version_key(part[1:])[1]
            if isinstance(other, tuple) and version_tuple >= other:
                return False
        elif part.startswith("^"):
            base = semantic_version_key(part[1:])[1]
            if isinstance(base, tuple) and (version_tuple < base or version_tuple[0] != base[0]):
                return False
        elif part == "||":
            continue
        elif version != part:
            return False
    return True


def version_prefix(version: str) -> str:
    key = semantic_version_key(version)
    if key[0] != 0 or not isinstance(key[1], tuple) or len(key[1]) < 2:
        return ""
    return f"{key[1][0]}.{key[1][1]}"


def inferred_platform_versions(package_ids: list[str], selection: dict[str, Any]) -> list[str]:
    configured = selection.get("platform_versions") if isinstance(selection.get("platform_versions"), dict) else {}
    versions = [str(value).strip() for value in configured.values() if str(value).strip()]
    if versions:
        return sorted(set(versions))
    inferred: list[str] = []
    for package_id in package_ids:
        match = re.search(r"(?:^|[-_.])v?(\d+)[-_.](\d+)(?:$|[-_.])", package_id)
        if match:
            inferred.append(f"{match.group(1)}.{match.group(2)}")
    return sorted(set(inferred))


def legacy_resource_requirements(
    package_resources: list[dict[str, Any]],
    *,
    direct_package_ids: list[str],
    selection: dict[str, Any],
) -> list[dict[str, Any]]:
    """Derive a narrow migration set for manifests created before selectors existed."""

    direct = set(direct_package_ids)
    target_versions = inferred_platform_versions(direct_package_ids, selection)
    requirements: list[dict[str, Any]] = []
    compatible: dict[str, dict[str, Any]] = {}
    for resource in package_resources:
        package_id = str(resource.get("package") or resource.get("package_id") or "")
        resource_id = str(resource.get("id") or resource.get("resource_id") or "")
        version = str(resource.get("version") or resource.get("generation") or "")
        if package_id in direct or package_id.startswith("project."):
            requirements.append({"id": resource_id, "preferred_version": version, "required": True, "selection_reason": "legacy_direct_package"})
            continue
        if target_versions and version_prefix(version) in target_versions:
            logical_id = str(resource.get("resource_id") or resource_id)
            previous = compatible.get(logical_id)
            if previous is None or semantic_version_key(version) > semantic_version_key(str(previous.get("version") or previous.get("generation") or "")):
                compatible[logical_id] = resource
    for resource in compatible.values():
        requirements.append(
            {
                "id": str(resource.get("id") or resource.get("resource_id") or ""),
                "preferred_version": str(resource.get("version") or resource.get("generation") or ""),
                "required": True,
                "selection_reason": "legacy_compatible_version",
            }
        )
    return requirements


def select_resolved_knowledge_resources(
    package_resources: list[dict[str, Any]],
    requirements: dict[str, Any],
    *,
    direct_package_ids: list[str] | None = None,
) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    resource_requirements = [item for item in requirements.get("knowledge_resources", []) if isinstance(item, dict)]
    selection = requirements.get("resource_selection") if isinstance(requirements.get("resource_selection"), dict) else {}
    if not resource_requirements:
        resource_requirements = legacy_resource_requirements(
            package_resources,
            direct_package_ids=direct_package_ids or [],
            selection=selection,
        )
        mode = "legacy_narrow"
    else:
        mode = "explicit"
    resolved: list[dict[str, Any]] = []
    used_keys: set[tuple[str, str]] = set()
    provenance: list[dict[str, Any]] = []
    for requirement in resource_requirements:
        resource_id = str(requirement.get("id") or "")
        candidates = [
            resource
            for resource in package_resources
            if resource_id in {str(resource.get("resource_id") or ""), str(resource.get("id") or "")}
        ]
        preferred = str(requirement.get("preferred_version") or "")
        constraint = str(requirement.get("constraint") or "")
        if preferred:
            candidates = [resource for resource in candidates if str(resource.get("version") or "") == preferred] or candidates
        if constraint:
            candidates = [resource for resource in candidates if version_satisfies_simple_constraint(str(resource.get("version") or ""), constraint)] or candidates
        candidates.sort(key=lambda resource: semantic_version_key(str(resource.get("version") or resource_generation(resource) or "")))
        if candidates:
            selected = candidates[-1]
            selected = dict(selected)
            selected["requirement"] = "required" if bool(requirement.get("required", True)) else "recommended"
            instance = resolved_resource_instance(selected)
            key = (instance["id"], instance["instance_id"])
            if key not in used_keys:
                instance["selection"] = {
                    "mode": mode,
                    "reason": str(requirement.get("selection_reason") or "explicit_selector"),
                    "preferred_version": preferred or None,
                    "constraint": constraint or None,
                }
                resolved.append(instance)
                used_keys.add(key)
            provenance.append({
                "selector": {key: value for key, value in requirement.items() if key in {"id", "preferred_version", "constraint", "required", "selection_reason"}},
                "resource_id": instance["id"],
                "instance_id": instance["instance_id"],
                "status": "selected",
            })
        else:
            provenance.append({"selector": {key: value for key, value in requirement.items() if key in {"id", "preferred_version", "constraint", "required", "selection_reason"}}, "status": "unresolved"})
    return resolved, {
        "mode": mode,
        "target_versions": inferred_platform_versions(direct_package_ids or [], selection),
        "selected_count": len(resolved),
        "available_count": len(package_resources),
        "provenance": provenance,
    }


def selected_resource_indexing(resource: dict[str, Any], selection: dict[str, Any]) -> dict[str, Any]:
    indexing = resource.get("indexing") if isinstance(resource.get("indexing"), dict) else {}
    if indexing:
        return copy.deepcopy(indexing)
    if str(selection.get("mode") or "") == "legacy_narrow" and str(resource.get("kind") or "") == "documentation":
        return {
            "enabled": True,
            "mode": "fulltext",
            "fields": ["title", "description", "version", "path"],
            "sources": [{"path": ".", "mode": "fulltext", "include": ["**/*.md", "**/*.txt", "**/*.rst"], "role": "documentation"}],
            "migration": "legacy_documentation_fulltext",
        }
    return {
        "enabled": True,
        "mode": "metadata",
        "fields": ["title", "description", "version", "path"],
        "sources": [{"path": ".", "mode": "metadata", "role": str(resource.get("kind") or "knowledge")}],
    }


def aggregate_reproducibility(resources: list[dict[str, Any]]) -> dict[str, Any]:
    levels = [str(item.get("reproducibility", {}).get("level", "best_effort")) for item in resources if isinstance(item, dict)]
    reasons = sorted({str(item.get("reproducibility", {}).get("reason")) for item in resources if isinstance(item, dict) and item.get("reproducibility", {}).get("reason")})
    if not levels or all(level == "exact" for level in levels):
        level = "exact"
    elif any(level == "non_reproducible" for level in levels):
        level = "non_reproducible"
    elif any(level == "best_effort" for level in levels):
        level = "best_effort"
    else:
        level = "mixed"
    return {"level": level, "reasons": reasons}


HEAVY_RESOURCE_KINDS = {
    "source_tree",
    "documentation",
    "article_collection",
    "note_collection",
    "snippet_collection",
    "example_collection",
    "dataset",
    "media_reference",
}


def resource_management_root(workplace_root: Path) -> Path:
    return workplace_root / "runtime" / "resource-management"


def resource_management_slug(command: str, object_id: str) -> str:
    stamp = now_utc().replace(":", "").replace("-", "").replace("Z", "z")
    return f"{stamp}-{safe_id(command, 'command')}-{safe_id(object_id, 'resource')}"


def write_resource_management_artifact(workplace_root: Path, kind: str, slug: str, content: str) -> Path:
    target = resource_management_root(workplace_root) / kind / f"{slug}.yaml"
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(ensure_trailing_newline(content), encoding="utf-8")
    return target


def write_resource_management_report(workplace_root: Path, slug: str, title: str, lines: list[str]) -> Path:
    target = resource_management_root(workplace_root) / "reports" / f"{slug}.md"
    target.parent.mkdir(parents=True, exist_ok=True)
    body = ["# " + title, "", *lines, ""]
    target.write_text("\n".join(body), encoding="utf-8")
    return target


def resource_management_event(
    *,
    scope: str,
    command: str,
    event_type: str,
    target: dict[str, Any],
    status: str,
    message: str,
    event_id: str | None = None,
) -> dict[str, Any]:
    return {
        "schema_version": 1,
        "event_id": event_id or f"evt_{uuid.uuid4().hex}",
        "event_type": event_type,
        "occurred_at": now_utc(),
        "scope": scope,
        "source": {"command": command, "actor_type": "agent"},
        "target": target,
        "result": {"status": status, "message": message},
    }


def append_workplace_resource_event(workplace_root: Path, event: dict[str, Any]) -> Path:
    target = workplace_root / "runtime" / "events" / "events.ndjson"
    target.parent.mkdir(parents=True, exist_ok=True)
    event_id = str(event.get("event_id") or "")
    if event_id and target.is_file():
        for line in target.read_text(encoding="utf-8", errors="replace").splitlines():
            try:
                existing = json.loads(line)
            except json.JSONDecodeError:
                continue
            if isinstance(existing, dict) and str(existing.get("event_id") or "") == event_id:
                return target
    target.write_text(
        (target.read_text(encoding="utf-8") if target.is_file() else "")
        + json.dumps(redact_telemetry_value(event), ensure_ascii=False, sort_keys=True)
        + "\n",
        encoding="utf-8",
    )
    mark_search_index_dirty_after_resource_event(workplace_root, event)
    return target


def mark_search_index_dirty_after_resource_event(workplace_root: Path, event: dict[str, Any]) -> None:
    result = event.get("result") if isinstance(event.get("result"), dict) else {}
    status = str(result.get("status") or "")
    if status in {"dry_run", "skipped", "passed", "failed"}:
        return
    try:
        from processforge_core.local_resource_search import ResourceSearchIndex

        ResourceSearchIndex(workplace_root, workplace_root=workplace_root).mark_dirty(reason=str(event.get("event_type") or "resource_event"))
    except Exception:
        return


def default_load_policy(kind: str, requested: str | None = None) -> str:
    if requested:
        return requested
    return "on_demand" if kind in HEAVY_RESOURCE_KINDS else "when_relevant"


def default_index_policy(kind: str, requested: str | None = None) -> str:
    if requested:
        return requested
    if kind in {"source_tree"}:
        return "symbols"
    if kind in {"documentation", "article", "article_collection"}:
        return "full_text"
    return "metadata"


def path_ref_for_known_root(workplace_root: Path, raw_path: str) -> dict[str, Any] | None:
    resource_resolution = workplace_path_resolution(workplace_root, raw_path)
    if resource_resolution.get("errors"):
        return None
    resource_resolved = normalize_path_string(str(resource_resolution.get("resolved", ""))).rstrip("/")
    registry_specs = [
        ("knowledge_roots", "knowledge-roots.yaml", "knowledge_roots"),
        ("template_roots", "templates.yaml", "template_roots"),
        ("package_roots", "package-roots.yaml", "package_roots"),
    ]
    for registry_name, registry_file, collection_key in registry_specs:
        registry = load_yaml_document(workplace_root / "registries" / registry_file)
        entries = registry.get(collection_key) if isinstance(registry, dict) else None
        if not isinstance(entries, list):
            continue
        for entry in entries:
            if not isinstance(entry, dict) or not entry.get("id") or not entry.get("path"):
                continue
            root_resolution = workplace_path_resolution(workplace_root, str(entry["path"]))
            if root_resolution.get("errors"):
                continue
            root_resolved = normalize_path_string(str(root_resolution.get("resolved", ""))).rstrip("/")
            if resource_resolved == root_resolved or resource_resolved.startswith(root_resolved + "/"):
                path_ref: dict[str, Any] = {"registry": registry_name, "id": str(entry["id"])}
                if resource_resolved != root_resolved:
                    path_ref["relative_path"] = resource_resolved[len(root_resolved) + 1 :]
                return path_ref
    return None


def ensure_private_resource_path(workplace_root: Path, resource_id: str, raw_path: str) -> Path:
    target = workplace_root / "registries" / "private-resource-paths.yaml"
    entry = {
        "id": resource_id,
        "label": resource_id.replace("-", " ").title(),
        "path": raw_path,
        "visibility": "private",
        "status": "available",
    }
    upsert_registry_entry(target, "private_resource_paths", entry)
    return target


def public_resource_path_ref(resource_id: str, raw_path: str | None, source_url: str | None = None, workplace_root: Path | None = None) -> dict[str, Any]:
    if source_url:
        return {"registry": "external_resources", "id": resource_id, "url": source_url}
    if raw_path:
        if workplace_root:
            known_ref = path_ref_for_known_root(workplace_root, raw_path)
            if known_ref:
                return known_ref
        if path_string_is_absolute(raw_path) or PATH_CONSTANT_PATTERN.search(raw_path):
            return {"registry": "private_resource_paths", "id": resource_id}
        return {"package": "self", "relative_path": raw_path}
    return {"registry": "external_resources", "id": resource_id}


def normalize_resource_record(resource: dict[str, Any], package_id: str, workplace_root: Path | None = None, *, register_private_path: bool = False) -> dict[str, Any]:
    record = dict(resource)
    resource_id = safe_id(str(record.get("id") or record.get("title") or "resource"), "resource")
    kind = str(record.get("kind") or "reference")
    raw_path = str(record.get("path")) if record.get("path") else None
    source = record.get("source") if isinstance(record.get("source"), dict) else {}
    source_url = str(source.get("url") or record.get("url") or "") or None
    record["id"] = resource_id
    record["kind"] = kind
    record["title"] = str(record.get("title") or resource_id.replace("-", " ").title())
    record["load_policy"] = default_load_policy(kind, str(record.get("load_policy")) if record.get("load_policy") else None)
    record["index_policy"] = default_index_policy(kind, str(record.get("index_policy")) if record.get("index_policy") else None)
    if "path_ref" not in record:
        record["path_ref"] = public_resource_path_ref(resource_id, raw_path, source_url, workplace_root)
    if raw_path and (path_string_is_absolute(raw_path) or PATH_CONSTANT_PATTERN.search(raw_path)):
        record["path_status"] = "resolved_private_path_hidden"
        resolution = workplace_path_resolution(workplace_root, raw_path) if workplace_root else None
        if resolution and resolution.get("errors"):
            record["path_resolution"] = {"status": "error", "errors": resolution.get("errors")}
        elif record.get("path_ref", {}).get("registry") == "private_resource_paths":
            record["registration_hint"] = "register a knowledge_root/template_root/package_root if this path should be shared by multiple resources"
    record.pop("path", None)
    if source_url and "source" not in record:
        record["source"] = {"type": "url", "url": source_url}
    if "update_policy" not in record:
        record["update_policy"] = {"mode": "manual"}
    versioning, retention, snapshot_behavior = resource_versioning_policy(record)
    record.setdefault("versioning", versioning)
    record.setdefault("retention", retention)
    record.setdefault("snapshot_behavior", snapshot_behavior)
    if "package" not in record:
        record["package"] = package_id
    return record


def resource_id_from_url(url: str, fallback: str = "resource") -> str:
    parsed = urlparse(url)
    pieces = [parsed.netloc, parsed.path.strip("/").split("/")[-1]]
    return safe_id("-".join(piece for piece in pieces if piece), fallback)


def find_workplace_package_manifests(workplace_root: Path, package_id: str) -> list[tuple[PackageRootResolution, Path]]:
    manifests: list[tuple[PackageRootResolution, Path]] = []
    roots = package_root_entries(workplace_root)
    if roots:
        root_resolutions = [package_root_resolution_from_entry(workplace_root, entry) for entry in roots]
    else:
        root_resolutions = [resolve_package_root(workplace_root, None, mode="read")]
    for root in root_resolutions:
        if root.warnings and not root.fallback:
            continue
        for path in package_path_candidates(root.resolved_path, package_id):
            if path.is_file():
                manifests.append((root, path))
    return manifests


def package_manifest_path_for_write(workplace_root: Path, package_id: str, package_root_id: str | None = None) -> tuple[PackageRootResolution, Path]:
    existing = find_workplace_package_manifests(workplace_root, package_id)
    if package_root_id:
        root, default_path = resolve_package_path(workplace_root, package_id, package_root_id, mode="write")
        for existing_root, existing_path in existing:
            if existing_root.root_id == root.root_id:
                return existing_root, existing_path
        return root, default_path
    if len(existing) > 1:
        roots = ", ".join(f"{root.root_id}:{path.as_posix()}" for root, path in existing)
        raise SystemExit(f"FAIL: duplicate package id '{package_id}' found across package roots: {roots}; pass --package-root")
    if len(existing) == 1:
        root, path = existing[0]
        if not root.resolved_path.is_dir() and not root.fallback:
            raise SystemExit(f"FAIL: package root '{root.root_id}' path does not exist: {root.resolved_path.as_posix()}")
        return root, path
    root, default_path = resolve_package_path(workplace_root, package_id, None, mode="write")
    if root.fallback:
        root.resolved_path.mkdir(parents=True, exist_ok=True)
    return root, default_path


def load_workplace_package_manifest(workplace_root: Path, package_id: str, package_root_id: str | None = None, *, mode: str = "read") -> tuple[Path, dict[str, Any], PackageRootResolution]:
    existing = find_workplace_package_manifests(workplace_root, package_id)
    if package_root_id:
        root, default_path = resolve_package_path(workplace_root, package_id, package_root_id, mode=mode)
        path = default_path
        for existing_root, existing_path in existing:
            if existing_root.root_id == root.root_id:
                root, path = existing_root, existing_path
                break
    elif existing:
        if len(existing) > 1:
            roots = ", ".join(f"{root.root_id}:{path.as_posix()}" for root, path in existing)
            root, path = existing[0]
            root.warnings.append(f"WARN: duplicate package id '{package_id}' found across package roots: {roots}")
        else:
            root, path = existing[0]
    else:
        root, path = resolve_package_path(workplace_root, package_id, None, mode=mode)
    data = load_yaml_document(path)
    error = yaml_error(data)
    if error:
        if mode == "write":
            raise SystemExit(f"FAIL: package manifest YAML invalid: {rel(path, workplace_root)}: {error}")
        return path, data, root
    if not data:
        data = {
            "schema_version": 1,
            "id": package_id,
            "name": package_id.replace(".", " ").replace("-", " ").title(),
            "version": "1.0.0",
            "kind": "documentation" if "docs" in package_id or "documentation" in package_id else "platform",
            "scope": "workplace",
            "resources": [],
        }
    if "resources" not in data or not isinstance(data.get("resources"), list):
        data["resources"] = []
    return path, data, root


def resource_index_path_for_package(manifest_path: Path, workplace_root: Path, package_id: str) -> Path:
    if manifest_path.name == "package.yaml":
        return manifest_path.parent / "indexes" / "resource-index.yaml"
    validated_id = validate_resource_id(package_id, "knowledge package")
    package_root = workplace_root / "packages"
    return contained_resource_path(
        package_root,
        package_root / validated_id / "indexes" / "resource-index.yaml",
        "knowledge package",
    )


def build_resource_index(package_manifest: dict[str, Any], workplace_root: Path | None = None, package_root_id: str | None = None) -> dict[str, Any]:
    package_id = str(package_manifest.get("id", "package"))
    resources = [
        normalize_resource_record(resource, package_id, workplace_root)
        for resource in package_manifest.get("resources", [])
        if isinstance(resource, dict)
    ]
    return {
        "schema_version": 1,
        "package": {
            "id": package_id,
            "version": str(package_manifest.get("version", "1.0.0")),
            "package_root": package_root_id or str(package_manifest.get("package_root", "")) or None,
        },
        "generated_at": now_utc(),
        "load_policy": {
            "default": "on_demand",
            "heavy_resources": "index_only_until_requested",
            "do_not_load_full_content": True,
        },
        "resources": resources,
    }


def upsert_resource(resources: list[Any], resource: dict[str, Any]) -> str:
    for index, item in enumerate(resources):
        if isinstance(item, dict) and str(item.get("id")) == str(resource["id"]):
            resources[index] = resource
            return "updated"
    resources.append(resource)
    return "added"


def write_package_manifest_and_index(workplace_root: Path, package_id: str, package_manifest: dict[str, Any], package_root_id: str | None = None) -> tuple[Path, Path, PackageRootResolution]:
    package_root, manifest_path = package_manifest_path_for_write(workplace_root, package_id, package_root_id)
    package_manifest["package_root"] = package_root.root_id
    manifest_path.parent.mkdir(parents=True, exist_ok=True)
    manifest_path.write_text(ensure_trailing_newline(dump_yaml(package_manifest)), encoding="utf-8")
    index_path = resource_index_path_for_package(manifest_path, workplace_root, package_id)
    index_path.parent.mkdir(parents=True, exist_ok=True)
    index_path.write_text(ensure_trailing_newline(dump_yaml(build_resource_index(package_manifest, workplace_root, package_root.root_id))), encoding="utf-8")
    return manifest_path, index_path, package_root


def registry_ids_from_workplace(workplace_root: Path, registry_name: str, collection_key: str) -> set[str]:
    data = load_yaml_document(workplace_root / "registries" / registry_name)
    return registry_ids(data, collection_key)


def resource_path_ref_missing(workplace_root: Path, resource: dict[str, Any]) -> str | None:
    path_ref = resource.get("path_ref")
    if not isinstance(path_ref, dict):
        return "missing path_ref"
    registry = str(path_ref.get("registry") or "")
    ref_id = str(path_ref.get("id") or "")
    if not registry or not ref_id:
        return None if path_ref.get("package") else "path_ref must include registry/id or package/relative_path"
    known = {
        "knowledge_roots": ("knowledge-roots.yaml", "knowledge_roots"),
        "package_roots": ("package-roots.yaml", "package_roots"),
        "templates": ("templates.yaml", "templates"),
        "tools": ("tools.yaml", "tools"),
        "mcp": ("mcp.yaml", "mcp_servers"),
        "private_resource_paths": ("private-resource-paths.yaml", "private_resource_paths"),
    }
    if registry in {"external_resources"}:
        return None
    if registry not in known:
        return f"unknown path_ref registry {registry}"
    registry_file, collection_key = known[registry]
    if ref_id not in registry_ids_from_workplace(workplace_root, registry_file, collection_key):
        return f"path_ref target missing: {registry}/{ref_id}"
    return None


def workspace_registry_specs() -> dict[str, tuple[str, str, str]]:
    return {
        "knowledge_roots": ("knowledge_roots", "knowledge-roots.yaml", "knowledge_roots"),
        "template_roots": ("template_roots", "templates.yaml", "template_roots"),
        "templates": ("templates", "templates.yaml", "templates"),
        "package_roots": ("package_roots", "package-roots.yaml", "package_roots"),
        "tools": ("tools", "tools.yaml", "tools"),
        "mcp": ("mcp", "mcp.yaml", "mcp_servers"),
        "private_resource_paths": ("private_resource_paths", "private-resource-paths.yaml", "private_resource_paths"),
    }


def workplace_registry_entry(workplace_manifest: Path | None, registry: str, ref_id: str) -> dict[str, Any] | None:
    spec = workspace_registry_specs().get(registry)
    if not spec or not workplace_manifest:
        return None
    registry_key, default_name, collection_key = spec
    data = load_workplace_registry(workplace_manifest, registry_key, default_name)
    entries = data.get(collection_key) if isinstance(data, dict) else None
    if not isinstance(entries, list):
        return None
    for entry in entries:
        if isinstance(entry, dict) and str(entry.get("id") or "") == ref_id:
            return entry
    return None


def resolve_workspace_path_ref(project_root: Path, path_ref: dict[str, Any], *, workplace_manifest: Path | None = None) -> dict[str, Any]:
    manifest = normalize_workplace_manifest(workplace_manifest or project_workplace_manifest(project_root))
    workplace_root = manifest.parent if manifest else None
    package_id = str(path_ref.get("package") or "")
    relative_path = str(path_ref.get("relative_path") or "").strip()
    if package_id:
        bases: list[Path] = []
        if package_id == "self":
            bases.append(project_root)
        else:
            bases.append(locate_flow_root(project_root) / "packages" / package_id)
            if workplace_root:
                manifest_path, _manifest, _package_root = load_workplace_package_manifest(workplace_root, package_id, mode="read")
                if manifest_path:
                    bases.append(manifest_path.parent)
        for base in bases:
            resolved_base = base.resolve()
            candidate = (resolved_base / relative_path).resolve() if relative_path else resolved_base
            try:
                candidate.relative_to(resolved_base)
            except ValueError:
                return {"status": "unresolved", "reason": "invalid_path_ref: relative_path escapes declared package root"}
            if candidate.exists():
                return {"status": "resolved", "path": str(candidate)}
        return {"status": "unresolved", "reason": f"package path not found: {package_id}/{relative_path}".rstrip("/")}
    registry = str(path_ref.get("registry") or "")
    ref_id = str(path_ref.get("id") or "")
    if registry == "external_resources":
        return {"status": "external", "url": path_ref.get("url") or ""}
    if not registry or not ref_id:
        return {"status": "unresolved", "reason": "path_ref must include package or registry/id"}
    if not manifest or not workplace_root:
        return {"status": "unresolved", "reason": "workplace manifest is not configured"}
    entry = workplace_registry_entry(manifest, registry, ref_id)
    if not entry:
        return {"status": "unresolved", "reason": f"registry target missing: {registry}/{ref_id}"}
    raw_path = entry.get("path")
    if not raw_path:
        return {"status": "descriptor", "entry": {str(key): value for key, value in entry.items() if str(key) != "path"}}
    root_resolution = workplace_path_resolution(workplace_root, str(raw_path))
    if root_resolution.get("errors"):
        return {"status": "unresolved", "reason": "; ".join(str(item) for item in root_resolution.get("errors", []))}
    base = path_resolution_to_path(root_resolution).resolve()
    # A knowledge root is an explicit workplace trust boundary.  Local heavy
    # documentation is intentionally allowed to live outside the workplace
    # directory (for example, in a shared device documentation root); deny
    # every other registry path outside the workplace unless it is the
    # dedicated private-resource mechanism.
    if registry not in {"private_resource_paths", "knowledge_roots"}:
        try:
            base.relative_to(workplace_root.resolve())
        except ValueError:
            return {"status": "unresolved", "reason": "invalid_path_ref: registry path escapes workplace root"}
    candidate = (base / relative_path).resolve() if relative_path else base
    try:
        candidate.relative_to(base)
    except ValueError:
        return {"status": "unresolved", "reason": "invalid_path_ref: relative_path escapes declared registry root"}
    return {"status": "resolved" if candidate.exists() else "missing", "path": str(candidate)}


def workspace_ref_matches_resource(resource: dict[str, Any], requested: Any) -> bool:
    if isinstance(requested, dict):
        if requested.get("path_ref") and resource.get("path_ref") == requested.get("path_ref"):
            return True
        requested_id = str(requested.get("id") or requested.get("resource_id") or "").strip()
        requested_package = str(requested.get("package_id") or requested.get("package") or "").strip()
    else:
        text = str(requested).strip()
        if text == "*":
            return True
        requested_package, _, requested_id = text.partition(":")
        if not requested_id:
            requested_id = requested_package
            requested_package = ""
    ids = {
        str(resource.get("id") or ""),
        str(resource.get("instance_id") or ""),
    }
    for value in list(ids):
        if ":" in value:
            ids.add(value.rsplit(":", 1)[-1])
        if "@" in value:
            ids.add(value.split("@", 1)[0])
    package_id = str(resource.get("package_id") or "")
    ids.add(f"{package_id}:{resource.get('id')}")
    ids.add(f"{package_id}:{resource.get('instance_id')}")
    if requested_id not in ids:
        return False
    return not requested_package or requested_package == package_id


def workspace_access_runtime_document(project_root: Path, task: dict[str, Any]) -> dict[str, Any]:
    task_id = safe_id(str(task.get("id") or "task"), "task")
    run_id = safe_id(str(task.get("run_id") or "run"), "run")
    capsule_path = locate_flow_root(project_root) / "contexts" / "assignment-capsules" / f"{task_id}.capsule.yaml"
    capsule = load_yaml_document(capsule_path)
    requested = normalize_workspace_access(task.get("workspace_access") or capsule.get("workspace_access"))
    resources = capsule.get("resolved_resources") if isinstance(capsule.get("resolved_resources"), list) else []
    selected_resources = [
        resource
        for resource in resources
        if isinstance(resource, dict) and any(workspace_ref_matches_resource(resource, item) for item in requested["knowledge_resources"])
    ]
    manifest = normalize_workplace_manifest(project_workplace_manifest(project_root))
    document: dict[str, Any] = {
        "schema_version": 1,
        "generated_at": now_utc(),
        "run_id": run_id,
        "task_id": task_id,
        "visibility": "private_runtime",
        "policy": {
            "do_not_copy_private_paths_to_public_artifacts": True,
            "assignment_scope_remains_project_relative": True,
        },
        "workplace_manifest": str(manifest) if manifest else "",
        "requested": requested,
        "grants": {key: [] for key in WORKSPACE_ACCESS_KEYS},
    }
    for resource in selected_resources:
        path_ref = resource.get("path_ref") if isinstance(resource.get("path_ref"), dict) else {}
        grant = {
            "id": str(resource.get("id") or ""),
            "instance_id": str(resource.get("instance_id") or ""),
            "package_id": str(resource.get("package_id") or ""),
            "kind": str(resource.get("kind") or ""),
            "load_policy": str(resource.get("load_policy") or "on_demand"),
            "path_ref": path_ref,
            "resolution": resolve_workspace_path_ref(project_root, path_ref, workplace_manifest=manifest) if path_ref else {"status": "unresolved", "reason": "missing path_ref"},
        }
        document["grants"]["knowledge_resources"].append(grant)
    registry_for_group = {"templates": "templates", "tools": "tools", "mcp": "mcp"}
    for group, registry in registry_for_group.items():
        for item in requested[group]:
            if isinstance(item, dict):
                path_ref = item.get("path_ref") if isinstance(item.get("path_ref"), dict) else {"registry": registry, "id": str(item.get("id") or "")}
                label = str(item.get("id") or item.get("name") or "")
            else:
                label = str(item)
                path_ref = {"registry": registry, "id": label}
            document["grants"][group].append(
                {
                    "id": label,
                    "path_ref": path_ref,
                    "resolution": resolve_workspace_path_ref(project_root, path_ref, workplace_manifest=manifest),
                }
            )
    return document


def write_workspace_access_runtime_file(project_root: Path, task: dict[str, Any]) -> Path:
    run_id = safe_id(str(task.get("run_id") or "run"), "run")
    task_id = safe_id(str(task.get("id") or "task"), "task")
    paths = worker_run_paths(project_root, run_id, task_id)
    document = workspace_access_runtime_document(project_root, task)
    json_write(paths["workspace_access"], document)
    return paths["workspace_access"]


def knowledge_package_doctor_checks(workplace_root: Path, package_id: str, package_root_id: str | None = None) -> list[Check]:
    manifest_path, manifest, package_root = load_workplace_package_manifest(workplace_root, package_id, package_root_id, mode="read")
    checks: list[Check] = []
    if not manifest_path.is_file():
        return [
            check_with_hint(
                "FAIL",
                f"package {package_id} manifest missing",
                "The package id cannot be resolved through registries/package-roots.yaml.",
                f"python bin/pf.py knowledge-package-create --workplace <workplace-root> --id {package_id} --package-root global --title \"{package_id}\" --apply",
            )
        ]
    for warning in package_root.warnings:
        level = "WARN" if warning.startswith("WARN:") else "FAIL"
        checks.append(
            check_with_hint(
                level,
                warning,
                "The package_root resolver found a registry/path issue.",
                "check registries/package-roots.yaml and pass --package-root when multiple roots contain the same package id",
            )
        )
    checks.append(check("PASS", f"package {package_id} resolved through package root {package_root.root_id}"))
    loaded = load_doctor_yaml(
        manifest_path,
        "package-manifest.schema.json",
        f"package {package_id} manifest",
        checks,
    )
    if loaded is None:
        return checks
    manifest = loaded
    resources = manifest.get("resources") if isinstance(manifest.get("resources"), list) else []
    for resource in resources:
        if not isinstance(resource, dict):
            checks.append(check("FAIL", f"package {package_id} contains non-object resource"))
            continue
        resource_id = str(resource.get("id", "resource"))
        normalized = normalize_resource_record(resource, package_id, workplace_root)
        missing = resource_path_ref_missing(workplace_root, normalized)
        checks.append(
            check("PASS", f"{package_id}:{resource_id} path_ref resolved")
            if not missing
            else check_with_hint(
                "FAIL",
                f"{package_id}:{resource_id} path_ref - {missing}",
                "Public resource records must resolve through a known registry instead of embedding private paths.",
                "update the resource to use path_ref.registry and path_ref.id from the workplace registries",
            )
        )
        kind = str(resource.get("kind") or "reference")
        if kind in HEAVY_RESOURCE_KINDS and not resource.get("load_policy"):
            checks.append(check("WARN", f"{package_id}:{resource_id} heavy resource should declare load_policy"))
        elif kind in HEAVY_RESOURCE_KINDS and str(resource.get("load_policy")) in {"always_index", "session_start", "project_init"}:
            checks.append(check("WARN", f"{package_id}:{resource_id} heavy resource should normally use on_demand"))
    index_path = resource_index_path_for_package(manifest_path, workplace_root, package_id)
    if index_path.is_file():
        index = load_yaml_document(index_path)
        checks.append(check("PASS" if not yaml_error(index) else "FAIL", f"{rel(index_path, workplace_root)} is valid YAML"))
        indexed_ids = {str(item.get("id")) for item in index.get("resources", []) if isinstance(item, dict)}
        for resource in resources:
            if isinstance(resource, dict) and str(resource.get("id")) not in indexed_ids:
                checks.append(check("WARN", f"{package_id}:{resource.get('id')} missing from resource index"))
    else:
        checks.append(check("WARN", f"{rel(index_path, workplace_root)} missing; run knowledge-index-refresh --apply"))
    text = manifest_path.read_text(encoding="utf-8", errors="replace")
    checks.append(check("PASS" if is_public_path_safe(text) else "FAIL", f"package {package_id} manifest has no private absolute paths"))
    navigation = manifest.get("navigation") if isinstance(manifest.get("navigation"), dict) else {}
    if navigation:
        checks.append(check("PASS", f"package {package_id} navigation configured"))
        allowed_sections = {"source_code", "development_articles", "documentation", "api_reference", "usage_rules"}
        for section in navigation:
            checks.append(check("PASS" if str(section) in allowed_sections else "WARN", f"navigation section recognized: {section}"))
    elif package_id.startswith("docs."):
        checks.append(check("WARN", f"package {package_id} navigation configured"))
    dependencies = package_dependency_ids(manifest)
    package_index = package_manifest_index(workplace_root, None, workplace_root / "workplace.yaml")
    for dependency_id in dependencies:
        checks.append(
            check("PASS", f"required knowledge package dependency available: {dependency_id}")
            if dependency_id in package_index
            else check_with_hint(
                "FAIL",
                f"required knowledge package dependency available: {dependency_id}",
                "The package manifest declares this dependency generically.",
                f"python bin/pf.py knowledge-package-create --workplace <workplace-root> --id {dependency_id} --package-root global --title \"{dependency_id}\" --apply",
            )
        )
    package_policy = load_policy_document("package-id-policy.yaml")
    for entry in policy_entries(package_policy, "package_id_rules"):
        if policy_id_matches(package_id, entry):
            level = str(entry.get("level", "WARN")).upper()
            checks.append(
                check_with_hint(
                    "FAIL" if level == "FAIL" else "WARN",
                    str(entry.get("message", f"package id policy matched: {package_id}")),
                    str(entry.get("why", "The package id matched a data-driven package id policy.")),
                    str(entry.get("fix", "update the package id or policy manifest")),
                )
            )
    return checks


def project_knowledge_resource_index_checks(project_root: Path, distribution_root: Path | None, workplace_manifest: Path | None) -> list[Check]:
    checks: list[Check] = []
    checked = 0
    flow_root = locate_flow_root(project_root)
    for manifest_path in package_manifest_candidates(project_root, distribution_root, workplace_manifest):
        manifest = load_yaml_document(manifest_path)
        if not manifest or yaml_error(manifest):
            continue
        resources = manifest.get("resources")
        if not isinstance(resources, list) or not resources:
            continue
        checked += 1
        package_id = str(manifest.get("id", manifest_path.stem))
        root_for_index = manifest_path.parent.parent if manifest_path.parent.name == "packages" else project_root
        if distribution_root:
            try:
                manifest_path.relative_to(distribution_root)
                root_for_index = distribution_root
            except ValueError:
                pass
        index_path = resource_index_path_for_package(manifest_path, root_for_index, package_id)
        project_local_package = path_is_relative_to(manifest_path, flow_root / "packages")
        if index_path.is_file():
            checks.append(check("PASS", f"knowledge resource index for {package_id} found"))
        elif project_local_package:
            checks.append(check("PASS", f"knowledge resource index for {package_id} optional for project-local package resources"))
        else:
            checks.append(
                check_with_hint(
                    "WARN",
                    f"knowledge resource index for {package_id} missing",
                    f"Expected resource index: {rel(index_path, project_root)}",
                    f"python bin/pf.py knowledge-resource-index-build --project-root . --package {package_id} --apply",
                )
            )
        for resource in resources:
            if not isinstance(resource, dict):
                checks.append(check("FAIL", f"{package_id} contains non-object resource"))
                continue
            normalized = normalize_resource_record(resource, package_id)
            if "path" in resource and Path(str(resource.get("path"))).is_absolute():
                checks.append(check("FAIL", f"{package_id}:{resource.get('id', 'resource')} exposes an absolute path instead of path_ref"))
            if "path_ref" not in normalized:
                checks.append(check("FAIL", f"{package_id}:{resource.get('id', 'resource')} missing path_ref"))
            kind = str(resource.get("kind") or "reference")
            if kind in HEAVY_RESOURCE_KINDS and not resource.get("load_policy"):
                checks.append(check("WARN", f"{package_id}:{resource.get('id', 'resource')} heavy resource should declare load_policy"))
    if checked == 0:
        checks.append(check("PASS", "knowledge resource indexes checked (no package resources declared)"))
    return checks


def capability_records(required: list[str], optional: list[str], providers: dict[str, str]) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    available = set(providers)

    def record(capability: str, required_capability: bool) -> dict[str, Any]:
        is_available = capability in available
        provider = providers.get(capability)
        return {
            "id": capability,
            "status": "available" if is_available else "missing",
            "provider": provider if is_available else None,
            "severity": "fail" if required_capability and not is_available else ("warn" if not required_capability and not is_available else "info"),
        }

    return [record(item, True) for item in required], [record(item, False) for item in optional]


def project_context_snapshot_paths(project_root: Path) -> tuple[Path, Path]:
    contexts = locate_flow_root(project_root) / "contexts"
    return contexts / "project-context.snapshot.yaml", contexts / "project-context.snapshot.md"


def project_context_snapshot_generations_dir(project_root: Path) -> Path:
    return locate_flow_root(project_root) / "contexts" / "project-context.snapshots"


def project_context_stale_marker_path(project_root: Path) -> Path:
    return locate_flow_root(project_root) / "runtime" / "context" / "project-context.stale.json"


def project_context_report_path(project_root: Path) -> Path:
    return locate_flow_root(project_root) / "artifacts" / "project-context-refresh-report.md"


def project_context_policy_action(status: str, policy: dict[str, Any]) -> str:
    session_policy = policy.get("on_session_start") if isinstance(policy.get("on_session_start"), dict) else {}
    if status == "fresh":
        return str(session_policy.get("if_fresh") or "continue")
    if status == "fresh_with_updates":
        return str(session_policy.get("if_fresh_with_updates") or "notify")
    if status == "stale":
        return str(session_policy.get("if_stale") or "ask_operator")
    if status == "broken":
        return str(session_policy.get("if_broken") or "block")
    return "block"


def execution_readiness_payload(
    required_records: list[dict[str, Any]],
    capability_resolution: dict[str, Any] | None = None,
    *,
    coordination_blocked: bool = False,
) -> dict[str, Any]:
    missing_capabilities: list[dict[str, Any]] = []
    blockers: list[dict[str, Any]] = []
    seen_capabilities: set[tuple[str, str]] = set()

    for item in required_records:
        if not isinstance(item, dict) or item.get("status") != "missing":
            continue
        capability = str(item.get("id") or "")
        if not capability:
            continue
        key = (capability, "project.required_capabilities")
        if key in seen_capabilities:
            continue
        seen_capabilities.add(key)
        missing = {
            "capability": capability,
            "required_by": "project.required_capabilities",
            "availability": "missing",
            "reason": "no active project registry provider declared the required capability",
            "expected_provider_scope": "project or workplace tool/MCP registry",
        }
        missing_capabilities.append(missing)
        blockers.append({"type": "capability_missing", **missing})

    resolution = capability_resolution if isinstance(capability_resolution, dict) else {}
    for item in resolution.get("unsatisfied", []) if isinstance(resolution.get("unsatisfied"), list) else []:
        if not isinstance(item, dict):
            continue
        capability = str(item.get("capability") or "")
        required_by = str(item.get("required_by") or "execution_route")
        if not capability:
            continue
        key = (capability, required_by)
        if key in seen_capabilities:
            continue
        seen_capabilities.add(key)
        missing = {
            "capability": capability,
            "required_by": required_by,
            "availability": "missing",
            "reason": str(item.get("reason") or "selected execution resources do not provide the capability"),
            "expected_provider_scope": "specialization resource profile, active process pack, or workplace registry",
        }
        missing_capabilities.append(missing)
        blockers.append({"type": "capability_missing", **missing})

    if coordination_blocked:
        blockers.append(
            {
                "type": "coordination_unavailable",
                "reason": "organized coordination is selected but the workplace Director is unavailable",
                "required_by": "project.coordination",
            }
        )

    return {
        "status": "blocked" if blockers else "ready",
        "missing_capabilities": missing_capabilities,
        "blockers": blockers,
    }


def resource_readiness_payload(
    *,
    platform_resolution: dict[str, Any],
    required_resource_missing: list[str],
    specialization_conflicts: list[dict[str, Any]],
    parameter_conflicts: list[dict[str, Any]],
) -> dict[str, Any]:
    blockers: list[dict[str, Any]] = []
    for item in platform_resolution.get("missing_required_contracts", []):
        blockers.append({"type": "platform_contract_missing", "id": str(item)})
    for item in platform_resolution.get("circular_platforms", []):
        blockers.append({"type": "platform_contract_cycle", "id": str(item)})
    for item in required_resource_missing:
        blockers.append({"type": "required_resource_missing", "id": str(item)})
    for item in specialization_conflicts:
        if isinstance(item, dict):
            blockers.append({"type": "specialization_conflict", **item})
    for item in parameter_conflicts:
        if isinstance(item, dict):
            blockers.append({"type": "parameter_conflict", **item})
    return {"status": "blocked" if blockers else "fresh", "blockers": blockers}


def resolved_resource_key(resource: dict[str, Any]) -> tuple[str, str, str]:
    return (str(resource.get("package_id") or ""), str(resource.get("id") or ""), str(resource.get("instance_id") or ""))


def current_resolved_resource_indexes(current_snapshot: dict[str, Any]) -> tuple[dict[tuple[str, str, str], dict[str, Any]], dict[tuple[str, str], list[dict[str, Any]]]]:
    resolved = current_snapshot.get("resolved") if isinstance(current_snapshot.get("resolved"), dict) else {}
    resources = resolved.get("available_knowledge_resources") if isinstance(resolved.get("available_knowledge_resources"), list) else []
    if not resources:
        resources = resolved.get("knowledge_resources") if isinstance(resolved.get("knowledge_resources"), list) else []
    by_instance: dict[tuple[str, str, str], dict[str, Any]] = {}
    by_subject: dict[tuple[str, str], list[dict[str, Any]]] = {}
    for item in resources:
        if not isinstance(item, dict):
            continue
        by_instance[resolved_resource_key(item)] = item
        by_subject.setdefault((str(item.get("package_id") or ""), str(item.get("id") or "")), []).append(item)
    return by_instance, by_subject


def project_context_check_result(project_root: Path, *, explicit_workplace: str | None = None) -> dict[str, Any]:
    snapshot_yaml, _snapshot_md = project_context_snapshot_paths(project_root)
    if not snapshot_yaml.is_file():
        return {
            "snapshot_id": None,
            "status": "broken",
            "fresh": False,
            "stale": False,
            "broken": True,
            "updates_available": [],
            "stale_resources": [],
            "broken_refs": [{"reason": "project context snapshot missing"}],
            "recommended_action": "project-context-refresh",
            "policy_action": "block",
        }
    snapshot = load_yaml_document(snapshot_yaml)
    reasons: list[str] = []
    stale_resources: list[dict[str, Any]] = []
    updates_available: list[dict[str, Any]] = []
    broken_refs: list[dict[str, Any]] = []
    for key in ["schema_version", "snapshot", "project", "flow", "sources", "capabilities", "session"]:
        if key not in snapshot:
            broken_refs.append({"reason": f"snapshot schema invalid: missing {key}"})
    meta = snapshot.get("snapshot", {}) if isinstance(snapshot.get("snapshot"), dict) else {}
    snapshot_id = str(meta.get("id") or snapshot.get("id") or "project-context")
    valid_until = parse_snapshot_timestamp(meta.get("valid_until"))
    if valid_until is None:
        reasons.append("valid_until missing or invalid")
    elif valid_until < datetime.now(timezone.utc):
        reasons.append("valid_until expired")
    marker_path = project_context_stale_marker_path(project_root)
    if marker_path.is_file():
        try:
            marker = json.loads(marker_path.read_text(encoding="utf-8"))
        except json.JSONDecodeError:
            marker = {"reason": "stale marker invalid"}
        stale_resources.append({"id": marker.get("subject") or "project-context", "reason": marker.get("reason") or "snapshot stale marker exists"})
    recorded_sources = {}
    sources = snapshot.get("sources", {}) if isinstance(snapshot.get("sources"), dict) else {}
    fingerprints = sources.get("fingerprints", []) if isinstance(sources, dict) else []
    if isinstance(fingerprints, list):
        for item in fingerprints:
            if isinstance(item, dict) and "id" in item:
                recorded_sources[str(item["id"])] = str(item.get("checksum", "missing"))
    current_sources = collect_project_snapshot_sources(project_root)
    current_by_id = {str(item["id"]): str(item.get("checksum", "missing")) for item in current_sources}
    for source_id, checksum in current_by_id.items():
        if source_id.startswith("package-"):
            continue
        if source_id not in recorded_sources:
            reasons.append(f"source added: {source_id}")
        elif recorded_sources[source_id] != checksum:
            reasons.append(f"source changed: {source_id}")
    for source_id in sorted(set(recorded_sources) - set(current_by_id)):
        if source_id.startswith("package-"):
            continue
        reasons.append(f"source removed: {source_id}")

    current = build_project_context_snapshot(project_root, explicit_workplace=explicit_workplace)
    execution_readiness = current.get("execution_readiness") if isinstance(current.get("execution_readiness"), dict) else {}
    resource_readiness = current.get("resource_readiness") if isinstance(current.get("resource_readiness"), dict) else {}
    readiness = current.get("readiness") if isinstance(current.get("readiness"), dict) else {}
    health = current.get("snapshot", {}).get("health") if isinstance(current.get("snapshot"), dict) and isinstance(current.get("snapshot", {}).get("health"), dict) else {}
    if str(resource_readiness.get("status") or "") == "blocked":
        for item in resource_readiness.get("blockers", []) if isinstance(resource_readiness.get("blockers"), list) else []:
            if isinstance(item, dict):
                broken_refs.append(
                    {
                        "id": item.get("id") or item.get("target") or "resource_readiness",
                        "reason": item.get("reason") or item.get("type") or "resource readiness blocked",
                        "type": item.get("type") or "resource_readiness_blocked",
                    }
                )
    old_classification = snapshot.get("project_classification")
    current_classification = current.get("project_classification")
    if json.dumps(old_classification or {}, ensure_ascii=False, sort_keys=True) != json.dumps(
        current_classification or {}, ensure_ascii=False, sort_keys=True
    ):
        reasons.append("project classification changed")
    old_resolved = snapshot.get("resolved") if isinstance(snapshot.get("resolved"), dict) else {}
    old_resources = old_resolved.get("knowledge_resources") if isinstance(old_resolved.get("knowledge_resources"), list) else []
    current_by_instance, current_by_subject = current_resolved_resource_indexes(current)
    for old in old_resources:
        if not isinstance(old, dict):
            continue
        mode = str(old.get("versioning_mode") or "rolling_index")
        key = resolved_resource_key(old)
        subject_key = (key[0], key[1])
        current_same_subject = current_by_subject.get(subject_key, [])
        current_instance = current_by_instance.get(key)
        if mode == "multi_version":
            if current_instance is None:
                broken_refs.append({"id": old.get("id"), "instance_id": old.get("instance_id"), "reason": "pinned multi_version resource instance missing"})
                continue
            old_version = str(old.get("resolved_version") or "")
            for current_resource in current_same_subject:
                current_version = str(current_resource.get("resolved_version") or "")
                is_newer, _warning = version_is_newer(current_version, old_version)
                if is_newer:
                    updates_available.append({"id": old.get("id"), "type": "knowledge_resource", "snapshot_version": old_version, "available_version": current_version, "snapshot_stale": False, "reason": "multi_version resource has newer version but pinned instance still exists"})
        else:
            current_resource = current_same_subject[-1] if current_same_subject else None
            if current_resource is None:
                broken_refs.append({"id": old.get("id"), "instance_id": old.get("instance_id"), "reason": "current resource missing"})
                continue
            old_generation = str(old.get("resolved_generation") or old.get("fingerprint", {}).get("value") or "")
            current_generation = str(current_resource.get("resolved_generation") or current_resource.get("fingerprint", {}).get("value") or "")
            old_fingerprint = str(old.get("fingerprint", {}).get("value") or "")
            current_fingerprint = str(current_resource.get("fingerprint", {}).get("value") or "")
            if old_generation != current_generation or old_fingerprint != current_fingerprint:
                stale_resources.append({"id": old.get("id"), "snapshot_generation": old_generation, "current_generation": current_generation, "reason": f"{mode} resource generation changed"})
    if broken_refs:
        status = "broken"
    elif stale_resources or reasons:
        status = "stale"
    elif updates_available:
        status = "fresh_with_updates"
    else:
        status = "fresh"
    policy = snapshot.get("context_policy") if isinstance(snapshot.get("context_policy"), dict) else default_context_policy({})
    policy_action = project_context_policy_action(status, policy)
    return {
        "snapshot_id": snapshot_id,
        "snapshot_sha256": "sha256:" + sha256_file(snapshot_yaml),
        "status": status,
        "fresh": status in {"fresh", "fresh_with_updates"},
        "stale": status == "stale",
        "broken": status == "broken",
        "updates_available": updates_available,
        "stale_resources": stale_resources + [{"reason": reason} for reason in reasons],
        "broken_refs": broken_refs,
        "recommended_action": "project-context-refresh" if status in {"stale", "broken"} else "continue",
        "policy_action": policy_action,
        "policy": {"action": policy_action},
        "health": health,
        "readiness": readiness,
        "resource_readiness": resource_readiness,
        "execution_readiness": execution_readiness,
    }


def build_project_context_snapshot(project_root: Path, *, max_age_days: int = 7, explicit_workplace: str | None = None) -> dict[str, Any]:
    flow_root = locate_flow_root(project_root)
    manifest = flow_root / "process-forge.yaml"
    if not manifest.is_file():
        raise SystemExit(f"FAIL: process-forge manifest not found: {rel(manifest, project_root)}")
    manifest_data = load_yaml_document(manifest)
    manifest_text = manifest.read_text(encoding="utf-8", errors="replace")
    sources = collect_project_snapshot_sources(project_root)
    required = sorted(
        set(yaml_list_values(manifest_text, "required_capabilities")).union(
            str(item)
            for item in as_list(manifest_data.get("required_capabilities"))
            if str(item)
        )
    )
    optional = sorted(
        set(yaml_list_values(manifest_text, "optional_capabilities")).union(
            str(item)
            for item in as_list(manifest_data.get("optional_capabilities"))
            if str(item)
        )
    )
    generated_at = now_utc()
    valid_until = (datetime.now(timezone.utc).replace(microsecond=0) + timedelta(days=max_age_days)).isoformat().replace("+00:00", "Z")
    project = manifest_data.get("project", {}) if isinstance(manifest_data.get("project"), dict) else {}
    process_forge_data = manifest_data.get("process_forge", {}) if isinstance(manifest_data.get("process_forge"), dict) else {}
    detected_data = manifest_data.get("detected", {}) if isinstance(manifest_data.get("detected"), dict) else {}
    workplace_manifest_path: Path | None = None
    distribution_root: Path | None = None
    local_config = flow_root / "process-forge.local.yaml"
    if explicit_workplace:
        workplace_manifest_path = workplace_manifest_path_from_root(Path(explicit_workplace).expanduser())
        if workplace_manifest_path.is_file():
            distribution_root = resolve_distribution_path(workplace_manifest_path, "processforge")
    elif local_config.is_file():
        workplace_manifest_path = resolve_workplace_manifest(local_config)
        if workplace_manifest_path and workplace_manifest_path.is_file():
            distribution_root = resolve_distribution_path(workplace_manifest_path, "processforge")
    elif isinstance(manifest_data.get("workplace"), dict) and manifest_data["workplace"].get("reference") == "auto":
        distribution_root = project_root
    providers = load_registry_capability_providers(project_root, workplace_manifest_path)
    required_records, optional_records = capability_records(required, optional, providers)
    classification = classify_project(project_root, workplace_manifest_path)
    manifest_platform_contracts = manifest_data.get("platform_contracts") if isinstance(manifest_data.get("platform_contracts"), list) else []
    manifest_platform_ids = [
        str(item.get("platform") or str(item.get("id", "")).removeprefix("platform."))
        for item in manifest_platform_contracts
        if isinstance(item, dict) and (item.get("platform") or item.get("id"))
    ]
    meta_project_without_selection = project_type_is_meta_workspace(manifest_data) and not manifest_platform_ids
    if not manifest_platform_ids and not meta_project_without_selection:
        manifest_platform_ids = classification["platforms"]
    platform_resolution = resolve_platform_contracts(workplace_manifest_path, manifest_platform_ids, project_root=project_root)
    available_platform_contracts = available_platform_contract_records(workplace_manifest_path, project_root)
    if meta_project_without_selection:
        platform_selection = {
            "status": "not_applicable",
            "reason": f"Project type {project_types_from_manifest(manifest_data)[0]} does not select one platform stack by default.",
        }
    elif manifest_platform_ids:
        platform_selection = {"status": "selected", "reason": "Project manifest or detection selected platform contracts."}
    else:
        platform_selection = {"status": "not_selected", "reason": "No platform contracts were selected for this project."}
    package_index_ids = set(package_manifest_index(project_root, distribution_root, workplace_manifest_path))
    required_resource_missing, recommended_resource_missing = platform_resource_findings(workplace_manifest_path, platform_resolution, package_index_ids)
    process_refs = manifest_data.get("processes") if isinstance(manifest_data.get("processes"), list) else []
    package_refs = manifest_data.get("packages") if isinstance(manifest_data.get("packages"), list) else []
    process_id_for_resolution = str(manifest_data.get("process") or "")
    manifest_specializations = [str(item) for item in as_list(manifest_data.get("specializations")) if str(item)]
    specialization_context = resolve_specialization_context(
        project_root,
        workplace_manifest_path,
        platform_ids=manifest_platform_ids,
        process_id=process_id_for_resolution,
        specialization_ids=manifest_specializations,
        platform_resolution=platform_resolution,
    )
    package_ids = [
        str(item.get("id"))
        for item in manifest_data.get("knowledge_stack", [])
        if isinstance(item, dict) and item.get("id")
    ]
    package_ids.extend(specialization_context["activated_knowledge_packages"])
    enabled_processes = [
        {"id": str(item.get("id", "unknown")), "path": str(item.get("path", ""))}
        for item in process_refs
        if isinstance(item, dict)
    ]
    selected_packages = [
        {"id": str(item.get("id", "unknown")), "path": str(item.get("path", ""))}
        for item in package_refs
        if isinstance(item, dict)
    ]
    package_ids.extend(item["id"] for item in selected_packages)
    required_package_ids = sorted(set(platform_resolution["required_knowledge_packages"]).intersection(set(specialization_context["activated_knowledge_packages"])))
    package_resources = resolve_package_resources(
        project_root,
        distribution_root,
        workplace_manifest_path,
        sorted(set(package_ids)),
        required_package_ids,
    )
    context_requirements = context_requirements_from_manifest(manifest_data)
    context_policy = default_context_policy(manifest_data)
    direct_platform_package_ids = sorted(
        {
            str(package_id)
            for contract in platform_resolution.get("contracts", [])
            if isinstance(contract, dict)
            for package_id in [
                *(contract.get("required", {}).get("knowledge_packages", []) if isinstance(contract.get("required"), dict) else []),
                *(contract.get("recommended", {}).get("knowledge_packages", []) if isinstance(contract.get("recommended"), dict) else []),
            ]
            if str(package_id)
        }
    )
    resolved_knowledge_resources, resource_selection = select_resolved_knowledge_resources(
        package_resources,
        context_requirements,
        direct_package_ids=direct_platform_package_ids,
    )
    available_knowledge_resources = [resolved_resource_instance(resource) for resource in package_resources]
    local_search_resources = [
        {
            "id": str(item.get("id") or ""),
            "resource_id": str(item.get("id") or ""),
            "package_id": str(item.get("package_id") or ""),
            "kind": str(item.get("kind") or "knowledge"),
            "title": str(item.get("title") or item.get("id") or ""),
            "description": str(item.get("description") or ""),
            "version": str(item.get("version") or item.get("generation") or ""),
            "fingerprint": item.get("fingerprint") if isinstance(item.get("fingerprint"), dict) else {},
            "path_ref": item.get("path_ref") if isinstance(item.get("path_ref"), dict) else {},
            "status": str(item.get("status") or "available"),
            "load_policy": "snapshot_authorized",
            "indexing": selected_resource_indexing(item, resource_selection),
        }
        for item in resolved_knowledge_resources
        if str(item.get("id") or "")
    ]
    template_ids = {str(item) for item in specialization_context.get("activated_templates", []) if str(item)}
    template_ids.update(
        str(item.get("id") or "")
        for item in context_requirements.get("templates", [])
        if isinstance(item, dict) and str(item.get("id") or "")
    )
    for template_id in sorted(template_ids):
        entry = workplace_registry_entry(workplace_manifest_path, "templates", template_id)
        if entry and str(entry.get("status") or "available") not in {"missing", "disabled"}:
            local_search_resources.append(
                {
                    "id": template_id,
                    "resource_id": template_id,
                    "package_id": str(entry.get("template_root") or ""),
                    "kind": "template",
                    "title": str(entry.get("title") or template_id),
                    "description": str(entry.get("description") or ""),
                    "version": str(entry.get("version") or ""),
                    "path_ref": {"registry": "templates", "id": template_id},
                    "status": str(entry.get("status") or "available"),
                    "load_policy": "snapshot_authorized",
                    "indexing": entry.get("indexing") if isinstance(entry.get("indexing"), dict) else {
                        "enabled": True,
                        "mode": "metadata",
                        "fields": ["title", "description", "version", "path"],
                        "sources": [
                            {"path": "README.md", "mode": "fulltext", "include": ["README.md"], "role": "description"},
                            {"path": ".", "mode": "metadata", "role": "template_root"},
                        ],
                    },
                }
            )
    reproducibility = aggregate_reproducibility(resolved_knowledge_resources)
    parameter_resolution = resolve_project_parameters(
        project_root,
        workplace_manifest_path,
        manifest_data,
        platform_resolution,
        manifest_specializations,
        manifest_platform_ids,
        process_id_for_resolution,
        manifest_path_refs(project_root, "processes"),
    )
    coordination_status = effective_project_coordination(project_root, explicit_workplace)
    coordination_blocked = coordination_status["effective_mode"] == "organized" and (
        not coordination_status["workplace_director_enabled"] or not coordination_status["director_office_exists"]
    )
    health_status = "blocked" if any(item["severity"] == "fail" for item in required_records) or platform_resolution["missing_required_contracts"] or platform_resolution["circular_platforms"] or required_resource_missing or specialization_context["conflicts"] or parameter_resolution["conflicts"] or coordination_blocked else ("warn" if any(item["severity"] == "warn" for item in optional_records) or recommended_resource_missing else "pass")
    execution_readiness = execution_readiness_payload(
        required_records,
        specialization_context.get("capability_resolution") if isinstance(specialization_context.get("capability_resolution"), dict) else {},
        coordination_blocked=coordination_blocked,
    )
    resource_readiness = resource_readiness_payload(
        platform_resolution=platform_resolution,
        required_resource_missing=required_resource_missing,
        specialization_conflicts=specialization_context["conflicts"],
        parameter_conflicts=parameter_resolution["conflicts"],
    )
    snapshot_id = f"ctx-{datetime.now(timezone.utc).strftime('%Y%m%d-%H%M%S')}-{uuid.uuid4().hex[:6]}"
    requirements = requirements_fingerprints(flow_root, project_root)
    source_fingerprints = {
        "workplace_manifest": next((item.get("checksum") for item in sources if item.get("id") == "workplace_manifest"), "missing"),
        "package_roots_registry": "sha256:" + sha256_file(workplace_manifest_path.parent / "registries" / "package-roots.yaml") if workplace_manifest_path and (workplace_manifest_path.parent / "registries" / "package-roots.yaml").is_file() else "missing",
        "knowledge_roots_registry": "sha256:" + sha256_file(workplace_manifest_path.parent / "registries" / "knowledge-roots.yaml") if workplace_manifest_path and (workplace_manifest_path.parent / "registries" / "knowledge-roots.yaml").is_file() else "missing",
        "template_registry": "sha256:" + sha256_file(workplace_manifest_path.parent / "registries" / "templates.yaml") if workplace_manifest_path and (workplace_manifest_path.parent / "registries" / "templates.yaml").is_file() else "missing",
        "tool_registry": "sha256:" + sha256_file(workplace_manifest_path.parent / "registries" / "tools.yaml") if workplace_manifest_path and (workplace_manifest_path.parent / "registries" / "tools.yaml").is_file() else "missing",
        "parameters_registry": "sha256:" + sha256_file(workplace_manifest_path.parent / "registries" / "parameters.yaml") if workplace_manifest_path and (workplace_manifest_path.parent / "registries" / "parameters.yaml").is_file() else "missing",
        "installed_subjects": "sha256:" + sha256_file(workplace_manifest_path.parent / "registries" / "installed-subjects.yaml") if workplace_manifest_path and (workplace_manifest_path.parent / "registries" / "installed-subjects.yaml").is_file() else "missing",
    }
    return {
        "schema_version": 1,
        "id": snapshot_id,
        "generated_at": generated_at,
        "snapshot": {
            "id": snapshot_id,
            "generated_at": generated_at,
            "valid_until": valid_until,
            "refresh_policy": {
                "max_age_days": max_age_days,
                "refresh_when_sources_change": True,
                "refresh_when_workplace_changes": True,
                "refresh_when_package_versions_change": True,
                "refresh_when_required_tools_change": True,
            },
            "health": {"status": health_status},
        },
        "project": {
            "id": str(project.get("id", safe_id(project_root.name))),
            "name": str(project.get("name", project_root.name)),
            "type": (
                project.get("type")
                if str(project.get("type") or "") not in {"", "auto", "unknown"}
                else (classification["project_types"][0] if classification["project_types"] else "unknown")
            ),
        },
        "project_classification": classification,
        "flow": {
            "root": flow_label(project_root),
            "layout": flow_layout(project_root),
            "manifest": rel(manifest, project_root),
            "local_config": rel(flow_root / "process-forge.local.yaml", project_root),
        },
        "process_forge": {
            "version": str(process_forge_data.get("version", "1.0.0")),
            "version_constraint": str(process_forge_data.get("version_constraint", "^1.0")),
            "install_mode": str(process_forge_data.get("install_mode", "linked")),
            "distribution": {
                "id": "processforge",
                "source": "workplace" if workplace_manifest_path else "project",
                "path": "<private-distribution-ref>" if distribution_root else "missing",
                "status": "available" if distribution_root and distribution_root.is_dir() else "missing",
            },
        },
        "platform_contracts": {
            "available": available_platform_contracts,
            "selected": platform_resolution["contracts"],
            "stack": platform_resolution["platform_stack"],
            "missing_required": platform_resolution["missing_required_contracts"],
            "circular": platform_resolution["circular_platforms"],
            "missing_required_resources": required_resource_missing,
            "missing_recommended_resources": recommended_resource_missing,
        },
        "available_platform_contracts": available_platform_contracts,
        "selected_platform_contracts": platform_resolution["contracts"],
        "platform_selection": platform_selection,
        "platform_stack": platform_resolution["platform_stack"],
        "sources": {"fingerprints": sources},
        "requirements_fingerprint": requirements,
        "context_requirements": context_requirements,
        "context_policy": context_policy,
        "resolved_parameters": parameter_resolution["resolved_parameters"],
        "parameter_resolution": {
            "status": parameter_resolution["status"],
            "sources": parameter_resolution["sources"],
            "provenance": parameter_resolution["provenance"],
            "conflicts": parameter_resolution["conflicts"],
        },
        "resolved_context": specialization_context,
        "active_resource_profile": specialization_context["active_resource_profile"],
        "execution_route": specialization_context["execution_route"],
        "capability_resolution": specialization_context["capability_resolution"],
        "selected_specializations": specialization_context["selected_specializations"],
        "applied_project_overrides": specialization_context["applied_project_overrides"],
        "effective_fingerprints": specialization_context["effective_fingerprints"],
        "resolution_reasons": specialization_context["resolution_reasons"],
        "conflicts": specialization_context["conflicts"] + parameter_resolution["conflicts"],
        "resolved": {
            "knowledge_packages": [{"id": item, "constraint": "declared"} for item in sorted(set(package_ids))],
            "knowledge_resources": resolved_knowledge_resources,
            "available_knowledge_resources": available_knowledge_resources,
            "template_packages": context_requirements.get("template_packages", []),
            "templates": [{"id": item, "status": "activated"} for item in specialization_context["activated_templates"]],
            "excluded_templates": [{"id": item, "reason": "excluded by specialization or project override"} for item in specialization_context["excluded_templates"]],
            "tools": [{"id": item, "status": "activated"} for item in specialization_context["activated_tools"]],
            "excluded_tools": [{"id": item, "reason": "excluded by specialization or project override"} for item in specialization_context["excluded_tools"]],
            "platform_contracts": context_requirements.get("platform_contracts", []),
            "process_packages": selected_packages,
        },
        "local_search_resources": local_search_resources,
        "resource_selection": resource_selection,
        "freshness": {
            "status": "fresh",
            "checked_at": generated_at,
            "stale_reasons": [],
            "update_available": [],
            "broken_refs": [],
        },
        "readiness": {
            "context": {"status": "fresh"},
            "resources": resource_readiness,
            "execution": execution_readiness,
        },
        "resource_readiness": resource_readiness,
        "execution_readiness": execution_readiness,
        "reproducibility": reproducibility,
        "source_fingerprints": source_fingerprints,
        "knowledge_stack": manifest_data.get("knowledge_stack", [{"id": "processforge.core", "version": "1.0.0", "source": "distribution"}]),
        "resolved_policies": {
            "hard": [
                {"id": "public.no_local_absolute_paths", "value": True, "locked": True},
                {"id": "files.one_writer_per_scope", "value": True, "locked": True},
                {"id": "secrets.public_exports_sanitized", "value": True, "locked": True},
                {"id": "runtime.private", "value": True, "locked": True},
                {"id": "markdown.not_machine_merge_source", "value": True, "locked": True},
            ],
            "preferences": [
                {"id": "templates.project_overrides_global", "value": True},
                {"id": "session.prefer_project_context_snapshot", "value": True},
            ],
        },
        "capabilities": {"required": required_records, "optional": optional_records},
        "knowledge_resources": {
            "selected": resolved_knowledge_resources,
            "available": available_knowledge_resources,
            "required": [item for item in resolved_knowledge_resources if item.get("requirement") == "required"],
            "recommended": [item for item in resolved_knowledge_resources if item.get("requirement") == "recommended"],
            "missing_required": required_resource_missing,
            "missing_recommended": recommended_resource_missing,
        },
        "tools": {"required": platform_resolution["required_tools"], "recommended": platform_resolution["recommended_tools"], "activated": specialization_context["activated_tools"], "excluded": specialization_context["excluded_tools"], "source": "workplace-registry"},
        "mcp": {"required": platform_resolution["required_mcp"], "recommended": platform_resolution["recommended_mcp"], "activated": specialization_context["activated_mcp"], "excluded": specialization_context["excluded_mcp"], "source": "workplace-registry"},
        "templates": {
            "project": [str(item["path"]) for item in sources if item.get("kind") == "template"],
            "required": platform_resolution["required_templates"],
            "recommended": platform_resolution["recommended_templates"],
            "activated": specialization_context["activated_templates"],
            "excluded": specialization_context["excluded_templates"],
            "source": "workplace-registry",
        },
        "processes": {"enabled": enabled_processes},
        "packages": {"selected": selected_packages},
        "workplace_coordination": {
            "project_mode": coordination_status["project_mode"],
            "workplace_default_project_mode": coordination_status["workplace_default_project_mode"],
            "effective_mode": coordination_status["effective_mode"],
            "director_enabled": bool(coordination_status["workplace_director_enabled"] and coordination_status["effective_mode"] == "organized"),
            "director_available_at_workplace": bool(coordination_status["workplace_director_enabled"]),
            "director_office_exists": bool(coordination_status["director_office_exists"]),
            "director_required": bool(coordination_status["director_required"]),
            "director_process": coordination_status["director_process"] if coordination_status["effective_mode"] == "organized" else None,
            "director_inbox": coordination_status["director_inbox"] if coordination_status["effective_mode"] == "organized" else {"enabled": False},
        },
        "session": {
            "startup_read_order": [
                rel(flow_root / "AGENTS.md", project_root),
                rel(flow_root / "process-forge.yaml", project_root),
                rel(flow_root / "contexts" / "project-context.snapshot.md", project_root),
                "current assignment",
                "relevant logs/reviews/handoffs",
            ],
            "telemetry_root": rel(flow_root / "runtime" / "telemetry", project_root),
            "events_log": rel(flow_root / "runtime" / "events" / "events.ndjson", project_root),
        },
    }


def render_project_context_snapshot_md(snapshot: dict[str, Any], freshness: str = "fresh", reasons: list[str] | None = None) -> str:
    project = snapshot.get("project", {})
    flow = snapshot.get("flow", {})
    meta = snapshot.get("snapshot", {})
    capabilities = snapshot.get("capabilities", {})
    policies = snapshot.get("resolved_policies", {})
    process_forge = snapshot.get("process_forge", {}) if isinstance(snapshot.get("process_forge"), dict) else {}
    distribution = process_forge.get("distribution", {}) if isinstance(process_forge.get("distribution"), dict) else {}
    platforms = snapshot.get("platform_contracts", {}).get("selected", []) if isinstance(snapshot.get("platform_contracts"), dict) else []
    platform_stack = snapshot.get("platform_stack", [])
    if not isinstance(platform_stack, list):
        platform_stack = []
    knowledge_resources = snapshot.get("knowledge_resources", {}) if isinstance(snapshot.get("knowledge_resources"), dict) else {}
    required_resources = knowledge_resources.get("required", []) if isinstance(knowledge_resources.get("required"), list) else []
    recommended_resources = knowledge_resources.get("recommended", []) if isinstance(knowledge_resources.get("recommended"), list) else []
    tools = snapshot.get("tools", {}) if isinstance(snapshot.get("tools"), dict) else {}
    mcp = snapshot.get("mcp", {}) if isinstance(snapshot.get("mcp"), dict) else {}
    template_groups = snapshot.get("templates", {}) if isinstance(snapshot.get("templates"), dict) else {}
    processes = snapshot.get("processes", {}).get("enabled", []) if isinstance(snapshot.get("processes"), dict) else []
    project_templates = template_groups.get("project", []) if isinstance(template_groups.get("project"), list) else []
    workplace_coordination = snapshot.get("workplace_coordination", {}) if isinstance(snapshot.get("workplace_coordination"), dict) else {}
    resolved_context = snapshot.get("resolved_context", {}) if isinstance(snapshot.get("resolved_context"), dict) else {}
    selected_specializations = resolved_context.get("selected_specializations", []) if isinstance(resolved_context.get("selected_specializations"), list) else []
    applied_project_overrides = resolved_context.get("applied_project_overrides", []) if isinstance(resolved_context.get("applied_project_overrides"), list) else []
    effective_resources = resolved_context.get("effective_resources", []) if isinstance(resolved_context.get("effective_resources"), list) else []
    provided_capabilities = resolved_context.get("provided_capabilities", []) if isinstance(resolved_context.get("provided_capabilities"), list) else []
    execution_route = resolved_context.get("execution_route", {}) if isinstance(resolved_context.get("execution_route"), dict) else {}
    capability_resolution = resolved_context.get("capability_resolution", {}) if isinstance(resolved_context.get("capability_resolution"), dict) else {}
    resolution_conflicts = resolved_context.get("conflicts", []) if isinstance(resolved_context.get("conflicts"), list) else []
    resolved_parameters = snapshot.get("resolved_parameters", {}) if isinstance(snapshot.get("resolved_parameters"), dict) else {}
    parameter_resolution = snapshot.get("parameter_resolution", {}) if isinstance(snapshot.get("parameter_resolution"), dict) else {}
    parameter_sources = parameter_resolution.get("sources", []) if isinstance(parameter_resolution.get("sources"), list) else []
    parameter_conflicts = parameter_resolution.get("conflicts", []) if isinstance(parameter_resolution.get("conflicts"), list) else []

    def md_items(items: list[Any], empty: str = "None.") -> str:
        if not items:
            return f"- {empty}"
        output: list[str] = []
        for item in items:
            if isinstance(item, dict):
                label = item.get("id") or item.get("path") or item
                status = item.get("status")
                severity = item.get("severity")
                suffix = f" ({status}, {severity})" if status or severity else ""
                output.append(f"- {label}{suffix}")
            else:
                output.append(f"- {item}")
        return "\n".join(output)

    reasons = reasons or []
    return "\n".join(
        [
            "# Project Context Snapshot",
            "",
            "## Generated",
            "",
            f"- generated_at: {meta.get('generated_at', 'unknown')}",
            f"- valid_until: {meta.get('valid_until', 'unknown')}",
            "",
            "## Freshness",
            "",
            freshness + (f": {', '.join(reasons)}" if reasons else ""),
            "",
            "## Project",
            "",
            f"- id: {project.get('id', 'unknown')}",
            f"- name: {project.get('name', 'unknown')}",
            "",
            "## Flow Root",
            "",
            f"`{flow.get('root', '.')}/`",
            "",
            "## Linked ProcessForge",
            "",
            f"- version: {process_forge.get('version', 'unknown')}",
            f"- constraint: {process_forge.get('version_constraint', 'unknown')}",
            f"- install_mode: {process_forge.get('install_mode', 'linked')}",
            f"- distribution: {distribution.get('id', 'processforge')} ({distribution.get('status', 'unknown')})",
            "",
            "## Coordination Mode",
            "",
            f"- project_mode: {workplace_coordination.get('project_mode', 'inherit')}",
            f"- workplace_default_project_mode: {workplace_coordination.get('workplace_default_project_mode', 'simple')}",
            f"- effective_mode: {workplace_coordination.get('effective_mode', 'simple')}",
            f"- director_available_at_workplace: {str(bool(workplace_coordination.get('director_available_at_workplace', False))).lower()}",
            f"- director_required: {str(bool(workplace_coordination.get('director_required', False))).lower()}",
            "",
            "## Connected Knowledge Packages",
            "",
            md_items(snapshot.get("knowledge_stack", [])),
            "",
            "## Platform Contracts",
            "",
            md_items(platforms),
            "",
            "## Platform Stack",
            "",
            md_items(platform_stack),
            "",
            "## Selected Specializations",
            "",
            md_items(selected_specializations),
            "",
            "## Effective Resources",
            "",
            md_items(effective_resources),
            "",
            "## Provided Capabilities",
            "",
            md_items(provided_capabilities),
            "",
            "## Execution Route",
            "",
            f"- process: {execution_route.get('process', '')}",
            f"- required_capabilities: {', '.join(execution_route.get('required_capabilities', [])) if isinstance(execution_route.get('required_capabilities'), list) and execution_route.get('required_capabilities') else 'None.'}",
            f"- required_evidence: {', '.join(execution_route.get('required_evidence', [])) if isinstance(execution_route.get('required_evidence'), list) and execution_route.get('required_evidence') else 'None.'}",
            "",
            "## Capability Resolution",
            "",
            f"- satisfied: {len(capability_resolution.get('satisfied', [])) if isinstance(capability_resolution.get('satisfied'), list) else 0}",
            f"- unsatisfied: {len(capability_resolution.get('unsatisfied', [])) if isinstance(capability_resolution.get('unsatisfied'), list) else 0}",
            "",
            "## Applied Project Overrides",
            "",
            md_items(applied_project_overrides),
            "",
            "## Resolved Parameters",
            "",
            f"- namespaces: {', '.join(sorted(str(key) for key in resolved_parameters)) if resolved_parameters else 'None.'}",
            f"- sources: {len(parameter_sources)}",
            f"- conflicts: {len(parameter_conflicts)}",
            "",
            "## Resolution Conflicts",
            "",
            md_items(resolution_conflicts),
            "",
            "## Required Knowledge Resources",
            "",
            md_items(required_resources),
            "",
            "## Recommended Knowledge Resources",
            "",
            md_items(recommended_resources),
            "",
            "## Enabled Processes",
            "",
            md_items(processes),
            "",
            "## Required Capabilities",
            "",
            md_items(capabilities.get("required", [])),
            "",
            "## Optional Capabilities",
            "",
            md_items(capabilities.get("optional", [])),
            "",
            "## Required Tools",
            "",
            md_items(tools.get("required", []) if isinstance(tools, dict) else []),
            "",
            "## Recommended Tools",
            "",
            md_items(tools.get("recommended", []) if isinstance(tools, dict) else []),
            "",
            "## Required MCP",
            "",
            md_items(mcp.get("required", []) if isinstance(mcp, dict) else []),
            "",
            "## Recommended MCP",
            "",
            md_items(mcp.get("recommended", []) if isinstance(mcp, dict) else []),
            "",
            "## Hard Policies",
            "",
            md_items(policies.get("hard", []) if isinstance(policies, dict) else []),
            "",
            "## Preferences",
            "",
            md_items(policies.get("preferences", []) if isinstance(policies, dict) else []),
            "",
            "## Project Templates",
            "",
            md_items(project_templates),
            "",
            "## Required Templates",
            "",
            md_items(template_groups.get("required", []) if isinstance(template_groups, dict) else []),
            "",
            "## Recommended Templates",
            "",
            md_items(template_groups.get("recommended", []) if isinstance(template_groups, dict) else []),
            "",
            "## Session Start",
            "",
            "Read in this order:",
            "",
            "1. `.pf/AGENTS.md`.",
            "2. `.pf/process-forge.yaml`.",
            "3. this snapshot.",
            "4. current assignment.",
            "5. relevant logs/reviews/handoffs.",
            "",
            f"Telemetry root: `{snapshot.get('session', {}).get('telemetry_root', 'runtime/telemetry')}`",
            f"Events log: `{snapshot.get('session', {}).get('events_log', 'runtime/events/events.ndjson')}`",
            "",
            "## Current Risks",
            "",
            "- Markdown files are human-readable context and are not authoritative structured merge sources.",
            "- If freshness is stale, refresh before using required capability decisions.",
            "",
            "## Refresh Instructions",
            "",
            "Run `python bin/pf.py project-context-refresh --project-root <project-root>` from the ProcessForge distribution root, or `python .pf/runtime/bin/pf.py project-context-refresh --project-root .` inside the linked project.",
            "",
        ]
    )


def parse_snapshot_timestamp(value: Any) -> datetime | None:
    if not isinstance(value, str):
        return None
    try:
        return datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError:
        return None


def project_context_freshness(project_root: Path, *, explicit_workplace: str | None = None) -> tuple[str, list[str], dict[str, Any]]:
    snapshot_yaml, _snapshot_md = project_context_snapshot_paths(project_root)
    if not snapshot_yaml.is_file():
        return "missing", [], {}
    snapshot = load_yaml_document(snapshot_yaml)
    result = project_context_check_result(project_root, explicit_workplace=explicit_workplace)
    reasons = [str(item.get("reason") or item) for item in result.get("stale_resources", []) if isinstance(item, dict)]
    reasons.extend(str(item.get("reason") or item) for item in result.get("broken_refs", []) if isinstance(item, dict))
    return str(result.get("status") or "stale"), reasons, snapshot


def write_project_context_snapshot_outputs(project_root: Path, *, explicit_workplace: str | None = None) -> tuple[str, dict[str, Path], dict[str, Any], list[str]]:
    snapshot = build_project_context_snapshot(project_root, explicit_workplace=explicit_workplace)
    status, reasons, _previous = project_context_freshness(project_root, explicit_workplace=explicit_workplace)
    if status == "missing":
        reasons = []
    snapshot_yaml, snapshot_md = project_context_snapshot_paths(project_root)
    snapshot_yaml.parent.mkdir(parents=True, exist_ok=True)
    generations = project_context_snapshot_generations_dir(project_root)
    generations.mkdir(parents=True, exist_ok=True)
    generation_path = generations / f"{snapshot['snapshot']['id']}.yaml"
    generation_path.write_text(ensure_trailing_newline(dump_yaml(snapshot)), encoding="utf-8")
    snapshot_yaml.write_text(ensure_trailing_newline(dump_yaml(snapshot)), encoding="utf-8")
    snapshot_md.write_text(render_project_context_snapshot_md(snapshot, "fresh", []), encoding="utf-8")
    marker = project_context_stale_marker_path(project_root)
    if marker.is_file():
        marker.unlink()
    workplace_snapshot = write_workplace_context_snapshot(project_root, snapshot)
    report = project_context_report_path(project_root)
    report.parent.mkdir(parents=True, exist_ok=True)
    report.write_text(
        "\n".join(
            [
                "# Project Context Refresh Report",
                "",
                f"- snapshot_id: {snapshot['snapshot']['id']}",
                f"- status: fresh",
                f"- previous_status: {status}",
                f"- generation: {rel(generation_path, project_root)}",
                f"- current: {rel(snapshot_yaml, project_root)}",
                "",
                "Existing assignment capsules are immutable and remain pinned to their original snapshot id and checksum.",
                "",
            ]
        ),
        encoding="utf-8",
    )
    return "fresh", {"snapshot_yaml": snapshot_yaml, "snapshot_md": snapshot_md, "snapshot_generation": generation_path, "refresh_report": report, "workplace_snapshot": workplace_snapshot}, snapshot, reasons


def telemetry_session_id(prefix: str = "session") -> str:
    stamp = now_utc().replace("-", "").replace(":", "").replace("Z", "z")
    return f"{prefix}-{stamp}"


def redact_telemetry_value(value: Any) -> Any:
    if isinstance(value, dict):
        return {key: redact_telemetry_value(item) for key, item in value.items()}
    if isinstance(value, list):
        return [redact_telemetry_value(item) for item in value]
    if isinstance(value, str) and contains_secret_value(value):
        return "<redacted>"
    return value


def append_telemetry_event(telemetry_path: Path, event: str, **payload: Any) -> None:
    telemetry_path.parent.mkdir(parents=True, exist_ok=True)
    item = {"ts": now_utc(), "event": event}
    item.update(redact_telemetry_value(payload))
    with telemetry_path.open("a", encoding="utf-8") as handle:
        handle.write(json.dumps(item, ensure_ascii=False, sort_keys=True) + "\n")


def event_runtime_paths(project_root: Path) -> tuple[Path, Path]:
    runtime = locate_flow_root(project_root) / "runtime" / "events"
    return runtime / "events.ndjson", locate_flow_root(project_root) / "runtime" / "hooks" / "outbox"


def hook_config_path(project_root: Path) -> Path:
    return locate_flow_root(project_root) / "hooks.yaml"


def hook_results_root(project_root: Path) -> Path:
    return locate_flow_root(project_root) / "runtime" / "hooks" / "results"


def validate_hooks_config(project_root: Path) -> list[Check]:
    path = hook_config_path(project_root)
    checks: list[Check] = []
    if not path.is_file():
        return [check("FAIL", f"{rel(path, project_root)} missing")]
    data = load_yaml_document(path)
    error = yaml_error(data)
    if error:
        return [check("FAIL", f"{rel(path, project_root)} is invalid YAML: {error}")]
    hooks_config = data.get("hooks") if isinstance(data, dict) else None
    if not isinstance(hooks_config, dict):
        return [check("FAIL", f"{rel(path, project_root)} missing hooks object")]
    targets = hooks_config.get("targets")
    if not isinstance(targets, list):
        checks.append(check("FAIL", f"{rel(path, project_root)} hooks.targets must be a list"))
        return checks
    checks.append(check("PASS", f"{rel(path, project_root)} is valid YAML"))
    checks.append(check("PASS", f"{rel(path, project_root)} hooks.targets is a list"))
    for index, target in enumerate(targets):
        label = f"hooks.targets[{index}]"
        if not isinstance(target, dict):
            checks.append(check("FAIL", f"{label} must be an object"))
            continue
        for key in ["id", "type", "enabled", "event_types"]:
            checks.append(check("PASS" if key in target else "FAIL", f"{label}.{key} present"))
        event_types = target.get("event_types")
        if isinstance(event_types, list) and all(isinstance(item, str) and item for item in event_types):
            checks.append(check("PASS", f"{label}.event_types is a string list"))
        else:
            checks.append(check("FAIL", f"{label}.event_types must be a string list; quote wildcard as \"*\""))
    return checks


def resolve_runtime_config_path(project_root: Path, value: str | None, default: Path) -> Path:
    if not value:
        return default
    path = Path(value)
    if path.is_absolute():
        return path
    if path.parts and path.parts[0] == PROJECT_FLOW_ROOT:
        return project_root / path
    return locate_flow_root(project_root) / path


def project_id(project_root: Path) -> str:
    manifest = locate_flow_root(project_root) / "process-forge.yaml"
    data = load_yaml_document(manifest)
    project = data.get("project") if isinstance(data, dict) else None
    if isinstance(project, dict) and project.get("id"):
        return str(project["id"])
    return safe_id(project_root.name, "project")


def processforge_event(
    project_root: Path,
    event_type: str,
    *,
    severity: str = "info",
    session_id: str | None = None,
    assignment_id_value: str | None = None,
    assignment_path: str | None = None,
    process_id: str | None = None,
    process_version: str | None = None,
    stage: str | None = None,
    subject: str | None = None,
    payload: dict[str, Any] | None = None,
    data: dict[str, Any] | None = None,
    privacy: str = "private",
    correlation_id: str | None = None,
    causation_id: str | None = None,
    event_id: str | None = None,
    actor: dict[str, Any] | None = None,
) -> dict[str, Any]:
    correlation = correlation_id or session_id or f"corr-{uuid.uuid4().hex[:12]}"
    event_id = event_id or f"evt_{uuid.uuid4().hex}"
    clean_data = redact_telemetry_value(data if data is not None else (payload or {}))
    actor_data = actor or {"type": "agent", "id": "processforge-cli", "role": "orchestrator"}
    event_subject = subject or assignment_path or assignment_id_value or session_id or event_type
    return {
        "schema_version": 1,
        "event_id": event_id,
        "event_type": event_type,
        "source": "processforge.cli",
        "subject": event_subject,
        "time": now_utc(),
        "correlation_id": correlation,
        "causation_id": causation_id,
        "project": {"flow_root": flow_label(project_root), "project_id": project_id(project_root)},
        "process": {"id": process_id, "version": process_version, "stage_id": stage, "process_run_id": None},
        "assignment": {"id": assignment_id_value, "path": assignment_path},
        "actor": actor_data,
        "session": {"id": session_id},
        "data": clean_data,
        "severity": severity,
        "privacy": privacy,
    }


def event_id_value(event: dict[str, Any]) -> str:
    return str(event.get("event_id") or event.get("id") or f"evt_{uuid.uuid4().hex}")


def event_type_name(event: dict[str, Any]) -> str:
    return str(event.get("event_type") or event.get("type") or "")


def event_matches_hook(event: dict[str, Any], hook: dict[str, Any]) -> bool:
    event_types = hook.get("event_types", ["*"])
    if not isinstance(event_types, list):
        return False
    return "*" in event_types or event_type_name(event) in event_types


def hook_targets(project_root: Path) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    config = load_yaml_document(hook_config_path(project_root))
    hooks_config = config.get("hooks") if isinstance(config, dict) else None
    if isinstance(hooks_config, dict):
        targets = hooks_config.get("targets", [])
        return hooks_config, targets if isinstance(targets, list) else []
    if isinstance(hooks_config, list):
        return {"mode": config.get("dispatch", {}).get("default_mode", "outbox") if isinstance(config.get("dispatch"), dict) else "outbox"}, hooks_config
    return {"mode": "outbox"}, []


def selected_hooks(project_root: Path, event: dict[str, Any]) -> list[dict[str, Any]]:
    _hooks_config, hooks = hook_targets(project_root)
    selected: list[dict[str, Any]] = []
    for hook in hooks:
        if not isinstance(hook, dict):
            continue
        if not hook.get("enabled", False):
            continue
        if event_matches_hook(event, hook):
            selected.append(hook)
    return selected


def hook_delivery_payload(event: dict[str, Any], target: dict[str, Any], mode: str, delivery_id: str) -> dict[str, Any]:
    return {
        "schema_version": 1,
        "delivery_id": delivery_id,
        "delivery_time": now_utc(),
        "target_id": str(target.get("id", "hook")),
        "mode": mode,
        "event": event,
    }


def wtaicc_outbox_payload(event: dict[str, Any], *, chat: dict[str, Any] | None = None) -> dict[str, Any]:
    return {
        "schema_version": 1,
        "target": "wtaicc",
        "delivery_mode": "outbox",
        "created_at": now_utc(),
        "event": event,
        "chat": chat or {"included": False, "mode": "metadata_only", "messages": []},
    }


def write_hook_result(project_root: Path, result: dict[str, Any]) -> Path:
    results_root = hook_results_root(project_root)
    results_root.mkdir(parents=True, exist_ok=True)
    target = results_root / f"{result['delivery_id']}.json"
    target.write_text(json.dumps(result, ensure_ascii=False, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    return target


def dispatch_hooks(project_root: Path, event: dict[str, Any], *, dry_run: bool = False, outbox: bool = True) -> list[dict[str, Any]]:
    hooks_config, _all_hooks = hook_targets(project_root)
    hooks = selected_hooks(project_root, event)
    actions: list[dict[str, Any]] = []
    for hook in hooks:
        hook_id = safe_id(str(hook.get("id", "hook")), "hook")
        hook_type = str(hook.get("type", "outbox"))
        delivery_id = f"del_{uuid.uuid4().hex}"
        action: dict[str, Any] = {"hook": hook_id, "target_id": hook_id, "type": hook_type, "delivery_id": delivery_id}
        if dry_run:
            action["status"] = "dry_run"
            action["mode"] = "dry_run"
        elif hook_type in {"outbox", "file_outbox", "webhook", "webhook_future"} and outbox:
            default_outbox = locate_flow_root(project_root) / "runtime" / "hooks" / "outbox"
            target_root = resolve_runtime_config_path(project_root, str(hook.get("path") or hook.get("outbox") or ""), default_outbox)
            if hook_id.startswith("wtaicc") and target_root.name != "wtaicc":
                target_root = target_root / "wtaicc"
            target_root.mkdir(parents=True, exist_ok=True)
            delivery = hook_delivery_payload(event, hook, "outbox", delivery_id)
            payload = wtaicc_outbox_payload(event) if hook_id.startswith("wtaicc") else delivery
            target = target_root / f"{event_id_value(event)}.{hook_id}.json"
            target.write_text(json.dumps(payload, ensure_ascii=False, indent=2, sort_keys=True) + "\n", encoding="utf-8")
            action["status"] = "outbox_written"
            action["outbox"] = rel(target, project_root)
            result = {
                "schema_version": 1,
                "delivery_id": delivery_id,
                "target_id": hook_id,
                "status": "written",
                "exit_code": 0,
                "blocking": False,
                "message": "Outbox payload written",
                "outbox": rel(target, project_root),
            }
            action["result"] = rel(write_hook_result(project_root, result), project_root)
        elif hook_type == "command":
            action["status"] = "skipped"
            action["reason"] = "command hooks require an explicit future runner/executor"
            result = {
                "schema_version": 1,
                "delivery_id": delivery_id,
                "target_id": hook_id,
                "status": "skipped",
                "exit_code": 0,
                "blocking": bool(hook.get("blocking", False)),
                "message": action["reason"],
            }
            action["result"] = rel(write_hook_result(project_root, result), project_root)
        elif hook_type == "webhook" and not hooks_config.get("network_send_enabled", False):
            action["status"] = "skipped"
            action["reason"] = "network send is disabled by default"
        else:
            action["status"] = "skipped"
            action["reason"] = f"unsupported hook type: {hook_type}"
        actions.append(action)
    return actions


def append_process_event(project_root: Path, event: dict[str, Any], *, dispatch: bool = True) -> Path:
    events_path, _outbox = event_runtime_paths(project_root)
    events_path.parent.mkdir(parents=True, exist_ok=True)
    event_id = event_id_value(event)
    exists = False
    if events_path.is_file():
        for line in events_path.read_text(encoding="utf-8", errors="replace").splitlines():
            try:
                existing = json.loads(line)
            except json.JSONDecodeError:
                continue
            if isinstance(existing, dict) and event_id_value(existing) == event_id:
                exists = True
                break
    if not exists:
        with events_path.open("a", encoding="utf-8") as handle:
            handle.write(json.dumps(event, ensure_ascii=False, sort_keys=True) + "\n")
    if dispatch:
        dispatch_hooks(project_root, event, dry_run=False, outbox=True)
    return events_path


def emit_process_event(project_root: Path, event_type: str, **kwargs: Any) -> dict[str, Any]:
    event = processforge_event(project_root, event_type, **kwargs)
    append_process_event(project_root, event)
    return event


EVENT_TYPE_PATTERN = re.compile(r"^[a-z][a-z0-9_-]*(?:\.[a-z][a-z0-9_-]*)+$")


def validate_event_object(event: Any, label: str) -> list[str]:
    errors: list[str] = []
    if not isinstance(event, dict):
        return [f"{label}: event is not an object"]
    for key in ["schema_version", "event_id", "event_type", "source", "subject", "time", "correlation_id", "project", "data"]:
        if key not in event:
            errors.append(f"{label}: missing {key}")
    event_type = event.get("event_type")
    if not isinstance(event_type, str) or not EVENT_TYPE_PATTERN.fullmatch(event_type):
        errors.append(f"{label}: invalid event_type")
    serialized = json.dumps(event, ensure_ascii=False)
    if contains_secret_value(serialized):
        errors.append(f"{label}: secret-like value found")
    return errors


def validate_chat_message_object(message: Any, label: str) -> list[str]:
    errors: list[str] = []
    if not isinstance(message, dict):
        return [f"{label}: chat message is not an object"]
    for key in ["schema_version", "message_id", "session_id", "turn_id", "timestamp", "participant", "message", "source"]:
        if key not in message:
            errors.append(f"{label}: missing {key}")
    body = message.get("message") if isinstance(message.get("message"), dict) else {}
    if "content_hash" not in body:
        errors.append(f"{label}: missing message.content_hash")
    serialized = json.dumps(message, ensure_ascii=False)
    if contains_secret_value(serialized):
        errors.append(f"{label}: secret-like value found")
    return errors


def iter_ndjson(path: Path) -> list[tuple[int, Any, str | None]]:
    rows: list[tuple[int, Any, str | None]] = []
    if not path.is_file():
        return rows
    for line_number, line in enumerate(path.read_text(encoding="utf-8-sig", errors="replace").splitlines(), start=1):
        if not line.strip():
            continue
        try:
            rows.append((line_number, json.loads(line), None))
        except json.JSONDecodeError as exc:
            rows.append((line_number, None, str(exc)))
    return rows


def chat_transcript_path(project_root: Path, session_id: str) -> Path:
    return locate_flow_root(project_root) / "runtime" / "chat" / "transcripts" / f"{safe_id(session_id, 'session')}.ndjson"


def sha256_text(value: str) -> str:
    return "sha256:" + hashlib.sha256(value.encode("utf-8")).hexdigest()


def redact_chat_content(content: str, max_chars: int = 20000) -> tuple[str, str]:
    redacted = content
    redaction = "none"
    for pattern in SECRET_VALUE_PATTERNS:
        redacted, count = pattern.subn("<redacted>", redacted)
        if count:
            redaction = "redacted"
    if len(redacted) > max_chars:
        redacted = redacted[:max_chars]
        redaction = "truncated" if redaction == "none" else "redacted_truncated"
    return redacted, redaction


def chat_participant(participant_id: str, role: str, participant_type: str | None = None) -> dict[str, Any]:
    inferred_type = participant_type or ("human" if participant_id in {"operator", "user"} else ("subagent" if participant_id.startswith("subagent") else "agent"))
    return {"id": participant_id, "type": inferred_type, "role": role}


def append_chat_message(
    project_root: Path,
    *,
    session_id: str,
    participant_id: str,
    participant_role: str,
    message_role: str,
    content: str,
    participant_type: str | None = None,
    turn_id: str | None = None,
    parent_message_id: str | None = None,
    source_kind: str = "manual_capture",
    process_id: str | None = None,
    stage_id: str | None = None,
    assignment_id_value: str | None = None,
    include_event_content: bool = False,
    message_id: str | None = None,
    event_id: str | None = None,
) -> tuple[Path, dict[str, Any], dict[str, Any]]:
    transcript = chat_transcript_path(project_root, session_id)
    transcript.parent.mkdir(parents=True, exist_ok=True)
    requested_message_id = message_id or f"msg_{uuid.uuid4().hex}"
    redacted_content, redaction = redact_chat_content(content)
    lock = transcript.with_suffix(transcript.suffix + ".lock")
    deadline = time.monotonic() + 20.0
    descriptor: int | None = None
    while descriptor is None:
        try:
            descriptor = os.open(str(lock), os.O_CREAT | os.O_EXCL | os.O_WRONLY)
        except FileExistsError:
            if time.monotonic() >= deadline:
                raise SystemExit(f"FAIL: timed out waiting for chat transcript lock: {lock.name}")
            time.sleep(0.05)
    try:
        existing_lines = transcript.read_text(encoding="utf-8", errors="replace").splitlines() if transcript.is_file() else []
        for line in existing_lines:
            try:
                existing = json.loads(line)
            except json.JSONDecodeError:
                continue
            if isinstance(existing, dict) and str(existing.get("message_id") or "") == requested_message_id:
                if event_id:
                    body = existing.get("message") if isinstance(existing.get("message"), dict) else {}
                    existing_participant = existing.get("participant") if isinstance(existing.get("participant"), dict) else {}
                    core_data = {
                        "session_id": session_id,
                        "message_id": requested_message_id,
                        "participant": existing_participant,
                        "message": {
                            "role": body.get("role"),
                            "content_hash": body.get("content_hash"),
                            "redaction": body.get("redaction", "none"),
                            "content_ref": {"path": rel(transcript, project_root), "line": 0, "message_id": requested_message_id},
                            "content_mode": "metadata_only",
                        },
                    }
                    emit_process_event(project_root, "chat.message.recorded", session_id=session_id, assignment_id_value=assignment_id_value, process_id=process_id, stage=stage_id, subject=f"chat/{session_id}/{requested_message_id}", data=core_data, privacy="private", correlation_id=session_id, event_id=event_id)
                return transcript, existing, {}
        line_number = len([line for line in existing_lines if line.strip()]) + 1
        record = {
        "schema_version": 1,
        "message_id": requested_message_id,
        "session_id": session_id,
        "turn_id": turn_id or f"turn_{line_number}",
        "parent_message_id": parent_message_id,
        "timestamp": now_utc(),
        "participant": chat_participant(participant_id, participant_role, participant_type),
        "message": {
            "role": message_role,
            "content_type": "text/markdown",
            "content": redacted_content,
            "content_hash": sha256_text(redacted_content),
            "redaction": redaction,
        },
        "source": {"kind": source_kind, "hook_event": None, "transcript_path": rel(transcript, project_root)},
        "process": {"id": process_id, "stage_id": stage_id},
        "assignment": {"id": assignment_id_value},
        }
        with transcript.open("a", encoding="utf-8") as handle:
            handle.write(json.dumps(record, ensure_ascii=False, sort_keys=True) + "\n")
        content_ref = {"path": rel(transcript, project_root), "line": line_number, "message_id": requested_message_id}
        event_data: dict[str, Any] = {
        "session_id": session_id,
        "message_id": requested_message_id,
        "participant": record["participant"],
        "message": {
            "role": message_role,
            "content_hash": record["message"]["content_hash"],
            "redaction": redaction,
            "content_ref": content_ref,
        },
        }
        if include_event_content:
            event_data["message"]["content"] = redacted_content
            event_data["message"]["content_mode"] = "full" if redaction == "none" else redaction
        else:
            event_data["message"]["content_mode"] = "metadata_only"
        event = emit_process_event(
        project_root,
        "chat.message.recorded",
        session_id=session_id,
        assignment_id_value=assignment_id_value,
        process_id=process_id,
        stage=stage_id,
        subject=f"chat/{session_id}/{requested_message_id}",
        data=event_data,
        privacy="private",
        correlation_id=session_id,
        event_id=event_id,
        )
        return transcript, record, event
    finally:
        if descriptor is not None:
            os.close(descriptor)
        lock.unlink(missing_ok=True)


def load_chat_messages(project_root: Path, session_id: str) -> list[dict[str, Any]]:
    transcript = chat_transcript_path(project_root, session_id)
    messages: list[dict[str, Any]] = []
    for _line_number, data, error in iter_ndjson(transcript):
        if error is None and isinstance(data, dict):
            messages.append(data)
    return messages


def chat_export_messages(messages: list[dict[str, Any]], *, include_content: bool) -> list[dict[str, Any]]:
    exported: list[dict[str, Any]] = []
    for item in messages:
        body = item.get("message") if isinstance(item.get("message"), dict) else {}
        exported_item = {
            "message_id": item.get("message_id"),
            "session_id": item.get("session_id"),
            "turn_id": item.get("turn_id"),
            "timestamp": item.get("timestamp"),
            "participant": item.get("participant"),
            "message": {
                "role": body.get("role"),
                "content_hash": body.get("content_hash"),
                "redaction": body.get("redaction", "none"),
            },
        }
        if include_content:
            exported_item["message"]["content"] = body.get("content", "")
            exported_item["message"]["content_mode"] = "full" if body.get("redaction") == "none" else body.get("redaction", "redacted")
        else:
            exported_item["message"]["content_mode"] = "metadata_only"
        exported.append(exported_item)
    return exported


def write_workplace_context_snapshot(project_root: Path, snapshot: dict[str, Any]) -> Path:
    cache = locate_flow_root(project_root) / "runtime" / "cache"
    cache.mkdir(parents=True, exist_ok=True)
    local_config = locate_flow_root(project_root) / "process-forge.local.yaml"
    payload = {
        "schema_version": 1,
        "snapshot": {
            "id": "workplace-context",
            "generated_at": now_utc(),
            "privacy": "private",
        },
        "project": {"id": project_id(project_root)},
        "flow": {
            "root": flow_label(project_root),
            "manifest": rel(locate_flow_root(project_root) / "process-forge.yaml", project_root),
            "local_config": rel(local_config, project_root),
            "local_config_exists": local_config.is_file(),
        },
        "capabilities": snapshot.get("capabilities", {}),
        "resolved_parameters": snapshot.get("resolved_parameters", {}),
        "parameter_resolution": snapshot.get("parameter_resolution", {}),
        "workplace_coordination": snapshot.get("workplace_coordination", {}),
        "tools": snapshot.get("tools", {}),
        "mcp": snapshot.get("mcp", {}),
        "notes": ["Private runtime snapshot may include local availability state."],
    }
    target = cache / "workplace-context.snapshot.yaml"
    target.write_text(ensure_trailing_newline(dump_yaml(payload)), encoding="utf-8")
    return target


def session_runtime_paths(project_root: Path, session_id: str) -> tuple[Path, Path]:
    runtime = locate_flow_root(project_root) / "runtime"
    return runtime / "sessions" / f"{session_id}.yaml", runtime / "telemetry" / f"{session_id}.ndjson"


def write_session_metadata(project_root: Path, session_id: str, mode: str, snapshot_status: str, telemetry_path: Path) -> Path:
    session_path, _events_path = session_runtime_paths(project_root, session_id)
    snapshot_yaml, _snapshot_md = project_context_snapshot_paths(project_root)
    payload = {
        "schema_version": 1,
        "session": {
            "id": session_id,
            "mode": mode,
            "actor_type": "human_started_agent",
            "role": "orchestrator",
            "started_at": now_utc(),
        },
        "context": {
            "project_flow_root": flow_label(project_root),
            "snapshot": rel(snapshot_yaml, project_root),
            "snapshot_status": snapshot_status,
        },
        "telemetry": {"events": rel(telemetry_path, project_root)},
    }
    session_path.parent.mkdir(parents=True, exist_ok=True)
    session_path.write_text(ensure_trailing_newline(dump_yaml(payload)), encoding="utf-8")
    return session_path


def collect_action_rules(texts: dict[str, str]) -> tuple[list[str], list[str]]:
    allowed = {"read_required_sources"}
    forbidden = {"edit_forbidden_files", "rebuild_context_without_approval"}
    for text in texts.values():
        allowed.update(yaml_list_values(text, "allowed_actions"))
        forbidden.update(yaml_list_values(text, "forbidden_actions"))
    return sorted(allowed), sorted(forbidden)


def build_context_payload(project_root: Path, assignment: Path | None = None) -> tuple[dict[str, Any], dict[str, Any], str, str]:
    flow_root = locate_flow_root(project_root)
    sources = collect_context_sources(project_root, assignment)
    fingerprints = source_fingerprints(sources)
    texts = source_texts(project_root, sources)
    capabilities = resolve_capabilities(texts, project_root)
    allowed_actions, forbidden_actions = collect_action_rules(texts)

    conflicts: list[dict[str, str]] = []
    for item in sources:
        if item.get("required") and not item.get("exists"):
            conflicts.append({"status": "blocked", "message": f"required source missing: {item['path']}", "source": str(item["path"])})
    manifest_rel = rel(flow_root / "process-forge.yaml", project_root)
    manifest_text = texts.get(manifest_rel, "")
    if manifest_text:
        if not is_public_path_safe(manifest_text):
            conflicts.append({"status": "blocked", "message": "public manifest contains a local absolute path", "source": manifest_rel})
        if contains_secret_value(manifest_text):
            conflicts.append({"status": "blocked", "message": "public manifest contains a secret-like value", "source": manifest_rel})
    for capability in capabilities["missing_required"]:
        conflicts.append({"status": "blocked", "message": f"required capability is unresolved: {capability}", "source": "capabilities"})
    for capability in capabilities["missing_optional"]:
        conflicts.append({"status": "warn", "message": f"optional capability is unresolved: {capability}", "source": "capabilities"})

    overlap = sorted(set(allowed_actions).intersection(forbidden_actions))
    for action in overlap:
        conflicts.append({"status": "blocked", "message": f"action is both allowed and forbidden: {action}", "source": "resolved-rules"})

    gitignore = project_root / ".gitignore"
    if gitignore.is_file():
        ignore_text = gitignore.read_text(encoding="utf-8", errors="replace")
        if ".pf/runtime/" not in ignore_text:
            conflicts.append({"status": "warn", "message": "runtime cache path is not ignored", "source": ".gitignore"})
    if assignment is None:
        conflicts.append({"status": "warn", "message": "broad project context includes available sources that workers should not load by default", "source": "context-index"})

    if any(item["status"] == "blocked" for item in conflicts):
        status = "blocked"
    elif any(item["status"] == "requires_approval" for item in conflicts):
        status = "requires_approval"
    elif any(item["status"] == "warn" for item in conflicts):
        status = "warn"
    else:
        status = "resolved"

    selected_processes = [Path(str(item["path"])).stem for item in sources if item["kind"] == "process" and item["exists"]]
    selected_packages = [Path(str(item["path"])).stem for item in sources if item["kind"] == "package" and item["exists"]]
    selected_templates = [Path(str(item["path"])).name for item in sources if item["kind"] == "template" and item["exists"]]
    template_records = [
        {
            "id": safe_id(Path(str(item["path"])).stem, "template"),
            "path": str(item["path"]),
            "source": "project",
            "status": "selected" if item.get("load_policy") != "available" else "available",
        }
        for item in sources
        if item["kind"] == "template" and item["exists"]
    ]

    index = {
        "schema_version": 1,
        "context": {
            "id": "context-index",
            "generated_at": now_utc(),
            "mode": "context_resolve",
            "project_flow": manifest_rel,
        },
        "sources": sources,
        "selected_processes": selected_processes,
        "selected_packages": selected_packages,
        "selected_templates": selected_templates,
        "capabilities": capabilities,
        "fingerprints": fingerprints,
        "freshness": {"status": "fresh", "stale_sources": []},
    }
    resolved = {
        "schema_version": 1,
        "rules": {
            "hard": [
                {"id": "public-files-no-local-paths", "source": "process-forge.yaml"},
                {"id": "no-secret-values-in-generated-files", "source": "process-forge.yaml"},
            ],
            "locked": [{"id": "locked-hard-policies-cannot-be-weakened", "source": "process-forge.yaml"}],
            "preferences": [],
            "gates": [{"id": "blocked-conflicts-stop-context-compile", "source": "context-resolution"}],
            "tools": [{"id": "processforge-cli", "source": "tools/processforge.py"}],
            "templates": template_records,
        },
        "allowed_actions": allowed_actions,
        "forbidden_actions": forbidden_actions,
        "merge": {
            "order": [
                "core",
                "workplace",
                "organization",
                "direction",
                "specialization",
                "platform",
                "toolchain",
                "project",
                "process",
                "stage",
                "task",
                "agent_profile",
            ],
            "conflict_policy": "block_on_locked_policy_conflict",
        },
        "source_fingerprints": fingerprints,
    }
    report = render_conflict_report(status, conflicts, fingerprints)
    return index, resolved, report, status


def render_conflict_report(status: str, conflicts: list[dict[str, str]], fingerprints: dict[str, str]) -> str:
    blocking = [item for item in conflicts if item["status"] == "blocked"]
    warnings = [item for item in conflicts if item["status"] == "warn"]
    approvals = [item for item in conflicts if item["status"] == "requires_approval"]
    resolved = [item for item in conflicts if item["status"] == "resolved"]

    def lines(items: list[dict[str, str]]) -> list[str]:
        return [f"- {item['message']} ({item.get('source', 'unknown')})" for item in items] or ["- None."]

    output: list[str] = [
        "schema_version: 1",
        f"status: {status}",
        f"blocking_conflicts: {len(blocking)}",
        f"warnings: {len(warnings)}",
        f"requires_approval: {len(approvals)}",
        "",
        "# Context Conflict Report",
        "",
        "## Blocking Conflicts",
        "",
        *lines(blocking),
        "",
        "## Warnings",
        "",
        *lines(warnings),
        "",
        "## Requires Approval",
        "",
        *lines(approvals),
        "",
        "## Resolved",
        "",
        *lines(resolved),
        "",
        "## Source Fingerprints",
        "",
    ]
    output.extend(f"- {path}: {fingerprint}" for path, fingerprint in fingerprints.items())
    return "\n".join(output) + "\n"


def write_context_outputs(project_root: Path, assignment: Path | None = None) -> tuple[str, dict[str, Path]]:
    index, resolved, report, status = build_context_payload(project_root, assignment)
    flow_root = locate_flow_root(project_root)
    contexts = flow_root / "contexts"
    cache = flow_root / "runtime" / "cache"
    contexts.mkdir(parents=True, exist_ok=True)
    cache.mkdir(parents=True, exist_ok=True)
    paths = {
        "context_index": contexts / "context-index.yaml",
        "resolved_rules": contexts / "resolved-rules.yaml",
        "conflict_report": contexts / "context-conflict-report.md",
        "context_cache": cache / "context-cache.yaml",
    }
    paths["context_index"].write_text(ensure_trailing_newline(dump_yaml(index)), encoding="utf-8")
    paths["resolved_rules"].write_text(ensure_trailing_newline(dump_yaml(resolved)), encoding="utf-8")
    paths["conflict_report"].write_text(report, encoding="utf-8")
    cache_payload = {
        "schema_version": 1,
        "cache": {"id": "context-cache", "generated_at": now_utc(), "status": "fresh" if status != "blocked" else "stale"},
        "fingerprints": index["fingerprints"],
        "sources": index["sources"],
        "health": {"conflict_status": status},
    }
    paths["context_cache"].write_text(ensure_trailing_newline(dump_yaml(cache_payload)), encoding="utf-8")
    return status, paths


def context_report_status(path: Path) -> str:
    if not path.is_file():
        return "missing"
    text = path.read_text(encoding="utf-8", errors="replace")
    match = re.search(r"(?m)^status" + COLON_WS + r"([a-z_]+)\s*$", text)
    return match.group(1) if match else "missing"


def context_freshness(project_root: Path) -> tuple[str, list[str]]:
    index_path = locate_flow_root(project_root) / "contexts" / "context-index.yaml"
    if not index_path.is_file():
        return "missing", []
    text = index_path.read_text(encoding="utf-8", errors="replace")
    current_sources = collect_context_sources(project_root)
    stale: list[str] = []
    for item in current_sources:
        path = str(item["path"])
        fingerprint = str(item.get("fingerprint", "missing"))
        if path not in text or fingerprint not in text:
            stale.append(path)
    return ("fresh" if not stale else "stale"), stale


def assignment_id(path: Path) -> str:
    return safe_id(path.stem, "assignment")


def conflict_metric(report: str, key: str) -> int:
    match = re.search(rf"(?m)^{re.escape(key)}" + COLON_WS + r"(\d+)\s*$", report)
    return int(match.group(1)) if match else 0


def normalized_context_status(status: str) -> str:
    return "pass" if status == "resolved" else status


def unique_context_path(contexts: Path, assn_id: str, suffix: str) -> Path:
    stamp = now_utc().replace(":", "").replace("-", "").replace("Z", "z")
    return contexts / f"{assn_id}.{stamp}.{suffix}"


def ecp_checksum(payload: dict[str, Any]) -> str:
    stable = dict(payload)
    stable["checksum"] = "pending"
    return hashlib.sha256(ensure_trailing_newline(dump_yaml(stable)).encode("utf-8")).hexdigest()


def compile_execution_context(
    project_root: Path,
    assignment: Path,
    *,
    write_capsule: bool = False,
    supersede: bool = False,
    allow_requires_approval: bool = False,
) -> tuple[Path, Path | None, Path]:
    if not assignment.is_file():
        raise SystemExit(f"FAIL: assignment not found: {assignment}")

    index, resolved, report, status = build_context_payload(project_root, assignment)
    assn_id = assignment_id(assignment)
    flow_root = locate_flow_root(project_root)
    contexts = flow_root / "contexts"
    contexts.mkdir(parents=True, exist_ok=True)
    assignment_conflict_report = contexts / f"{assn_id}.conflicts.md"
    assignment_conflict_report.write_text(report, encoding="utf-8")

    if status == "blocked":
        raise SystemExit(f"FAIL: assignment context has blocking conflicts: {rel(assignment_conflict_report, project_root)}")
    if status == "requires_approval" and not allow_requires_approval:
        raise SystemExit(f"FAIL: assignment context requires approval: {rel(assignment_conflict_report, project_root)}")

    ecp_path = contexts / f"{assn_id}.ecp.yaml"
    supersedes: str | None = None
    if ecp_path.exists():
        if not supersede:
            raise SystemExit(f"FAIL: ECP already exists: {rel(ecp_path, project_root)}")
        supersedes = rel(ecp_path, project_root)
        ecp_path = unique_context_path(contexts, assn_id, "ecp.yaml")
    capsule_path: Path | None = contexts / f"{assn_id}.capsule.yaml" if write_capsule else None
    if capsule_path and capsule_path.exists():
        if not supersede:
            raise SystemExit(f"FAIL: capsule already exists: {rel(capsule_path, project_root)}")
        capsule_path = unique_context_path(contexts, assn_id, "capsule.yaml")

    sources = [
        {
            "path": item["path"],
            "checksum": item.get("checksum", "missing"),
            "kind": item.get("kind", "source"),
            "selection_reason": item.get("selection_reason", ""),
            "load_policy": item.get("load_policy", ""),
        }
        for item in index["sources"]
        if item.get("required") or item.get("load_policy") == "read_required"
    ]
    source_fingerprints = [{"path": item["path"], "checksum": item.get("checksum", "missing")} for item in sources]
    context_status = normalized_context_status(status)
    ecp = {
        "schema_version": 1,
        "id": f"{assn_id}-context",
        "type": "execution_context_package",
        "assignment": assn_id,
        "assignment_path": rel(assignment, project_root),
        "process": "assignment-execute",
        "stage": "assignment_execute",
        "role": "worker",
        "context_status": context_status,
        "blocking_conflicts": conflict_metric(report, "blocking_conflicts"),
        "warnings": conflict_metric(report, "warnings"),
        "requires_approval": conflict_metric(report, "requires_approval"),
        "conflict_report": rel(assignment_conflict_report, project_root),
        "source_fingerprints": source_fingerprints,
        "read_sources": [str(item["path"]) for item in sources],
        "resolved_rules": {
            "allowed_actions": resolved["allowed_actions"],
            "forbidden_actions": resolved["forbidden_actions"],
            "merge": resolved["merge"],
        },
        "allowed_files": [rel(assignment, project_root)],
        "forbidden_files": [],
        "required_outputs": [],
        "required_capabilities": index["capabilities"].get("required", []),
        "selected_tools": ["processforge-cli"],
        "selected_mcp": [],
        "selected_templates": resolved["rules"].get("templates", []),
        "created_at": now_utc(),
        "checksum": "pending",
        "context": {
            "id": f"{assn_id}-context",
            "created_at": now_utc(),
            "immutable": True,
            "context_index": rel(contexts / "context-index.yaml", project_root),
            "conflict_report": rel(assignment_conflict_report, project_root),
        },
        "task_input": [rel(assignment, project_root)],
        "sources": sources,
        "packages": [{"id": item, "status": "available"} for item in index.get("selected_packages", [])],
        "templates": resolved["rules"].get("templates", []),
        "allowed_actions": resolved["allowed_actions"],
        "forbidden_actions": resolved["forbidden_actions"],
        "quality_gates": ["doctor-context"],
        "checksums": {"assignment": sha256_file(assignment), "context_index": sha256_file(contexts / "context-index.yaml")},
    }
    if supersedes:
        ecp["supersedes"] = supersedes
    ecp["checksum"] = ecp_checksum(ecp)
    ecp_path.write_text(ensure_trailing_newline(dump_yaml(ecp)), encoding="utf-8")

    if write_capsule:
        assert capsule_path is not None
        capsule = {
            "schema_version": 1,
            "capsule": {
                "id": f"{assn_id}-capsule",
                "ecp": rel(ecp_path, project_root),
                "worker_may_rebuild_context": False,
            },
            "assignment": {"id": assn_id, "path": rel(assignment, project_root)},
            "context": {
                "freshness": context_freshness(project_root)[0],
                "conflict_status": status,
                "context_status": context_status,
                "conflict_report": rel(assignment_conflict_report, project_root),
            },
            "required_sources": [str(item["path"]) for item in sources],
            "allowed_files": [rel(assignment, project_root)],
            "forbidden_files": [],
            "allowed_actions": resolved["allowed_actions"],
            "forbidden_actions": resolved["forbidden_actions"],
        }
        capsule_path.write_text(ensure_trailing_newline(dump_yaml(capsule)), encoding="utf-8")
    return ecp_path, capsule_path, assignment_conflict_report


def recent_files(root: Path, dirname: str, limit: int = 5, *, rel_root: Path | None = None) -> list[str]:
    directory = root / dirname
    if not directory.is_dir():
        return []
    files = sorted((path for path in directory.rglob("*") if path.is_file()), key=lambda path: path.stat().st_mtime, reverse=True)
    return [rel(path, rel_root or root) for path in files[:limit]]


def render_session_status(project_root: Path, mode: str) -> str:
    flow_root = locate_flow_root(project_root)
    manifest = flow_root / "process-forge.yaml"
    manifest_text = manifest.read_text(encoding="utf-8", errors="replace") if manifest.is_file() else ""
    name_match = re.search(r"(?m)^\s*name" + COLON_WS + r"(.+?)\s*$", manifest_text)
    version_match = re.search(r"(?m)^\s*version" + COLON_WS + r"(.+?)\s*$", manifest_text)
    project_name = name_match.group(1).strip() if name_match else project_root.name
    flow_version = version_match.group(1).strip() if version_match else "unknown"
    snapshot_freshness, snapshot_stale, _snapshot = project_context_freshness(project_root)
    legacy_freshness, legacy_stale = context_freshness(project_root)
    freshness = snapshot_freshness if snapshot_freshness != "missing" else legacy_freshness
    stale = snapshot_stale if snapshot_freshness != "missing" else legacy_stale
    conflict_status = context_report_status(flow_root / "contexts" / "context-conflict-report.md")
    assignments = recent_files(flow_root, "assignments", rel_root=project_root)
    artifacts = recent_files(flow_root, "artifacts", rel_root=project_root)
    reviews = recent_files(flow_root, "reviews", rel_root=project_root)
    adrs = recent_files(flow_root, "adr", rel_root=project_root)

    def markdown_items(items: list[str]) -> str:
        return "\n".join(f"- {item}" for item in items) if items else "- None."

    blocked = []
    if conflict_status == "blocked":
        blocked.append("Context conflict report is blocked.")
    if freshness in {"missing", "stale"}:
        blocked.append(f"Context freshness is {freshness}.")

    return "\n".join(
        [
            "# ProcessForge Session Status",
            "",
            "## Project",
            "",
            project_name,
            "",
            "## Flow Version",
            "",
            flow_version,
            "",
            "## Project Flow Root",
            "",
            flow_label(project_root),
            "",
            "## Session Mode",
            "",
            mode,
            "",
            "## Context Freshness",
            "",
            freshness + (f": {', '.join(stale)}" if stale else ""),
            "",
            "## Completed Work",
            "",
            markdown_items(artifacts),
            "",
            "## Current Active Assignments",
            "",
            markdown_items(assignments),
            "",
            "## Blocked Items",
            "",
            markdown_items(blocked),
            "",
            "## Latest Reviews",
            "",
            markdown_items(reviews),
            "",
            "## Important ADR",
            "",
            markdown_items(adrs),
            "",
            "## Risks",
            "",
            "- Project context snapshot is the preferred operational map; context cache is only an accelerator.",
            "",
            "## Recommended Next Steps",
            "",
            "- Run project-context-refresh if the snapshot is stale or missing.",
            "- Run assignment-capsule before starting assignment workers.",
            "",
            "## Suggested Assignments",
            "",
            "- None.",
            "",
        ]
    )


def command_session_start(args: argparse.Namespace) -> int:
    if getattr(args, "agent", None):
        return command_agent_checkin(args)
    if not getattr(args, "mode", None):
        raise SystemExit("FAIL: session-start requires --mode for telemetry bootstrap or --agent for agent session check-in")
    if not getattr(args, "project_root", None):
        raise SystemExit("FAIL: --project-root is required for session-start telemetry bootstrap")
    project_root = Path(args.project_root).expanduser().resolve()
    if not project_root.is_dir():
        raise SystemExit(f"FAIL: project root not found: {project_root}")
    require_flow_root(project_root)
    session_id = telemetry_session_id()
    session_path, telemetry_path = session_runtime_paths(project_root, session_id)
    freshness, stale_reasons, snapshot = project_context_freshness(project_root)
    if args.rebuild_context_if_stale and freshness in {"missing", "stale"}:
        status, paths, snapshot, _old_reasons = write_project_context_snapshot_outputs(project_root, explicit_workplace=getattr(args, "workplace", None))
        freshness = status
        stale_reasons = []
        print(f"PROJECT_CONTEXT: {status}")
        for path in paths.values():
            print(f"WROTE: {rel(path, project_root)}")
    check_result = project_context_check_result(project_root, explicit_workplace=getattr(args, "workplace", None)) if project_context_snapshot_paths(project_root)[0].is_file() else {"status": freshness, "policy_action": "project-context-refresh", "recommended_action": "project-context-refresh"}
    print(f"PROJECT_CONTEXT_CHECK: {check_result.get('status')} policy_action={check_result.get('policy_action')}")
    if check_result.get("status") == "broken" and check_result.get("policy_action") == "block":
        print("PROJECT_CONTEXT_BLOCKED: broken snapshot")
        return 1
    write_session_metadata(project_root, session_id, args.mode, freshness, telemetry_path)
    emit_process_event(
        project_root,
        "session.started",
        session_id=session_id,
        payload={"mode": args.mode, "snapshot_status": freshness},
        correlation_id=session_id,
    )
    append_telemetry_event(telemetry_path, "session_start", mode=args.mode, actor="agent", session=session_id)
    append_telemetry_event(
        telemetry_path,
        "snapshot_check",
        path=rel(project_context_snapshot_paths(project_root)[0], project_root),
        status=check_result.get("status", freshness),
        policy_action=check_result.get("policy_action"),
        reasons=stale_reasons,
    )
    if freshness == "stale":
        emit_process_event(
            project_root,
            "context.snapshot.stale",
            severity="warn",
            session_id=session_id,
            payload={"reasons": stale_reasons},
            correlation_id=session_id,
        )
    flow_root = locate_flow_root(project_root)
    read_order = [
        flow_root / "AGENTS.md",
        flow_root / "process-forge.yaml",
        flow_root / "contexts" / "project-context.snapshot.md",
    ]
    for source in read_order:
        append_telemetry_event(telemetry_path, "source_read", path=rel(source, project_root), exists=source.is_file(), reason="session_start")
    assignment_path = Path(args.assignment).expanduser().resolve() if args.assignment else None
    append_telemetry_event(
        telemetry_path,
        "assignment_loaded",
        path=rel(assignment_path, project_root) if assignment_path else None,
        status="loaded" if assignment_path and assignment_path.is_file() else "not_provided",
    )
    if assignment_path:
        emit_process_event(
            project_root,
            "assignment.started",
            session_id=session_id,
            assignment_id_value=assignment_id(assignment_path),
            payload={"path": rel(assignment_path, project_root), "exists": assignment_path.is_file()},
            correlation_id=session_id,
        )
    capabilities = snapshot.get("capabilities", {}) if isinstance(snapshot, dict) else {}
    for capability in capabilities.get("required", []) if isinstance(capabilities, dict) else []:
        if isinstance(capability, dict):
            append_telemetry_event(telemetry_path, "capability_check", required=True, **capability)
    for capability in capabilities.get("optional", []) if isinstance(capabilities, dict) else []:
        if isinstance(capability, dict):
            append_telemetry_event(telemetry_path, "capability_check", required=False, **capability)
    append_telemetry_event(telemetry_path, "tool_selected", tool="processforge-cli", reason="session_start")
    selected_specializations = [specialization_resource_id(str(item)) for item in as_list(getattr(args, "specialization", []))]
    if selected_specializations:
        append_telemetry_event(telemetry_path, "specialization_switch", selected_specializations=selected_specializations, reason="explicit_session_start")
        emit_process_event(project_root, "context.snapshot.refreshed", session_id=session_id, payload={"selected_specializations": selected_specializations, "reason": "garage_mode_specialization_switch"}, correlation_id=session_id)
    append_telemetry_event(telemetry_path, "tool_invoked", tool="processforge-cli", command="session-start")
    emit_process_event(project_root, "tool.invoked", session_id=session_id, payload={"tool": "processforge-cli", "command": "session-start"}, correlation_id=session_id)
    append_telemetry_event(telemetry_path, "tool_failed", tool=None, status="skipped")
    emit_process_event(project_root, "tool.failed", severity="warn", session_id=session_id, payload={"status": "skipped"}, correlation_id=session_id)
    append_telemetry_event(telemetry_path, "mcp_check", status="skipped", reason="no required MCP declared")
    emit_process_event(project_root, "mcp.invoked", session_id=session_id, payload={"status": "skipped"}, correlation_id=session_id)
    append_telemetry_event(telemetry_path, "fallback_used", status="skipped")
    emit_process_event(project_root, "tool.invoked", session_id=session_id, payload={"status": "fallback skipped"}, correlation_id=session_id)
    append_telemetry_event(telemetry_path, "conflict_detected", status="none")
    append_telemetry_event(telemetry_path, "file_scope_checked", status="ok", flow_root=flow_label(project_root))
    report = render_session_status(project_root, args.mode)
    print(report, end="")
    if args.allow_write and not args.report_only:
        target = flow_root / "artifacts" / "session-status-report.md"
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(report, encoding="utf-8")
        append_telemetry_event(telemetry_path, "artifact_written", path=rel(target, project_root))
        emit_process_event(project_root, "artifact.updated", session_id=session_id, payload={"path": rel(target, project_root)}, correlation_id=session_id)
        print(f"WROTE: {rel(target, project_root)}")
    else:
        append_telemetry_event(telemetry_path, "artifact_written", status="skipped", reason="report_only")
    append_telemetry_event(telemetry_path, "review_requested", status="skipped")
    emit_process_event(project_root, "review.requested", session_id=session_id, payload={"status": "skipped"}, correlation_id=session_id)
    append_telemetry_event(telemetry_path, "handoff_created", status="skipped")
    emit_process_event(project_root, "artifact.updated", session_id=session_id, payload={"status": "handoff skipped"}, correlation_id=session_id)
    append_telemetry_event(telemetry_path, "doctor_run", status="skipped")
    append_telemetry_event(telemetry_path, "session_end", status="completed")
    emit_process_event(project_root, "session.ended", session_id=session_id, payload={"mode": args.mode, "status": "completed"}, correlation_id=session_id)
    print(f"SESSION: {rel(session_path, project_root)}")
    print(f"TELEMETRY: {rel(telemetry_path, project_root)}")
    return 0


def command_project_context_refresh(args: argparse.Namespace) -> int:
    project_root = Path(args.project_root).expanduser().resolve()
    if not project_root.is_dir():
        raise SystemExit(f"FAIL: project root not found: {project_root}")
    require_flow_root(project_root)
    if getattr(args, "dry_run", False):
        snapshot = build_project_context_snapshot(project_root, explicit_workplace=getattr(args, "workplace", None))
        current = project_context_check_result(project_root, explicit_workplace=getattr(args, "workplace", None))
        proposal = {
            "schema_version": 1,
            "created_at": now_utc(),
            "reason": getattr(args, "reason", None) or "manual",
            "before": {"snapshot_id": current.get("snapshot_id"), "status": current.get("status")},
            "after": {"snapshot_id": snapshot.get("snapshot", {}).get("id"), "status": "fresh"},
            "impact": {
                "new_capsules": "use_new_snapshot_generation",
                "existing_capsules": "remain_pinned",
            },
            "resolved_resources": snapshot.get("resolved", {}).get("knowledge_resources", []),
        }
        if getattr(args, "write_proposal", None):
            proposal_path = Path(args.write_proposal).expanduser()
            if not proposal_path.is_absolute():
                proposal_path = project_root / proposal_path
            proposal_path.parent.mkdir(parents=True, exist_ok=True)
            proposal_path.write_text(ensure_trailing_newline(dump_yaml(proposal)), encoding="utf-8")
            print(f"WROTE: {rel(proposal_path, project_root)}")
        else:
            print(dump_yaml(proposal), end="")
        return 0
    session_id = telemetry_session_id("project-context-refresh")
    _session_path, telemetry_path = session_runtime_paths(project_root, session_id)
    emit_process_event(project_root, "tool.invoked", session_id=session_id, payload={"command": "project-context-refresh", "reason": getattr(args, "reason", None)}, correlation_id=session_id)
    status, paths, snapshot, old_reasons = write_project_context_snapshot_outputs(project_root, explicit_workplace=getattr(args, "workplace", None))
    append_telemetry_event(telemetry_path, "session_start", mode="project_context_refresh", actor="agent")
    append_telemetry_event(telemetry_path, "snapshot_check", status="previous_" + ("stale" if old_reasons else "fresh"), reasons=old_reasons)
    for source in snapshot.get("sources", {}).get("fingerprints", []):
        if isinstance(source, dict):
            append_telemetry_event(telemetry_path, "source_read", path=source.get("path"), source_id=source.get("id"), reason="snapshot_fingerprint")
    for group in ("required", "optional"):
        for capability in snapshot.get("capabilities", {}).get(group, []):
            if isinstance(capability, dict):
                append_telemetry_event(telemetry_path, "capability_check", required=group == "required", **capability)
    append_telemetry_event(telemetry_path, "tool_selected", tool="processforge-cli", reason="project_context_refresh")
    append_telemetry_event(telemetry_path, "tool_invoked", tool="processforge-cli", command="project-context-refresh")
    emit_process_event(project_root, "tool.invoked", session_id=session_id, payload={"tool": "processforge-cli", "command": "project-context-refresh"}, correlation_id=session_id)
    append_telemetry_event(telemetry_path, "mcp_check", status="skipped", reason="no required MCP declared")
    emit_process_event(project_root, "mcp.invoked", session_id=session_id, payload={"status": "skipped"}, correlation_id=session_id)
    for path in paths.values():
        append_telemetry_event(telemetry_path, "artifact_written", path=rel(path, project_root))
        emit_process_event(project_root, "artifact.updated", session_id=session_id, payload={"path": rel(path, project_root)}, correlation_id=session_id)
    for group, event_type, severity in [
        ("required", "capability.missing", "error"),
        ("optional", "capability.missing", "warn"),
    ]:
        for capability in snapshot.get("capabilities", {}).get(group, []):
            if isinstance(capability, dict) and capability.get("status") == "missing":
                emit_process_event(project_root, event_type, severity=severity, session_id=session_id, payload={"capability": capability.get("id")}, correlation_id=session_id)
    append_telemetry_event(telemetry_path, "session_end", status="completed")
    health = snapshot.get("snapshot", {}).get("health", {}).get("status") if isinstance(snapshot.get("snapshot"), dict) else "pass"
    emit_process_event(
        project_root,
        "context.snapshot.refreshed",
        severity="warn" if health == "warn" else ("error" if health == "blocked" else "info"),
        session_id=session_id,
        payload={"status": status, "health": health, "paths": {key: rel(path, project_root) for key, path in paths.items()}},
        correlation_id=session_id,
    )
    workplace_manifest = resolve_project_workplace_manifest(project_root, getattr(args, "workplace", None))
    maintenance: dict[str, Any] | None = None
    if workplace_manifest:
        maintenance = search_index_maintenance_for_known_projects(
            workplace_manifest.parent,
            reason="project-context-refresh",
            project_roots=[project_root],
        )
    print(f"STATUS: {status}")
    for path in paths.values():
        print(f"WROTE: {rel(path, project_root)}")
    if maintenance:
        print_search_index_maintenance_summary(maintenance)
    print(f"TELEMETRY: {rel(telemetry_path, project_root)}")
    resource_readiness = snapshot.get("resource_readiness") if isinstance(snapshot.get("resource_readiness"), dict) else {}
    return 1 if resource_readiness.get("status") == "blocked" else 0


def command_project_context_check(args: argparse.Namespace) -> int:
    project_root = Path(args.project_root).expanduser().resolve()
    if not project_root.is_dir():
        raise SystemExit(f"FAIL: project root not found: {project_root}")
    require_flow_root(project_root)
    result = project_context_check_result(project_root, explicit_workplace=getattr(args, "workplace", None))
    result["session_start"] = bool(getattr(args, "session_start", False))
    result["check_update_candidates"] = getattr(args, "check_update_candidates", "if_due")
    if getattr(args, "write_report", None):
        report_path = Path(args.write_report).expanduser()
        if not report_path.is_absolute():
            report_path = project_root / report_path
        report_path.parent.mkdir(parents=True, exist_ok=True)
        lines = [
            "# Project Context Check Report",
            "",
            f"- snapshot_id: {result.get('snapshot_id')}",
            f"- status: {result.get('status')}",
            f"- policy_action: {result.get('policy_action')}",
            f"- recommended_action: {result.get('recommended_action')}",
            "",
            "## Updates Available",
            "",
            dump_yaml(result.get("updates_available", [])),
            "",
            "## Stale Resources",
            "",
            dump_yaml(result.get("stale_resources", [])),
            "",
            "## Broken References",
            "",
            dump_yaml(result.get("broken_refs", [])),
            "",
            "## Resource Readiness",
            "",
            dump_yaml(result.get("resource_readiness", {})),
            "",
            "## Execution Readiness",
            "",
            dump_yaml(result.get("execution_readiness", {})),
        ]
        report_path.write_text("\n".join(lines), encoding="utf-8")
        result["report"] = rel(report_path, project_root)
    if getattr(args, "json", False):
        print(json.dumps(result, ensure_ascii=False, indent=2, sort_keys=True))
    else:
        print(f"SNAPSHOT_ID: {result.get('snapshot_id')}")
        print(f"STATUS: {result.get('status')}")
        print(f"POLICY_ACTION: {result.get('policy_action')}")
        print(f"RECOMMENDED_ACTION: {result.get('recommended_action')}")
        for item in result.get("updates_available", []):
            print(f"UPDATE_AVAILABLE: {item.get('id')} {item.get('snapshot_version')} -> {item.get('available_version')}")
        for item in result.get("stale_resources", []):
            print(f"STALE: {item.get('id', 'project-context')}: {item.get('reason')}")
        for item in result.get("broken_refs", []):
            print(f"BROKEN: {item.get('id', 'project-context')}: {item.get('reason')}")
        resource_readiness = result.get("resource_readiness") if isinstance(result.get("resource_readiness"), dict) else {}
        execution_readiness = result.get("execution_readiness") if isinstance(result.get("execution_readiness"), dict) else {}
        if resource_readiness:
            print(f"RESOURCE_READINESS: {resource_readiness.get('status')}")
        if execution_readiness:
            print(f"EXECUTION_READINESS: {execution_readiness.get('status')}")
            for item in execution_readiness.get("missing_capabilities", []) if isinstance(execution_readiness.get("missing_capabilities"), list) else []:
                if isinstance(item, dict):
                    print(f"CAPABILITY_MISSING: {item.get('capability')} required_by={item.get('required_by')}")
    if result.get("status") == "broken":
        return 1
    if getattr(args, "strict", False) and result.get("status") != "fresh":
        return 1
    return 0


def mark_project_context_stale(project_root: Path, *, subject: str, reason: str, source: str = "manual") -> Path:
    marker_path = project_context_stale_marker_path(project_root)
    marker_path.parent.mkdir(parents=True, exist_ok=True)
    marker = {
        "schema_version": 1,
        "marked_at": now_utc(),
        "subject": subject,
        "reason": reason,
        "source": source,
        "status": "stale",
        "recommended_action": "project-context-check",
    }
    marker_path.write_text(json.dumps(marker, ensure_ascii=False, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    coordination = effective_project_coordination(project_root)
    if coordination.get("effective_mode") == "organized":
        flow_root = locate_flow_root(project_root)
        inbox_path = flow_root / "runtime" / "director" / "inbox" / f"context-stale-{safe_id(subject, 'subject')}.json"
        inbox_path.parent.mkdir(parents=True, exist_ok=True)
        inbox_path.write_text(json.dumps({"type": "context_snapshot_stale", **marker}, ensure_ascii=False, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    emit_process_event(project_root, "context.snapshot.stale", severity="warn", payload={"subject": subject, "reason": reason, "source": source})
    return marker_path


def command_project_context_mark_stale(args: argparse.Namespace) -> int:
    project_root = Path(args.project_root).expanduser().resolve()
    if not project_root.is_dir():
        raise SystemExit(f"FAIL: project root not found: {project_root}")
    require_flow_root(project_root)
    marker = mark_project_context_stale(project_root, subject=args.subject, reason=args.reason, source="project-context-mark-stale")
    print(f"MARKED_STALE: {rel(marker, project_root)}")
    return 0


def extract_assignment_front_matter(path: Path) -> dict[str, Any]:
    if not path.is_file():
        raise SystemExit(f"FAIL: assignment not found: {path}")
    if path.suffix.lower() in {".yaml", ".yml"}:
        return load_yaml_document(path)
    text = path.read_text(encoding="utf-8-sig", errors="replace")
    match = re.match(r"^---\r?\n(.*?)\r?\n---(?:\r?\n|$)", text, re.DOTALL)
    if not match:
        return {}
    front_matter = match.group(1).strip()
    try:
        import yaml  # type: ignore

        data = yaml.safe_load(front_matter)
        return data if isinstance(data, dict) else {}
    except ModuleNotFoundError:
        return parse_simple_yaml(front_matter)


ACTIVE_ASSIGNMENT_STATUSES = {"draft", "ready", "open", "pending", "in_progress", "blocked", "debugging", "review", "ready_for_review"}


def as_list(value: Any) -> list[Any]:
    if value is None:
        return []
    if isinstance(value, list):
        return value
    return [value]


def normalize_assignment_path(value: Any) -> str:
    text = str(value or "").strip().replace("\\", "/")
    while text.startswith("./"):
        text = text[2:]
    text = re.sub(r"/+", "/", text)
    return text.rstrip("/") if text not in {"", "/"} else text


def assignment_path_key(value: Any) -> str:
    text = normalize_assignment_path(value)
    return text.lower() if os.name == "nt" else text


def assignment_scope_items(value: Any) -> list[str]:
    items: list[str] = []
    seen: set[str] = set()
    for item in as_list(value):
        raw: Any = item
        if isinstance(item, dict):
            raw = item.get("path") or item.get("glob") or item.get("pattern") or item.get("file")
        text = normalize_assignment_path(raw)
        if text and text not in seen:
            items.append(text)
            seen.add(text)
    return items


def normalize_context_artifacts(value: Any) -> list[dict[str, Any]]:
    artifacts: list[dict[str, Any]] = []
    for item in as_list(value):
        if isinstance(item, dict):
            path = normalize_assignment_path(item.get("path"))
            if not path:
                continue
            artifacts.append(
                {
                    "path": path,
                    "role": str(item.get("role", "input")),
                    "required": bool(item.get("required", True)),
                    "mutable_by_worker": bool(item.get("mutable_by_worker", False)),
                }
            )
        else:
            path = normalize_assignment_path(item)
            if path:
                artifacts.append({"path": path, "role": "input", "required": True, "mutable_by_worker": False})
    return artifacts


def normalize_required_outputs(value: Any) -> list[dict[str, Any]]:
    outputs: list[dict[str, Any]] = []
    for item in as_list(value):
        if isinstance(item, dict):
            output_id = str(item.get("id") or item.get("name") or "").strip()
            if not output_id:
                continue
            record = dict(item)
            record["id"] = output_id
            record.setdefault("type", "unspecified")
            record.setdefault("required", True)
            outputs.append(record)
        else:
            text = str(item or "").strip()
            if not text:
                continue
            if "=" in text:
                record: dict[str, Any] = {}
                for part in text.split(","):
                    if "=" not in part:
                        continue
                    key, raw_value = part.split("=", 1)
                    key = key.strip()
                    raw_value = raw_value.strip()
                    if key == "required":
                        record[key] = raw_value.lower() not in {"0", "false", "no"}
                    else:
                        record[key] = raw_value
                output_id = str(record.get("id") or record.get("name") or "").strip()
                if output_id:
                    record["id"] = output_id
                    record.setdefault("type", "unspecified")
                    record.setdefault("required", True)
                    outputs.append(record)
                continue
            outputs.append({"id": text, "type": "unspecified", "required": True})
    return outputs


def parse_required_output_waivers(value: Any) -> dict[str, str]:
    waivers: dict[str, str] = {}
    for item in as_list(value):
        text = str(item or "").strip()
        if not text:
            continue
        output_id, sep, reason = text.partition(":")
        output_id = safe_id(output_id, "output")
        reason = reason.strip() if sep else ""
        if not reason:
            raise SystemExit(f"FAIL: required output waiver needs '<id>:<reason>': {text}")
        waivers[output_id] = reason
    return waivers


def task_output_path(project_root: Path, output: dict[str, Any]) -> Path | None:
    raw_path = str(output.get("path") or "").strip()
    if not raw_path:
        return None
    return project_root / normalize_assignment_path(raw_path)


def required_output_checks(project_root: Path, task: dict[str, Any], waivers: dict[str, str] | None = None, enforce_missing: bool = True) -> list[Check]:
    waiver_map = waivers or {}
    checks: list[Check] = []
    for output in normalize_required_outputs(task.get("required_outputs")):
        output_id = safe_id(str(output.get("id") or "output"), "output")
        if not bool(output.get("required", True)):
            checks.append(check("PASS", f"required output optional: {output_id}"))
            continue
        out_path = task_output_path(project_root, output)
        if out_path is None:
            if output_id in waiver_map:
                checks.append(check("WARN", f"required output without path waived: {output_id} ({waiver_map[output_id]})"))
            elif entry == ".codex/hooks.json" and not (project_root / entry).exists():
                checks.append(
                    check_with_hint(
                        "WARN",
                        ".gitignore does not predeclare optional .codex/hooks.json",
                        "Codex hooks are optional host telemetry and are not installed for a generic project.",
                        "add .codex/hooks.json only when opting into the project-local Codex integration",
                    )
                )
            else:
                checks.append(check("FAIL", f"required output has no path: {output_id}"))
            continue
        output_rel = normalize_assignment_path(str(output.get("path") or ""))
        if out_path.is_file():
            checks.append(check("PASS", f"required output exists: {output_rel}"))
        elif output_id in waiver_map:
            checks.append(check("WARN", f"required output waived: {output_id} ({waiver_map[output_id]})"))
        elif not enforce_missing:
            checks.append(check("WARN", f"required output pending: {output_rel}"))
        else:
            checks.append(check("FAIL", f"required output missing: {output_rel}"))
    expected = task.get("expected_report") if isinstance(task.get("expected_report"), dict) else {}
    expected_artifact = normalize_assignment_path(str(expected.get("artifact") or ""))
    if expected_artifact:
        expected_path = project_root / expected_artifact
        if expected_path.is_file():
            checks.append(check("PASS", f"expected report exists: {expected_artifact}"))
        elif "expected-report" in waiver_map or "expected_report" in waiver_map:
            waiver_reason = waiver_map.get("expected-report") or waiver_map["expected_report"]
            checks.append(check("WARN", f"expected report waived: {expected_artifact} ({waiver_reason})"))
        elif not enforce_missing:
            checks.append(check("WARN", f"expected report pending: {expected_artifact}"))
        else:
            checks.append(check("FAIL", f"expected report missing: {expected_artifact}"))
    return checks


def normalize_execution_mode(value: Any) -> dict[str, Any]:
    if isinstance(value, dict):
        mode = dict(value)
    elif isinstance(value, str) and value.strip():
        mode = {"kind": value.strip()}
    else:
        return {}
    kind = str(mode.get("kind", "")).strip()
    if kind:
        mode["kind"] = kind
    mode.setdefault("code_changes_allowed", False)
    mode.setdefault("artifact_changes_allowed", True)
    mode.setdefault("requires_review", True)
    return mode


def normalize_ownership(metadata: dict[str, Any], allowed_files: list[str]) -> dict[str, Any]:
    raw = metadata.get("ownership") if isinstance(metadata.get("ownership"), dict) else {}
    owner_id = str(raw.get("owner_id") or metadata.get("id") or "assignment")
    owned_files = assignment_scope_items(raw.get("owned_files"))
    owned_globs = assignment_scope_items(raw.get("owned_globs"))
    if not owned_files and allowed_files:
        owned_files = list(allowed_files)
    return {
        "owner_id": safe_id(owner_id, "assignment"),
        "owner_label": str(raw.get("owner_label") or f"worker-{safe_id(owner_id, 'assignment')}"),
        "role": str(raw.get("role") or metadata.get("role") or ""),
        "writer": bool(raw.get("writer", bool(allowed_files or owned_files or owned_globs))),
        "owned_files": owned_files,
        "owned_globs": owned_globs,
    }


def normalize_non_overlap(value: Any, current_write_scope: list[str]) -> dict[str, Any]:
    if not isinstance(value, dict):
        value = {}
    result = dict(value)
    active = result.get("active_parallel_tasks")
    if not isinstance(active, list):
        active = []
    if result.get("active_parallel_task"):
        active.append(
            {
                "id": result.get("active_parallel_task"),
                "owner": result.get("active_parallel_owner"),
                "write_scope": assignment_scope_items(result.get("active_parallel_scope")),
            }
        )
    normalized_active: list[dict[str, Any]] = []
    for item in active:
        if isinstance(item, dict):
            record = dict(item)
            if "write_scope" in record:
                record["write_scope"] = assignment_scope_items(record.get("write_scope"))
            normalized_active.append(record)
        elif item:
            normalized_active.append({"id": str(item), "write_scope": []})
    result["policy"] = str(result.get("policy") or "block_on_write_overlap")
    result["active_parallel_tasks"] = normalized_active
    result["current_write_scope"] = current_write_scope
    result.pop("active_parallel_task", None)
    result.pop("active_parallel_owner", None)
    result.pop("active_parallel_scope", None)
    return result


def assignment_write_scope(metadata: dict[str, Any]) -> list[str]:
    allowed = assignment_scope_items(metadata.get("allowed_files"))
    ownership = metadata.get("ownership") if isinstance(metadata.get("ownership"), dict) else {}
    owned = assignment_scope_items(ownership.get("owned_files"))
    owned.extend(assignment_scope_items(ownership.get("owned_globs")))
    owned.extend(assignment_scope_items(metadata.get("allowed_globs")))
    result: list[str] = []
    seen: set[str] = set()
    for item in [*allowed, *owned]:
        key = assignment_path_key(item)
        if key not in seen:
            result.append(item)
            seen.add(key)
    return result


def assignment_has_glob(value: str) -> bool:
    return any(char in value for char in "*?[")


def iter_repo_files(project_root: Path) -> list[str]:
    files: list[str] = []
    skipped = {".git", "__pycache__", ".mypy_cache", ".pytest_cache"}
    for path in project_root.rglob("*"):
        if any(part in skipped for part in path.parts):
            continue
        if path.is_file():
            files.append(rel(path, project_root))
    return files


def assignment_patterns_overlap(left: str, right: str, repo_files: list[str]) -> tuple[bool, str]:
    left_key = assignment_path_key(left)
    right_key = assignment_path_key(right)
    left_glob = assignment_has_glob(left_key)
    right_glob = assignment_has_glob(right_key)
    files = [assignment_path_key(item) for item in repo_files]
    if not left_glob and not right_glob:
        return (left_key == right_key, "same_file")
    if left_glob and not right_glob:
        return (fnmatch.fnmatch(right_key, left_key), "glob_matches_file")
    if right_glob and not left_glob:
        return (fnmatch.fnmatch(left_key, right_key), "file_matches_glob")
    if left_key == right_key:
        return True, "same_glob"
    if any(fnmatch.fnmatch(item, left_key) and fnmatch.fnmatch(item, right_key) for item in files):
        return True, "glob_matches_same_file"
    left_prefix = re.split(r"[*?\[]", left_key, maxsplit=1)[0]
    right_prefix = re.split(r"[*?\[]", right_key, maxsplit=1)[0]
    if left_prefix and right_prefix and (left_prefix.startswith(right_prefix) or right_prefix.startswith(left_prefix)):
        return True, "possible_glob_overlap"
    return False, ""


def assignment_scope_conflicts(
    current_id: str,
    current_scope: list[str],
    other_id: str,
    other_scope: list[str],
    repo_files: list[str],
    *,
    reason_prefix: str = "",
) -> list[dict[str, str]]:
    conflicts: list[dict[str, str]] = []
    for current_item in current_scope:
        for other_item in other_scope:
            overlaps, reason = assignment_patterns_overlap(current_item, other_item, repo_files)
            if overlaps:
                conflicts.append(
                    {
                        "current_assignment": current_id,
                        "current_scope": current_item,
                        "other_assignment": other_id,
                        "other_scope": other_item,
                        "reason": reason_prefix + reason,
                    }
                )
    return conflicts


def validate_assignment_scope_overlaps(
    project_root: Path,
    metadata: dict[str, Any],
    *,
    assignment_path: Path | None = None,
) -> dict[str, Any]:
    current_id = safe_id(str(metadata.get("id") or (assignment_path.stem if assignment_path else "assignment")), "assignment")
    current_scope = assignment_write_scope(metadata)
    forbidden_scope = assignment_scope_items(metadata.get("forbidden_files"))
    repo_files = iter_repo_files(project_root)
    conflicts = assignment_scope_conflicts(
        current_id,
        current_scope,
        current_id,
        forbidden_scope,
        repo_files,
        reason_prefix="assignment_forbidden_wins:",
    )
    flow_root = locate_flow_root(project_root)
    current_resolved = assignment_path.resolve() if assignment_path else None
    for candidate in sorted((flow_root / "assignments").glob("*.yaml")):
        if current_resolved and candidate.resolve() == current_resolved:
            continue
        other = load_yaml_document(candidate)
        if yaml_error(other):
            continue
        status = str(other.get("status", "")).strip()
        if status not in ACTIVE_ASSIGNMENT_STATUSES:
            continue
        other_scope = assignment_write_scope(other)
        if not other_scope:
            continue
        other_id = safe_id(str(other.get("id") or candidate.stem), "assignment")
        current_deps = assignment_dependency_set(metadata)
        other_deps = assignment_dependency_set(other)
        if other_id in current_deps or current_id in other_deps:
            continue
        conflicts.extend(assignment_scope_conflicts(current_id, current_scope, other_id, other_scope, repo_files))
    return {"status": "fail" if conflicts else "pass", "conflicts": conflicts}


def overlap_allowed_check(overlap_check: dict[str, Any], source: str) -> dict[str, Any]:
    resolved = dict(overlap_check)
    resolved["policy"] = "allow"
    resolved["source"] = source
    if resolved.get("status") == "fail":
        resolved["status"] = "allowed"
        resolved["behavior"] = "write scope overlap allowed by resolved plan policy"
    return resolved


def assignment_allows_write_scope_overlap(metadata: dict[str, Any]) -> bool:
    non_overlap = metadata.get("non_overlap") if isinstance(metadata.get("non_overlap"), dict) else {}
    return str(non_overlap.get("policy") or "") == "allow_write_scope_overlap"


def assignment_dependency_set(metadata: dict[str, Any]) -> set[str]:
    dependencies = metadata.get("dependencies") if isinstance(metadata.get("dependencies"), dict) else {}
    values = [
        *as_list(dependencies.get("blocked_by")),
        *as_list(metadata.get("dependencies") if not isinstance(metadata.get("dependencies"), dict) else []),
        *as_list(metadata.get("depends_on")),
    ]
    return {safe_id(str(item), "assignment") for item in values if item}


def normalized_assignment_contract(project_root: Path, assignment: Path, metadata: dict[str, Any]) -> dict[str, Any]:
    snapshot_yaml, _snapshot_md = project_context_snapshot_paths(project_root)
    assignment_rel = rel(assignment, project_root)
    required_sources = assignment_scope_items([rel(snapshot_yaml, project_root), assignment_rel, *as_list(metadata.get("required_sources"))])
    context_artifacts = normalize_context_artifacts(metadata.get("context_artifacts"))
    allowed_files = assignment_scope_items(metadata.get("allowed_files"))
    allowed_read_files = assignment_scope_items(metadata.get("allowed_read_files"))
    forbidden_files = assignment_scope_items(metadata.get("forbidden_files"))
    ownership = normalize_ownership(metadata, allowed_files)
    write_scope = assignment_write_scope({"allowed_files": allowed_files, "ownership": ownership})
    non_overlap = normalize_non_overlap(metadata.get("non_overlap"), write_scope)
    return {
        "assignment": {
            "id": safe_id(str(metadata.get("id", assignment.stem)), "assignment"),
            "path": assignment_rel,
            "status": metadata.get("status", "ready"),
            "objective": metadata.get("objective", ""),
            "execution_mode": normalize_execution_mode(metadata.get("execution_mode")),
        },
        "context": {"required_sources": required_sources, "context_artifacts": context_artifacts},
        "scope": {
            "allowed_files": allowed_files,
            "allowed_read_files": allowed_read_files,
            "forbidden_files": forbidden_files,
            "ownership": ownership,
            "non_overlap": non_overlap,
        },
        "outputs": {
            "required_outputs": normalize_required_outputs(metadata.get("required_outputs")),
            "expected_report": metadata.get("expected_report") if isinstance(metadata.get("expected_report"), dict) else {},
        },
        "workspace_access": normalize_workspace_access(metadata.get("workspace_access")),
        "agent_model": normalize_agent_model(metadata.get("agent_model") or metadata.get("model") or ""),
        "agent_reasoning_effort": normalize_agent_reasoning_effort(metadata.get("agent_reasoning_effort") or metadata.get("reasoning_effort") or ""),
        "subagent_policy": normalize_subagent_policy(metadata.get("subagent_policy")),
    }


WORKSPACE_ACCESS_KEYS = ("knowledge_resources", "templates", "tools", "mcp")


def normalize_workspace_access(value: Any) -> dict[str, list[Any]]:
    raw = value if isinstance(value, dict) else {}
    aliases = {
        "knowledge": "knowledge_resources",
        "resources": "knowledge_resources",
        "knowledge_resource_refs": "knowledge_resources",
        "template_refs": "templates",
        "tool_refs": "tools",
        "mcp_refs": "mcp",
        "mcp_servers": "mcp",
    }
    result: dict[str, list[Any]] = {key: [] for key in WORKSPACE_ACCESS_KEYS}
    for key, target in aliases.items():
        if key in raw:
            result[target].extend(as_list(raw.get(key)))
    for key in WORKSPACE_ACCESS_KEYS:
        result[key].extend(as_list(raw.get(key)))
    cleaned: dict[str, list[Any]] = {}
    for key, items in result.items():
        normalized: list[Any] = []
        seen: set[str] = set()
        for item in items:
            if isinstance(item, dict):
                marker = json.dumps(item, sort_keys=True, ensure_ascii=False)
                normalized_item: Any = {str(k): v for k, v in item.items()}
            else:
                text = str(item).strip()
                if not text:
                    continue
                marker = text
                normalized_item = text
            if marker in seen:
                continue
            seen.add(marker)
            normalized.append(normalized_item)
        cleaned[key] = normalized
    return cleaned


def workspace_access_public_path_issues(access: dict[str, list[Any]]) -> list[str]:
    issues: list[str] = []
    for group, items in access.items():
        for index, item in enumerate(items):
            if isinstance(item, str):
                if path_string_is_absolute(item) or PATH_CONSTANT_PATTERN.search(item):
                    issues.append(f"workspace_access.{group}[{index}] must be an id/path_ref, not a private path")
                continue
            if not isinstance(item, dict):
                continue
            if "path" in item or "resolved_path" in item or "absolute_path" in item:
                issues.append(f"workspace_access.{group}[{index}] must not include raw path fields")
            for key, value in item.items():
                if str(key) == "path_ref":
                    continue
                if isinstance(value, str) and (path_string_is_absolute(value) or PATH_CONSTANT_PATTERN.search(value)):
                    issues.append(f"workspace_access.{group}[{index}].{key} must not include a private path")
    return issues


def validate_assignment_required_sources(project_root: Path, contract: dict[str, Any]) -> list[str]:
    missing: list[str] = []
    required_sources = contract.get("context", {}).get("required_sources", [])
    for source in required_sources if isinstance(required_sources, list) else []:
        path = project_root / str(source)
        if not path.is_file():
            missing.append(str(source))
    artifacts = contract.get("context", {}).get("context_artifacts", [])
    for item in artifacts if isinstance(artifacts, list) else []:
        if isinstance(item, dict) and item.get("required", True):
            source = str(item.get("path", ""))
            if source and not (project_root / source).is_file():
                missing.append(source)
    return sorted(set(missing))


def capsule_coordination_block(snapshot: dict[str, Any], metadata: dict[str, Any]) -> dict[str, Any]:
    coordination = snapshot.get("workplace_coordination") if isinstance(snapshot.get("workplace_coordination"), dict) else {}
    effective_mode = str(coordination.get("effective_mode") or "simple")
    raw_requirements = metadata.get("coordination_requirements") if isinstance(metadata.get("coordination_requirements"), dict) else {}
    inbox_requirements = raw_requirements.get("director_inbox") if isinstance(raw_requirements.get("director_inbox"), dict) else {}
    submit_required = bool(inbox_requirements.get("required", False) or metadata.get("director_inbox_submit_required", False))
    if effective_mode != "organized":
        if submit_required:
            raise SystemExit("FAIL: assignment requires Director inbox but project effective coordination mode is simple")
        return {
            "effective_mode": "simple",
            "director_required": False,
            "director_available_at_workplace": bool(coordination.get("director_available_at_workplace", False)),
        }
    director_inbox = coordination.get("director_inbox") if isinstance(coordination.get("director_inbox"), dict) else {}
    return {
        "effective_mode": "organized",
        "director_required": bool(coordination.get("director_required", True)),
        "director_process": coordination.get("director_process") or "agent-director-supervision",
        "director_inbox": {
            "enabled": bool(director_inbox.get("enabled", True)),
            "submit_required": submit_required or bool(director_inbox.get("submit_required", False)),
            "allowed_message_types": director_inbox.get("allowed_message_types", ["worker_report", "error_report", "decision_request"]),
        },
    }


def command_assignment_capsule(args: argparse.Namespace) -> int:
    project_root = Path(args.project_root).expanduser().resolve()
    require_flow_root(project_root)
    assignment = Path(args.assignment).expanduser().resolve()
    metadata = extract_assignment_front_matter(assignment)
    if not metadata:
        raise SystemExit("FAIL: assignment has no YAML front matter; it is human-readable only and cannot produce an automated capsule")
    status, reasons, snapshot = project_context_freshness(project_root)
    if status not in {"fresh", "fresh_with_updates"}:
        raise SystemExit("FAIL: project context snapshot is not fresh: " + (", ".join(reasons) if reasons else status))
    assn_id = safe_id(str(metadata.get("id", assignment.stem)), "assignment")
    required = [str(item) for item in metadata.get("required_capabilities", [])] if isinstance(metadata.get("required_capabilities"), list) else []
    optional = [str(item) for item in metadata.get("optional_capabilities", [])] if isinstance(metadata.get("optional_capabilities"), list) else []
    providers = load_registry_capability_providers(project_root, resolve_project_workplace_manifest(project_root))
    required_records, optional_records = capability_records(required, optional, providers)
    missing_required = [item["id"] for item in required_records if item.get("status") == "missing"]
    if missing_required:
        for capability in missing_required:
            emit_process_event(project_root, "capability.missing", severity="error", assignment_id_value=assn_id, assignment_path=rel(assignment, project_root), payload={"capability": capability})
        raise SystemExit("FAIL: required capabilities missing: " + ", ".join(missing_required))
    flow_root = locate_flow_root(project_root)
    telemetry_rel = rel(flow_root / "runtime" / "telemetry" / f"{assn_id}.ndjson", project_root)
    snapshot_yaml, _snapshot_md = project_context_snapshot_paths(project_root)
    snapshot_sha = "sha256:" + sha256_file(snapshot_yaml)
    snapshot_meta = snapshot.get("snapshot", {}) if isinstance(snapshot.get("snapshot"), dict) else {}
    contract = normalized_assignment_contract(project_root, assignment, metadata)
    workspace_access_issues = workspace_access_public_path_issues(contract["workspace_access"])
    if workspace_access_issues:
        raise SystemExit("FAIL: workspace access must use public refs: " + "; ".join(workspace_access_issues))
    missing_sources = validate_assignment_required_sources(project_root, contract)
    if missing_sources:
        raise SystemExit("FAIL: assignment required sources missing: " + ", ".join(missing_sources))
    overlap_check = validate_assignment_scope_overlaps(project_root, metadata, assignment_path=assignment)
    if assignment_allows_write_scope_overlap(metadata):
        overlap_check = overlap_allowed_check(overlap_check, "plan.allow_write_scope_overlap")
    if overlap_check["status"] == "fail" and not args.force:
        raise SystemExit("FAIL: assignment write scope overlaps active assignments: " + dump_yaml(overlap_check))
    contract["scope"]["non_overlap"]["overlap_check"] = overlap_check
    assignment_parameter_resolution = resolve_assignment_parameters(project_root, snapshot, metadata)
    capsule = {
        "schema_version": 1,
        "capsule": {
            "id": f"{assn_id}-capsule",
            "generated_at": now_utc(),
            "assignment_id": assn_id,
            "assignment_path": rel(assignment, project_root),
            "assignment_checksum": sha256_file(assignment),
            "snapshot": rel(snapshot_yaml, project_root),
            "snapshot_checksum": sha256_file(snapshot_yaml),
            "immutable": True,
            "worker_may_rebuild_context": False,
        },
        "context_snapshot": {
            "id": snapshot_meta.get("id", "project-context"),
            "sha256": snapshot_sha,
            "generated_at": snapshot_meta.get("generated_at"),
            "freshness_at_creation": status,
        },
        "project_classification": snapshot.get("project_classification", {}),
        "resolved_resources": snapshot.get("resolved", {}).get("knowledge_resources", []) if isinstance(snapshot.get("resolved"), dict) else [],
        "resolved_parameters": assignment_parameter_resolution["resolved_parameters"],
        "parameter_resolution_summary": {
            "status": assignment_parameter_resolution["status"],
            "sources": assignment_parameter_resolution["sources"],
            "conflicts": assignment_parameter_resolution["conflicts"],
        },
        "effective_specializations": snapshot.get("selected_specializations", []),
        "project_override_summary": snapshot.get("applied_project_overrides", []),
        "active_resource_profile": (snapshot.get("resolved_context", {}) if isinstance(snapshot.get("resolved_context"), dict) else {}).get("active_resource_profile", {}),
        "execution_route_summary": (snapshot.get("resolved_context", {}) if isinstance(snapshot.get("resolved_context"), dict) else {}).get("execution_route", {}),
        "capability_resolution_summary": (snapshot.get("resolved_context", {}) if isinstance(snapshot.get("resolved_context"), dict) else {}).get("capability_resolution", {}),
        "effective_resources": (snapshot.get("resolved_context", {}) if isinstance(snapshot.get("resolved_context"), dict) else {}).get("effective_resources", []),
        "assignment": contract["assignment"],
        "context": {
            "snapshot_id": snapshot_meta.get("id", "project-context"),
            "freshness": status,
            "required_sources": contract["context"]["required_sources"],
            "context_artifacts": contract["context"]["context_artifacts"],
            "selected_specializations": [str(item.get("id")) for item in snapshot.get("selected_specializations", []) if isinstance(item, dict)],
            "applied_project_overrides": [str(item.get("target")) for item in snapshot.get("applied_project_overrides", []) if isinstance(item, dict)],
            "parameter_sources": [str(item.get("id")) for item in assignment_parameter_resolution["sources"] if isinstance(item, dict)],
        },
        "scope": contract["scope"],
        "outputs": contract["outputs"],
        "workspace_access": contract["workspace_access"],
        "agent_model": contract["agent_model"],
        "agent_reasoning_effort": contract["agent_reasoning_effort"],
        "subagent_policy": contract["subagent_policy"],
        "workplace_coordination": capsule_coordination_block(snapshot, metadata),
        "capabilities": {"required": required_records, "optional": optional_records},
        "telemetry": {"events": telemetry_rel, "event_correlation_id": f"assignment-{assn_id}"},
        "required_sources": contract["context"]["required_sources"],
        "allowed_files": contract["scope"]["allowed_files"],
        "forbidden_files": contract["scope"]["forbidden_files"],
        "required_outputs": contract["outputs"]["required_outputs"],
        "required_capabilities": required_records,
        "optional_capabilities": optional_records,
        "selected_sources": metadata.get("selected_sources", []),
        "event_correlation_id": f"assignment-{assn_id}",
    }
    capsule_dir = flow_root / "contexts" / "assignment-capsules"
    capsule_dir.mkdir(parents=True, exist_ok=True)
    capsule_path = capsule_dir / f"{assn_id}.capsule.yaml"
    if capsule_path.exists() and not args.force:
        raise SystemExit(f"FAIL: capsule already exists: {rel(capsule_path, project_root)}")
    capsule_path.write_text(ensure_trailing_newline(dump_yaml(capsule)), encoding="utf-8")
    emit_process_event(project_root, "assignment.started", assignment_id_value=assn_id, assignment_path=rel(assignment, project_root), payload={"path": rel(assignment, project_root)}, correlation_id=f"assignment-{assn_id}")
    emit_process_event(project_root, "assignment.created", assignment_id_value=assn_id, assignment_path=rel(assignment, project_root), payload={"capsule": rel(capsule_path, project_root)}, correlation_id=f"assignment-{assn_id}")
    emit_process_event(project_root, "artifact.created", assignment_id_value=assn_id, assignment_path=rel(assignment, project_root), payload={"path": rel(capsule_path, project_root)}, correlation_id=f"assignment-{assn_id}")
    print(f"WROTE: {rel(capsule_path, project_root)}")
    if optional_records:
        missing_optional = [item["id"] for item in optional_records if item.get("status") == "missing"]
        if missing_optional:
            for capability in missing_optional:
                emit_process_event(project_root, "capability.missing", severity="warn", assignment_id_value=assn_id, assignment_path=rel(assignment, project_root), payload={"capability": capability}, correlation_id=f"assignment-{assn_id}")
            print("WARN: optional capabilities missing: " + ", ".join(missing_optional))
    return 0


def command_capsule_doctor(args: argparse.Namespace) -> int:
    project_root = Path(args.project_root).expanduser().resolve()
    require_flow_root(project_root)
    capsule_path = Path(args.capsule).expanduser()
    if not capsule_path.is_absolute():
        capsule_path = project_root / capsule_path
    capsule = load_yaml_document(capsule_path)
    checks: list[Check] = []
    if not capsule:
        return print_checks([check("FAIL", f"capsule missing or invalid: {capsule_path}")])
    context_snapshot = capsule.get("context_snapshot") if isinstance(capsule.get("context_snapshot"), dict) else {}
    context = capsule.get("context") if isinstance(capsule.get("context"), dict) else {}
    snapshot_id = str(context_snapshot.get("id") or context.get("snapshot_id") or "")
    snapshot_sha = str(context_snapshot.get("sha256") or "")
    snapshot_file = project_context_snapshot_generations_dir(project_root) / f"{snapshot_id}.yaml"
    current_snapshot, _current_md = project_context_snapshot_paths(project_root)
    pinned_exists = snapshot_file.is_file() or current_snapshot.is_file()
    checks.append(check("PASS" if snapshot_id else "FAIL", "capsule pins context snapshot id"))
    checks.append(check("PASS" if snapshot_sha.startswith("sha256:") or capsule.get("capsule", {}).get("snapshot_checksum") else "FAIL", "capsule pins context snapshot checksum"))
    checks.append(check("PASS" if pinned_exists else "FAIL", f"pinned snapshot exists: {snapshot_id or 'missing'}"))
    if snapshot_file.is_file() and snapshot_sha.startswith("sha256:"):
        checks.append(check("PASS" if "sha256:" + sha256_file(snapshot_file) == snapshot_sha else "WARN", "pinned snapshot generation checksum matches"))
    resources = capsule.get("resolved_resources") if isinstance(capsule.get("resolved_resources"), list) else []
    for item in resources:
        if not isinstance(item, dict):
            continue
        uses_latest = any(str(item.get(key) or "").lower() == "latest" for key in ["instance_id", "resolved_version", "resolved_generation"])
        reproducibility = item.get("reproducibility") if isinstance(item.get("reproducibility"), dict) else {}
        allowed_live = bool(item.get("non_reproducible_live_resource")) or reproducibility.get("level") == "non_reproducible"
        checks.append(check("FAIL" if uses_latest and not allowed_live else "PASS", f"resource {item.get('id', 'resource')} avoids unpinned latest"))
    return print_checks(checks)


RUN_STATUSES = {"draft", "open", "in_progress", "blocked", "review", "completed", "cancelled", "failed"}
TASK_STATUSES = {"open", "in_progress", "blocked", "debugging", "review", "done", "cancelled", "failed"}
ITERATION_KINDS = {"work", "debug", "fix", "review", "test", "research", "handoff", "note"}
ITERATION_STATUSES = {"planned", "in_progress", "completed", "passed", "failed", "cancelled"}


def run_root(project_root: Path, run_id: str) -> Path:
    return locate_flow_root(project_root) / "runs" / safe_id(run_id, "run")


def run_yaml_path(project_root: Path, run_id: str) -> Path:
    return run_root(project_root, run_id) / "run.yaml"


def assignment_yaml_path(project_root: Path, task_id: str) -> Path:
    return locate_flow_root(project_root) / "assignments" / f"{safe_id(task_id, 'task')}.yaml"


def task_artifacts_root(project_root: Path, run_id: str, task_id: str) -> Path:
    return locate_flow_root(project_root) / "artifacts" / "runs" / safe_id(run_id, "run") / safe_id(task_id, "task")


def read_yaml_file(path: Path) -> dict[str, Any]:
    data = load_yaml_document(path)
    error = yaml_error(data)
    if error:
        raise SystemExit(f"FAIL: {path} is invalid YAML: {error}")
    return data


def write_yaml_file(path: Path, data: dict[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(ensure_trailing_newline(dump_yaml(data)), encoding="utf-8")


def write_yaml_file_atomic(path: Path, data: dict[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(f".{path.name}.{uuid.uuid4().hex}.tmp")
    temporary.write_text(ensure_trailing_newline(dump_yaml(data)), encoding="utf-8")
    os.replace(temporary, path)


def write_text_file_atomic(path: Path, text: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(f".{path.name}.{uuid.uuid4().hex}.tmp")
    temporary.write_text(text, encoding="utf-8")
    os.replace(temporary, path)


@contextlib.contextmanager
def registry_file_lock(path: Path, *, timeout_seconds: float = 30.0, stale_after_seconds: float = 300.0) -> Any:
    path.parent.mkdir(parents=True, exist_ok=True)
    lock_path = path.with_name(f".{path.name}.lock")
    deadline = time.monotonic() + timeout_seconds
    while True:
        try:
            fd = os.open(str(lock_path), os.O_CREAT | os.O_EXCL | os.O_WRONLY)
            with os.fdopen(fd, "w", encoding="utf-8") as handle:
                handle.write(
                    json.dumps(
                        {
                            "path": str(path),
                            "pid": os.getpid(),
                            "created_at": now_utc(),
                        },
                        ensure_ascii=False,
                        indent=2,
                        sort_keys=True,
                    )
                    + "\n"
                )
            break
        except FileExistsError:
            try:
                age = time.time() - lock_path.stat().st_mtime
                if age > stale_after_seconds:
                    lock_path.unlink()
                    continue
            except OSError:
                pass
            if time.monotonic() >= deadline:
                raise SystemExit(f"FAIL: registry is locked by another writer: {lock_path}")
            time.sleep(0.1)
    try:
        yield
    finally:
        try:
            lock_path.unlink()
        except FileNotFoundError:
            pass


def parse_cli_bool(value: Any, *, name: str = "value") -> bool:
    if isinstance(value, bool):
        return value
    text = str(value).strip().lower()
    if text in {"1", "true", "yes", "y", "on"}:
        return True
    if text in {"0", "false", "no", "n", "off"}:
        return False
    raise SystemExit(f"FAIL: {name} must be true or false")


def normalize_project_coordination_mode(value: Any) -> str:
    mode = str(value or "inherit").strip().lower()
    if mode not in COORDINATION_PROJECT_MODES:
        raise SystemExit("FAIL: project coordination mode must be inherit, simple, or organized")
    return mode


def normalize_workplace_default_project_mode(value: Any) -> str:
    mode = str(value or "simple").strip().lower()
    if mode not in WORKPLACE_DEFAULT_PROJECT_MODES:
        raise SystemExit("FAIL: workplace default_project_mode must be simple or organized")
    return mode


def normalize_workplace_path(path: Path) -> Path:
    resolved = path.expanduser().resolve()
    if resolved.name == "workplace.yaml":
        return resolved.parent
    return resolved


def workplace_manifest_path_from_root(workplace: Path) -> Path:
    root = normalize_workplace_path(workplace)
    return root if root.name == "workplace.yaml" else root / "workplace.yaml"


def default_workplace_coordination() -> dict[str, Any]:
    return {
        "director_enabled": False,
        "director_office_enabled": False,
        "default_project_mode": "simple",
        "director": dict(DIRECTOR_OFFICE_DEFAULTS),
        "error_workflow_support": True,
    }


def default_project_coordination(mode: str = "inherit") -> dict[str, Any]:
    return {
        "mode": normalize_project_coordination_mode(mode),
        "director": {
            "use_workplace_director": True,
            "inbox_submit_required": False,
        },
    }


def workplace_coordination_config(workplace_manifest: Path | None) -> dict[str, Any]:
    config = default_workplace_coordination()
    if workplace_manifest and workplace_manifest.is_file():
        data = load_yaml_document(workplace_manifest)
        raw = data.get("coordination") if isinstance(data, dict) else None
        if isinstance(raw, dict):
            config.update({key: value for key, value in raw.items() if key != "director"})
            if isinstance(raw.get("director"), dict):
                director = dict(DIRECTOR_OFFICE_DEFAULTS)
                director.update(raw["director"])
                config["director"] = director
    config["director_enabled"] = bool(config.get("director_enabled", False))
    config["director_office_enabled"] = bool(config.get("director_office_enabled", False))
    config["default_project_mode"] = normalize_workplace_default_project_mode(config.get("default_project_mode"))
    if not isinstance(config.get("director"), dict):
        config["director"] = dict(DIRECTOR_OFFICE_DEFAULTS)
    return config


def project_coordination_config(project_root: Path) -> dict[str, Any]:
    flow_root = locate_flow_root(project_root)
    manifest = flow_root / "process-forge.yaml"
    data = load_yaml_document(manifest) if manifest.is_file() else {}
    raw = data.get("coordination") if isinstance(data, dict) else None
    config = default_project_coordination()
    if isinstance(raw, dict):
        config.update({key: value for key, value in raw.items() if key != "director"})
        director = config.get("director") if isinstance(config.get("director"), dict) else {}
        if isinstance(raw.get("director"), dict):
            director = dict(director)
            director.update(raw["director"])
        config["director"] = director
    config["mode"] = normalize_project_coordination_mode(config.get("mode"))
    if not isinstance(config.get("director"), dict):
        config["director"] = default_project_coordination()["director"]
    config["director"].setdefault("use_workplace_director", True)
    config["director"].setdefault("inbox_submit_required", False)
    return config


def resolve_project_workplace_manifest(project_root: Path, explicit_workplace: str | None = None) -> Path | None:
    if explicit_workplace:
        candidate = workplace_manifest_path_from_root(Path(explicit_workplace))
        return candidate if candidate.is_file() else candidate
    flow_root = locate_flow_root(project_root)
    local_config = flow_root / "process-forge.local.yaml"
    if local_config.is_file():
        return resolve_workplace_manifest(local_config)
    manifest = flow_root / "process-forge.yaml"
    if manifest.is_file():
        data = load_yaml_document(manifest)
        workplace_data = data.get("workplace") if isinstance(data, dict) else None
        if isinstance(workplace_data, dict) and workplace_data.get("reference") == "auto":
            return project_root / "workplace.yaml" if (project_root / "workplace.yaml").is_file() else None
    return None


def director_office_paths(workplace_root: Path, coordination: dict[str, Any] | None = None) -> dict[str, Path]:
    cfg = coordination or workplace_coordination_config(workplace_root / "workplace.yaml")
    director = cfg.get("director") if isinstance(cfg.get("director"), dict) else {}
    paths: dict[str, Path] = {}
    for key, default in DIRECTOR_OFFICE_DEFAULTS.items():
        if not key.endswith("_path"):
            continue
        raw = str(director.get(key) or default)
        path = Path(raw)
        paths[key] = path if path.is_absolute() else workplace_root / path
    return paths


def director_office_exists(workplace_root: Path, coordination: dict[str, Any] | None = None) -> bool:
    paths = director_office_paths(workplace_root, coordination)
    required = ["office_path", "inbox_path", "outbox_path", "cases_path", "history_path"]
    return all(paths[key].is_dir() for key in required)


def initialize_director_office(workplace_root: Path, coordination: dict[str, Any] | None = None) -> dict[str, Path]:
    paths = director_office_paths(workplace_root, coordination)
    for path in paths.values():
        path.mkdir(parents=True, exist_ok=True)
    agents = paths["office_path"] / "AGENTS.md"
    if not agents.exists():
        agents.write_text(
            ensure_trailing_newline(
                "# Director Office\n\n"
                "This is the workplace-level ProcessForge Director Office.\n\n"
                "- It coordinates organized projects only.\n"
                "- It does not take over simple projects by default.\n"
                "- Generated inbox, case, history, and runtime data stay outside public release archives.\n"
            ),
            encoding="utf-8",
        )
    manifest = paths["office_path"] / "process-forge.yaml"
    if not manifest.exists():
        write_yaml_file(
            manifest,
            {
                "schema_version": 1,
                "process_forge": {
                    "version": "1.0.0",
                    "mode": "file_only",
                    "runner_required": False,
                    "backend_required": False,
                },
                "project": {"id": "director-office", "name": "Director Office", "type": "workplace_process"},
                "coordination": {"mode": "organized"},
                "paths": {"inbox": "inbox", "outbox": "outbox", "cases": "cases", "history": "history", "runtime": "runtime"},
                "policies": {"workspace_scope": True, "simple_projects_opt_in_only": True},
            },
        )
    return paths


def effective_project_coordination(project_root: Path, explicit_workplace: str | None = None) -> dict[str, Any]:
    project_cfg = project_coordination_config(project_root)
    workplace_manifest = resolve_project_workplace_manifest(project_root, explicit_workplace)
    workplace_root = workplace_manifest.parent if workplace_manifest else None
    workplace_cfg = workplace_coordination_config(workplace_manifest)
    project_mode = normalize_project_coordination_mode(project_cfg.get("mode"))
    default_mode = normalize_workplace_default_project_mode(workplace_cfg.get("default_project_mode"))
    effective_mode = default_mode if project_mode == "inherit" else project_mode
    director_available = bool(workplace_cfg.get("director_enabled"))
    office_exists = bool(workplace_root and director_office_exists(workplace_root, workplace_cfg))
    director_required = effective_mode == "organized"
    result = {
        "project_root": normalize_path_string(str(project_root)),
        "project_id": project_id(project_root) if (locate_flow_root(project_root) / "process-forge.yaml").is_file() else safe_id(project_root.name, "project"),
        "project_mode": project_mode,
        "workplace_root": normalize_path_string(str(workplace_root)) if workplace_root else None,
        "workplace_manifest": normalize_path_string(str(workplace_manifest)) if workplace_manifest else None,
        "workplace_default_project_mode": default_mode,
        "workplace_director_enabled": director_available,
        "workplace_director_office_enabled": bool(workplace_cfg.get("director_office_enabled")),
        "director_office_exists": office_exists,
        "effective_mode": effective_mode,
        "director_available": director_available,
        "director_required": director_required,
        "director_process": str((workplace_cfg.get("director") or {}).get("process_id") or "agent-director-supervision"),
        "director_inbox": {
            "enabled": bool(director_available and effective_mode == "organized"),
            "submit_required": bool((project_cfg.get("director") or {}).get("inbox_submit_required", False)) if effective_mode == "organized" else False,
            "allowed_message_types": ["worker_report", "error_report", "decision_request"] if effective_mode == "organized" else ["operator_note"],
        },
    }
    if workplace_root:
        paths = director_office_paths(workplace_root, workplace_cfg)
        result["director_office"] = {key: normalize_path_string(str(value)) for key, value in paths.items()}
    return result


def coordination_doctor_checks(project_root: Path, explicit_workplace: str | None = None) -> list[Check]:
    status = effective_project_coordination(project_root, explicit_workplace)
    checks = [
        check("PASS", f"project coordination mode is {status['project_mode']}"),
        check("PASS", f"effective coordination mode is {status['effective_mode']}"),
    ]
    if status["effective_mode"] == "organized":
        checks.append(check("PASS" if status["workplace_director_enabled"] else "FAIL", "organized project has workplace director capability"))
        checks.append(check("PASS" if status["director_office_exists"] else "FAIL", "organized project has Director Office available"))
    else:
        checks.append(check("PASS", "simple project does not require Director Office"))
    return checks


def process_coordination_requirements(process_data: dict[str, Any]) -> dict[str, Any]:
    raw = process_data.get("coordination_requirements") if isinstance(process_data.get("coordination_requirements"), dict) else {}
    mode = str(raw.get("mode") or "simple_allowed")
    if mode not in PROCESS_COORDINATION_MODES:
        mode = "simple_allowed"
    return {
        "mode": mode,
        "director_inbox": raw.get("director_inbox") if isinstance(raw.get("director_inbox"), dict) else {"required": False, "optional": False},
        "error_workflow": raw.get("error_workflow") if isinstance(raw.get("error_workflow"), dict) else {"mode": "none"},
    }


def validate_process_against_project_mode(process_data: dict[str, Any], project_root: Path, *, force: bool = False) -> list[Check]:
    requirements = process_coordination_requirements(process_data)
    coordination = effective_project_coordination(project_root)
    effective_mode = str(coordination.get("effective_mode"))
    mode = str(requirements.get("mode"))
    if mode == "organized_required" and effective_mode != "organized":
        return [
            check(
                "WARN" if force else "FAIL",
                "organized_required process cannot run in effective simple project mode without --force or project migration",
            )
        ]
    if mode == "simple_allowed":
        inbox = requirements.get("director_inbox") if isinstance(requirements.get("director_inbox"), dict) else {}
        if bool(inbox.get("required")):
            return [check("FAIL", "simple_allowed process must not require Director inbox")]
    return [check("PASS", f"process coordination requirements match effective {effective_mode} mode")]


def _process_catalog_context(
    project_root: Path,
    *,
    workplace_manifest: Path | None = None,
) -> ProcessCatalogContext:
    resolved_project_root = project_root.expanduser().resolve()
    effective_workplace_manifest = workplace_manifest
    if effective_workplace_manifest is None:
        effective_workplace_manifest = resolve_project_workplace_manifest(resolved_project_root)
    return ProcessCatalogContext(
        project_root=resolved_project_root,
        flow_root=locate_flow_root(resolved_project_root),
        distribution_root=ROOT.resolve(),
        active_official_pack_ids=frozenset(active_process_pack_ids(effective_workplace_manifest)),
    )


def process_catalog_role(process: dict[str, Any]) -> str:
    return catalog_process_catalog_role(process)


def process_override_declared(process: dict[str, Any], overridden_process_id: str) -> bool:
    override = process.get("process_override") if isinstance(process.get("process_override"), dict) else {}
    return str(override.get("overrides") or "") == overridden_process_id and bool(str(override.get("reason") or "").strip())


def official_pack_manifest_records(root: Path | None = None) -> list[tuple[Path, dict[str, Any]]]:
    distribution_root = (root or ROOT).resolve()
    records: list[tuple[Path, dict[str, Any]]] = []
    for path in sorted((distribution_root / "packs" / "official").glob("*/package.yaml")):
        data = load_yaml_document(path)
        if (
            isinstance(data, dict)
            and not yaml_error(data)
            and data.get("kind") == "processforge.pack"
            and data.get("origin") == "official"
            and data.get("id")
        ):
            records.append((path, data))
    return records


def official_pack_registry_entries_for_profile(profile: str) -> list[dict[str, Any]]:
    selected: list[dict[str, Any]] = []
    for _path, manifest in official_pack_manifest_records():
        activation = manifest.get("activation") if isinstance(manifest.get("activation"), dict) else {}
        profiles = {str(item) for item in as_list(activation.get("profiles")) if str(item)}
        if profile not in profiles:
            continue
        selected.append(
            {
                "id": str(manifest["id"]),
                "origin": "official",
                "status": "active",
                "version": str(manifest.get("version") or ""),
            }
        )
    return selected


def workplace_process_pack_registry(workplace_manifest: Path | None) -> dict[str, Any]:
    if not workplace_manifest or not workplace_manifest.is_file():
        return {"schema_version": 1, "process_packs": []}
    registry = load_workplace_registry(workplace_manifest, "process_packs", "process-packs.yaml")
    return registry if isinstance(registry, dict) else {"schema_version": 1, "process_packs": []}


def active_process_pack_ids(workplace_manifest: Path | None) -> set[str]:
    active: set[str] = set()
    for entry in as_list(workplace_process_pack_registry(workplace_manifest).get("process_packs")):
        if not isinstance(entry, dict):
            continue
        status = str(entry.get("status") or "active")
        if entry.get("id") and status in {"active", "enabled", "configured"}:
            active.add(str(entry["id"]))
    return active


def active_official_pack_records(workplace_manifest: Path | None) -> list[tuple[Path, dict[str, Any]]]:
    active_ids = active_process_pack_ids(workplace_manifest)
    return [
        (path, manifest)
        for path, manifest in official_pack_manifest_records()
        if str(manifest.get("id") or "") in active_ids
    ]


def official_pack_capability_providers(
    workplace_manifest: Path | None,
) -> tuple[set[str], dict[str, list[dict[str, Any]]]]:
    capabilities: set[str] = set()
    providers: dict[str, list[dict[str, Any]]] = {}
    for _path, manifest in active_official_pack_records(workplace_manifest):
        pack_id = str(manifest.get("id") or "")
        provided = manifest.get("provides") if isinstance(manifest.get("provides"), dict) else {}
        declared = {str(item) for item in as_list(provided.get("capabilities")) if str(item)}
        for tool in as_list(provided.get("tools")):
            if isinstance(tool, dict):
                declared.update(values_from_registry_entry(tool))
        capabilities.update(declared)
        for capability in declared:
            providers.setdefault(capability, []).append(
                {"provider": "active_process_pack", "process_pack": pack_id}
            )
    return capabilities, providers


def official_process_definition_refs(
    project_root: Path,
    *,
    include_available: bool = False,
    workplace_manifest: Path | None = None,
) -> list[ProcessDefinitionRef]:
    context = _process_catalog_context(project_root, workplace_manifest=workplace_manifest)
    return catalog_official_process_definition_refs(
        context,
        include_available=include_available,
    )


