def orchestrator_plan_path(project_root: Path, run_id: str) -> Path:
    return run_root(project_root, run_id) / "orchestrator-plan.yaml"


def worker_prompt_path(project_root: Path, run_id: str, task_id: str) -> Path:
    return run_root(project_root, run_id) / "worker-prompts" / f"{safe_id(task_id, 'task')}.md"


RUNTIME_DRIVER_PLACEHOLDERS = {
    "project_root",
    "processforge_root",
    "run_id",
    "task_id",
    "agent_run_dir",
    "driver_id",
    "capsule_path",
    "worker_prompt_path",
    "workspace_access_path",
    "expected_report_path",
    "python_executable",
    "executable",
    "stdout_path",
    "stderr_path",
    "heartbeat_path",
    "exit_path",
    "agent_model",
    "agent_reasoning_effort",
    "agent_sandbox",
}

AGENT_RUN_STATUSES = {
    "planned",
    "ready",
    "starting",
    "running",
    "completed",
    "failed",
    "timed_out",
    "unknown_exit",
    "lost",
    "blocked",
    "cancelled",
    "manual_required",
}

AGENT_RUN_FAILURE_TERMINAL_STATUSES = {"failed", "timed_out", "unknown_exit", "lost"}
AGENT_RUN_START_SKIP_STATUSES = {"running", "completed", "failed", "timed_out", "unknown_exit", "lost", "cancelled"}


def project_workplace_manifest(project_root: Path) -> Path | None:
    local_config = locate_flow_root(project_root) / "process-forge.local.yaml"
    if not local_config.is_file():
        return None
    data = load_yaml_document(local_config)
    workplace = data.get("workplace") if isinstance(data, dict) else {}
    manifest = workplace.get("manifest") if isinstance(workplace, dict) else None
    if not manifest:
        return None
    path = Path(str(manifest)).expanduser()
    if not path.is_absolute():
        path = (project_root / path).resolve()
    return path


def normalize_workplace_manifest(path: Path | None) -> Path | None:
    if path is None:
        return None
    candidate = path.expanduser().resolve()
    if candidate.is_dir():
        candidate = candidate / "workplace.yaml"
    return candidate


def runtime_driver_registry_paths(workplace_manifest: Path | None = None, project_root: Path | None = None) -> list[Path]:
    paths = [ROOT / "templates" / "registries" / "runtime-drivers.yaml"]
    if workplace_manifest and workplace_manifest.is_file():
        paths.append(workplace_manifest.parent / "registries" / "runtime-drivers.yaml")
    if project_root:
        paths.append(locate_flow_root(project_root) / "runtime" / "registries" / "runtime-drivers.local.yaml")
    return paths


def runtime_driver_entries(registry_path: Path) -> list[dict[str, Any]]:
    if not registry_path.is_file():
        return []
    data = load_yaml_document(registry_path)
    entries = data.get("runtime_drivers") if isinstance(data, dict) else []
    return [item for item in entries if isinstance(item, dict)]


def runtime_driver_entry_path(registry_path: Path, entry: dict[str, Any]) -> Path | None:
    raw = entry.get("path")
    if not raw:
        return None
    text = str(raw).replace("{processforge_root}", str(ROOT)).replace("${PF_DISTRIBUTION}", str(ROOT))
    path = Path(text).expanduser()
    if not path.is_absolute():
        path = (registry_path.parent / path).resolve()
    return path


def load_runtime_driver_by_path(path: Path) -> dict[str, Any]:
    if not path.is_file():
        raise SystemExit(f"FAIL: runtime driver not found: {path}")
    data = read_yaml_file(path)
    data.setdefault("_source_path", str(path))
    return data


def resolve_runtime_driver(driver_ref: str, *, workplace_manifest: Path | None = None, project_root: Path | None = None) -> dict[str, Any]:
    direct = Path(driver_ref).expanduser()
    if direct.suffix in {".yaml", ".yml", ".json"} or direct.is_file():
        if not direct.is_absolute():
            base = project_root or ROOT
            direct = (base / direct).resolve()
        return load_runtime_driver_by_path(direct)
    driver_id = safe_id(driver_ref, "manual")
    for registry_path in runtime_driver_registry_paths(workplace_manifest, project_root):
        for entry in runtime_driver_entries(registry_path):
            if str(entry.get("id")) != driver_id:
                continue
            path = runtime_driver_entry_path(registry_path, entry)
            if path and path.is_file():
                return load_runtime_driver_by_path(path)
    builtin = default_runtime_driver_documents().get(driver_id)
    if builtin:
        result = json.loads(json.dumps(builtin))
        result["_source_path"] = "builtin"
        return result
    raise SystemExit(f"FAIL: runtime driver not found: {driver_ref}")


def runtime_driver_ref_is_direct_path(driver_ref: str) -> bool:
    direct = Path(driver_ref).expanduser()
    return direct.suffix in {".yaml", ".yml", ".json"} or direct.is_file()


def normalized_runtime_driver_ref(driver_ref: str, project_root: Path) -> str:
    direct = Path(driver_ref).expanduser()
    if not direct.is_absolute():
        direct = (project_root / direct).resolve()
    try:
        return direct.relative_to(project_root).as_posix()
    except ValueError:
        return str(direct)


def runtime_driver_id_list(*, workplace_manifest: Path | None = None, project_root: Path | None = None) -> list[tuple[str, str, str]]:
    found: dict[str, tuple[str, str, str]] = {}
    for registry_path in runtime_driver_registry_paths(workplace_manifest, project_root):
        source = rel(registry_path, ROOT) if registry_path.is_relative_to(ROOT) else str(registry_path)
        for entry in runtime_driver_entries(registry_path):
            driver_id = str(entry.get("id") or "")
            if not driver_id:
                continue
            path = runtime_driver_entry_path(registry_path, entry)
            status = str(entry.get("status") or ("available" if path and path.is_file() else "missing"))
            found[driver_id] = (driver_id, status, source)
    for driver_id in default_runtime_driver_documents():
        found.setdefault(driver_id, (driver_id, "available", "builtin"))
    return sorted(found.values())


def driver_placeholder_errors(value: Any, label: str) -> list[str]:
    errors: list[str] = []
    if isinstance(value, str):
        for match in re.findall(r"\{([a-zA-Z0-9_]+)\}", value):
            if match not in RUNTIME_DRIVER_PLACEHOLDERS:
                errors.append(f"{label}: unsupported placeholder {{{match}}}")
    elif isinstance(value, list):
        for index, item in enumerate(value):
            errors.extend(driver_placeholder_errors(item, f"{label}[{index}]"))
    elif isinstance(value, dict):
        for key, item in value.items():
            errors.extend(driver_placeholder_errors(item, f"{label}.{key}"))
    return errors


def parse_runtime_driver_limits(driver: dict[str, Any]) -> tuple[dict[str, int], list[str]]:
    raw_limits = driver.get("limits") if isinstance(driver.get("limits"), dict) else {}
    parsed: dict[str, int] = {}
    errors: list[str] = []
    defaults = {"timeout_seconds": 30, "max_retries": 0}
    minimums = {"timeout_seconds": 1, "max_retries": 0}
    for key, default in defaults.items():
        raw_value = raw_limits.get(key, default)
        if isinstance(raw_value, bool):
            errors.append(f"limits.{key}: expected integer, got boolean")
            parsed[key] = default
            continue
        try:
            value = int(raw_value)
        except (TypeError, ValueError):
            errors.append(f"limits.{key}: expected integer, got {raw_value!r}")
            parsed[key] = default
            continue
        if value < minimums[key]:
            errors.append(f"limits.{key}: expected >= {minimums[key]}, got {value}")
        parsed[key] = value
    return parsed, errors


def minimal_platform_environment() -> dict[str, str]:
    if os.name != "nt":
        return {}
    names = ["SystemRoot", "WINDIR", "COMSPEC", "PATHEXT", "TEMP", "TMP"]
    return {name: value for name in names if (value := os.environ.get(name))}


def build_worker_environment(driver: dict[str, Any], variables: dict[str, str]) -> tuple[dict[str, str], bool]:
    env_spec = driver.get("environment") if isinstance(driver.get("environment"), dict) else {}
    inherit = bool(env_spec.get("inherit", True))
    # Persist only PF-owned and explicitly configured values. Inherited host
    # environment may contain credentials and is materialized only at launch.
    env = {} if inherit else minimal_platform_environment()
    env.update(
        {
            "PF_RUN_ID": variables["run_id"],
            "PF_TASK_ID": variables["task_id"],
            "PF_AGENT_RUN_DIR": variables["agent_run_dir"],
            "PF_AGENT_EXIT_PATH": variables["exit_path"],
            "PF_AGENT_MODEL": variables["agent_model"],
            "PF_AGENT_REASONING_EFFORT": variables["agent_reasoning_effort"],
            "PF_PROJECT_ROOT": variables["project_root"],
            "PF_RUNTIME_DRIVER_ID": variables["driver_id"],
            "PF_WORKSPACE_ACCESS_FILE": variables["workspace_access_path"],
            "PF_WORKER_RUN_ID": variables["run_id"],
            "PF_WORKER_TASK_ID": variables["task_id"],
            "PF_WORKER_ATTEMPT": variables["attempt"],
        }
    )
    explicit = env_spec.get("variables") if isinstance(env_spec.get("variables"), dict) else {}
    reserved = sorted(str(key) for key in explicit if str(key) in RESERVED_WORKER_ENV_KEYS)
    if reserved:
        raise SystemExit("FAIL: runtime driver cannot override reserved ProcessForge environment variables: " + ", ".join(reserved))
    expanded = expand_runtime_value(explicit, variables)
    env.update({str(key): str(value) for key, value in expanded.items()})
    return env, inherit


def materialize_worker_launch_environment(command_spec: dict[str, Any]) -> dict[str, str]:
    inherit = bool(command_spec.get("environment_inherit", False))
    env = os.environ.copy() if inherit else minimal_platform_environment()
    persisted = command_spec.get("environment") if isinstance(command_spec.get("environment"), dict) else {}
    env.update({str(key): str(value) for key, value in persisted.items()})
    return env


def runtime_driver_start_readiness_checks(driver: dict[str, Any], executable_override: str | None = None) -> list[Check]:
    checks: list[Check] = []
    kind = str(driver.get("kind") or "")
    if kind != "shell":
        return checks
    command = driver.get("command") if isinstance(driver.get("command"), dict) else {}
    raw_executable = str(command.get("executable") or "")
    security = driver.get("security") if isinstance(driver.get("security"), dict) else {}
    resolved_executable = executable_override or ("" if raw_executable == "{executable}" else raw_executable)
    if security.get("require_explicit_executable") is True and raw_executable == "{executable}" and not executable_override:
        checks.append(check("FAIL", "start readiness executable override required for {executable}"))
    elif not resolved_executable:
        checks.append(check("FAIL", "start readiness executable resolves to empty value"))
    else:
        checks.append(check("PASS", f"start readiness executable: {resolved_executable}"))
    return checks


def validate_runtime_driver_document(driver: dict[str, Any], executable_override: str | None = None, include_start_readiness: bool = False) -> list[Check]:
    checks: list[Check] = []
    driver_id = str(driver.get("id") or "")
    kind = str(driver.get("kind") or "")
    checks.append(check("PASS" if driver.get("schema_version") else "FAIL", "schema_version present"))
    checks.append(check("PASS" if driver_id else "FAIL", "id present"))
    checks.append(check("PASS" if kind in {"manual", "shell"} else "FAIL", f"kind valid: {kind or 'missing'}"))
    security = driver.get("security") if isinstance(driver.get("security"), dict) else {}
    env_spec = driver.get("environment") if isinstance(driver.get("environment"), dict) else {}
    explicit_env = env_spec.get("variables") if isinstance(env_spec.get("variables"), dict) else {}
    reserved_env = sorted(str(key) for key in explicit_env if str(key) in RESERVED_WORKER_ENV_KEYS)
    checks.append(check("FAIL" if reserved_env else "PASS", "reserved ProcessForge env vars not overridden" + (f": {', '.join(reserved_env)}" if reserved_env else "")))
    if kind == "shell":
        command = driver.get("command") if isinstance(driver.get("command"), dict) else {}
        executable = str(command.get("executable") or "")
        args = command.get("args") if isinstance(command.get("args"), list) else []
        model_args = command.get("model_args") if "model_args" in command else []
        checks.append(check("PASS" if executable else "FAIL", "shell command executable present"))
        checks.append(check("PASS" if isinstance(args, list) else "FAIL", "shell command args list present"))
        checks.append(check("PASS" if isinstance(model_args, list) else "FAIL", "shell command model_args list when present"))
        checks.append(check("WARN" if security.get("allow_shell") is True else "PASS", "allow_shell false by default"))
        network_reason = str(security.get("network_reason") or "").strip()
        checks.append(check("PASS" if security.get("allow_network") is not True or network_reason else "FAIL", "allow_network explicit reason when enabled"))
    if kind == "manual":
        behavior = driver.get("behavior") if isinstance(driver.get("behavior"), dict) else {}
        checks.append(check("PASS" if behavior.get("do_not_start_process") is True else "FAIL", "manual driver does not start process"))
    limits, limit_errors = parse_runtime_driver_limits(driver)
    for error in limit_errors:
        checks.append(check("FAIL", error))
    if not limit_errors:
        checks.append(check("PASS", f"limits valid: timeout_seconds={limits['timeout_seconds']} max_retries={limits['max_retries']}"))
    for error in driver_placeholder_errors(driver, "driver"):
        checks.append(check("FAIL", error))
    if include_start_readiness:
        checks.extend(runtime_driver_start_readiness_checks(driver, executable_override))
    return checks


def command_runtime_driver_list(args: argparse.Namespace) -> int:
    project_root = Path(args.project_root).expanduser().resolve() if getattr(args, "project_root", None) else None
    if project_root:
        require_flow_root(project_root)
    workplace_manifest = normalize_workplace_manifest(Path(args.workplace)) if getattr(args, "workplace", None) else (project_workplace_manifest(project_root) if project_root else None)
    for driver_id, status, source in runtime_driver_id_list(workplace_manifest=workplace_manifest, project_root=project_root):
        print(f"{driver_id}\t{status}\t{source}")
    return 0


def command_runtime_driver_validate(args: argparse.Namespace) -> int:
    project_root = Path(args.project_root).expanduser().resolve() if getattr(args, "project_root", None) else None
    if project_root:
        require_flow_root(project_root)
    workplace_manifest = normalize_workplace_manifest(Path(args.workplace)) if getattr(args, "workplace", None) else (project_workplace_manifest(project_root) if project_root else None)
    driver = resolve_runtime_driver(args.driver, workplace_manifest=workplace_manifest, project_root=project_root)
    return print_checks(validate_runtime_driver_document(driver, getattr(args, "executable", None), include_start_readiness=True))


def command_runtime_driver_describe(args: argparse.Namespace) -> int:
    project_root = Path(args.project_root).expanduser().resolve() if getattr(args, "project_root", None) else None
    if project_root:
        require_flow_root(project_root)
    workplace_manifest = normalize_workplace_manifest(Path(args.workplace)) if getattr(args, "workplace", None) else (project_workplace_manifest(project_root) if project_root else None)
    driver = resolve_runtime_driver(args.driver, workplace_manifest=workplace_manifest, project_root=project_root)
    driver.pop("_source_path", None)
    print(dump_yaml(driver))
    return 0


def agent_run_root(project_root: Path, run_id: str, task_id: str) -> Path:
    return locate_flow_root(project_root) / "runtime" / "agent-runs" / safe_id(run_id, "run") / safe_id(task_id, "task")


def supervisor_root(project_root: Path) -> Path:
    return locate_flow_root(project_root) / "runtime" / "supervisor"


def json_write(path: Path, data: dict[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(data, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")


def json_read(path: Path) -> dict[str, Any]:
    if not path.is_file():
        return {}
    return json.loads(path.read_text(encoding="utf-8"))


def expected_report_artifact(task: dict[str, Any]) -> str:
    expected = task.get("expected_report") if isinstance(task.get("expected_report"), dict) else {}
    value = str(expected.get("artifact") or "")
    if value:
        return normalize_assignment_path(value)
    task_id = safe_id(str(task.get("id") or "task"), "task")
    return f".pf/artifacts/{task_id}-report.md"


def worker_run_paths(project_root: Path, run_id: str, task_id: str) -> dict[str, Path]:
    root = agent_run_root(project_root, run_id, task_id)
    return {
        "root": root,
        "status": root / "status.json",
        "command": root / "command.json",
        "process": root / "process.json",
        "exit": root / "exit.json",
        "stdout": root / "stdout.log",
        "stderr": root / "stderr.log",
        "heartbeat": root / "heartbeat.json",
        "collection": root / "collection-report.md",
        "workspace_access": root / "workspace-access.json",
    }


DETACHED_WORKER_PROCESSES: dict[tuple[str, str, str], subprocess.Popen[bytes]] = {}


@contextlib.contextmanager
def worker_run_lifecycle_lock(project_root: Path, run_id: str, task_id: str) -> Any:
    root = agent_run_root(project_root, run_id, task_id)
    root.mkdir(parents=True, exist_ok=True)
    lock_path = root / ".lifecycle.lock"
    deadline = time.time() + 30.0
    fd: int | None = None
    while fd is None:
        try:
            fd = os.open(str(lock_path), os.O_CREAT | os.O_EXCL | os.O_WRONLY)
        except FileExistsError:
            if time.time() >= deadline:
                raise SystemExit(f"FAIL: worker run lifecycle lock unavailable for {run_id}/{task_id}")
            time.sleep(0.05)
    try:
        payload = {"schema_version": 1, "pid": os.getpid(), "created_at": now_utc()}
        os.write(fd, json.dumps(payload, ensure_ascii=False, sort_keys=True).encode("utf-8"))
        yield
    finally:
        if fd is not None:
            os.close(fd)
        lock_path.unlink(missing_ok=True)


def expand_runtime_value(value: Any, variables: dict[str, str]) -> Any:
    if isinstance(value, str):
        def replace(match: re.Match[str]) -> str:
            key = match.group(1)
            if key not in variables:
                raise SystemExit(f"FAIL: unsupported runtime placeholder: {{{key}}}")
            return variables[key]

        return re.sub(r"\{([a-zA-Z0-9_]+)\}", replace, value)
    if isinstance(value, list):
        return [str(expand_runtime_value(item, variables)) for item in value]
    if isinstance(value, dict):
        return {str(key): expand_runtime_value(item, variables) for key, item in value.items()}
    return value


def runtime_driver_for_task(project_root: Path, task: dict[str, Any], driver_arg: str | None = None) -> dict[str, Any]:
    driver_id = driver_arg or str(task.get("runtime_driver") or "manual")
    workplace_manifest = project_workplace_manifest(project_root)
    driver = resolve_runtime_driver(driver_id, workplace_manifest=workplace_manifest, project_root=project_root)
    if driver_arg and runtime_driver_ref_is_direct_path(driver_arg):
        driver = copy.deepcopy(driver)
        driver["_driver_ref"] = normalized_runtime_driver_ref(driver_arg, project_root)
    failures = [item.message for item in validate_runtime_driver_document(driver) if item.level == "FAIL"]
    if failures:
        raise SystemExit("FAIL: runtime driver invalid: " + "; ".join(failures))
    return driver


def runtime_driver_for_worker_state(project_root: Path, task: dict[str, Any], state: dict[str, Any], fallback_driver_ref: str | None = None) -> dict[str, Any]:
    task_id = safe_id(str(task.get("id") or state.get("task_id") or "task"), "task")
    run_id = safe_id(str(task.get("run_id") or state.get("run_id") or "run"), "run")
    command = json_read(worker_run_paths(project_root, run_id, task_id)["command"])
    driver_ref = command.get("driver_ref")
    if isinstance(driver_ref, str) and driver_ref.strip():
        try:
            return runtime_driver_for_task(project_root, task, driver_ref.strip())
        except SystemExit as exc:
            raise SystemExit(f"FAIL: saved runtime driver_ref invalid for {run_id}/{task_id}: {driver_ref}: {exc}") from exc
    driver_id = str(state.get("driver_id") or fallback_driver_ref or task.get("runtime_driver") or "manual")
    return runtime_driver_for_task(project_root, task, driver_id)


def worker_run_state_requires_reconciliation(project_root: Path, run_id: str, task_id: str, state: dict[str, Any]) -> bool:
    if str(state.get("status") or "") != "running":
        return False
    paths = worker_run_paths(project_root, run_id, task_id)
    if paths["exit"].is_file():
        return True
    pid = state.get("pid")
    if not isinstance(pid, int):
        return True
    command = json_read(paths["command"])
    started_at = str(state.get("started_at") or "")
    started_dt = parse_runtime_timestamp(started_at)
    timeout_seconds = int(state.get("timeout_seconds") or ((command.get("limits") if isinstance(command.get("limits"), dict) else {}).get("timeout_seconds") or 30))
    if started_dt and datetime.now(timezone.utc) > started_dt + timedelta(seconds=timeout_seconds):
        return True
    proc = DETACHED_WORKER_PROCESSES.get(worker_process_key(project_root, run_id, task_id))
    if proc is not None:
        return proc.poll() is not None
    return not process_pid_running(pid)


def existing_running_worker_run(project_root: Path, task: dict[str, Any], fallback_driver_ref: str | None = None) -> tuple[dict[str, Any], dict[str, Any], dict[str, Path]] | None:
    task_id = safe_id(str(task.get("id") or "task"), "task")
    run_id = safe_id(str(task.get("run_id") or "run"), "run")
    paths = worker_run_paths(project_root, run_id, task_id)
    state = load_agent_run_state(project_root, run_id, task_id)
    if str(state.get("status") or "") != "running":
        return None
    driver = runtime_driver_for_worker_state(project_root, task, state, fallback_driver_ref)
    observed = observe_worker_run(project_root, task, driver, state) if worker_run_state_requires_reconciliation(project_root, run_id, task_id, state) else state
    if str(observed.get("status") or "") == "running":
        return observed, driver, paths
    return None


def emit_worker_run_skip(project_root: Path, task: dict[str, Any], driver: dict[str, Any], state: dict[str, Any], event_type: str) -> None:
    task_id = safe_id(str(task.get("id") or state.get("task_id") or "task"), "task")
    run_id = safe_id(str(task.get("run_id") or state.get("run_id") or "run"), "run")
    pid = state.get("pid")
    emit_process_event(
        project_root,
        event_type,
        process_id=task_process_id(task),
        subject=task_id,
        assignment_id_value=task_id,
        assignment_path=rel(assignment_yaml_path(project_root, task_id), project_root),
        payload={"run_id": run_id, "driver_id": driver.get("id"), "status": "running", "pid": pid if isinstance(pid, int) else None, "reason": "already running"},
        correlation_id=f"run-{run_id}",
    )


def normalize_agent_model(value: Any) -> str:
    if value in (None, ""):
        return ""
    text = str(value).strip()
    if not text:
        return ""
    if any(char in text for char in "\r\n\0"):
        raise SystemExit("FAIL: agent model contains unsupported control characters")
    return text


def normalize_agent_reasoning_effort(value: Any) -> str:
    if value in (None, ""):
        return ""
    text = str(value).strip().lower()
    if not text:
        return ""
    if text not in {"minimal", "low", "medium", "high"}:
        raise SystemExit(f"FAIL: agent reasoning effort must be one of minimal, low, medium, high; got {text}")
    return text


def worker_sandbox_for_task(task: dict[str, Any]) -> str:
    execution = task.get("execution_mode") if isinstance(task.get("execution_mode"), dict) else {}
    ownership = task.get("ownership") if isinstance(task.get("ownership"), dict) else {}
    writable = ownership.get("writer") is True and (
        execution.get("code_changes_allowed") is True
        or execution.get("artifact_changes_allowed") is True
    )
    return "workspace-write" if writable else "read-only"


def build_worker_process_command(
    project_root: Path,
    task: dict[str, Any],
    driver: dict[str, Any],
    executable_override: str | None = None,
    *,
    attempt: int = 1,
) -> tuple[dict[str, Any], dict[str, Path]]:
    task_id = safe_id(str(task.get("id") or "task"), "task")
    run_id = safe_id(str(task.get("run_id") or "run"), "run")
    paths = worker_run_paths(project_root, run_id, task_id)
    capsule_path = locate_flow_root(project_root) / "contexts" / "assignment-capsules" / f"{task_id}.capsule.yaml"
    prompt_path = worker_prompt_path(project_root, run_id, task_id)
    report_path = project_root / expected_report_artifact(task)
    variables = {
        "project_root": str(project_root),
        "processforge_root": str(ROOT),
        "run_id": run_id,
        "task_id": task_id,
        "attempt": str(attempt),
        "agent_run_dir": str(paths["root"]),
        "driver_id": str(driver.get("id") or "manual"),
        "capsule_path": str(capsule_path),
        "worker_prompt_path": str(prompt_path),
        "workspace_access_path": str(paths["workspace_access"]),
        "expected_report_path": str(report_path),
        "python_executable": sys.executable,
        "executable": executable_override or "",
        "stdout_path": str(paths["stdout"]),
        "stderr_path": str(paths["stderr"]),
        "heartbeat_path": str(paths["heartbeat"]),
        "exit_path": str(paths["exit"]),
        "agent_model": normalize_agent_model(task.get("agent_model") or task.get("model") or ""),
        "agent_reasoning_effort": normalize_agent_reasoning_effort(task.get("agent_reasoning_effort") or task.get("reasoning_effort") or ""),
        "agent_sandbox": worker_sandbox_for_task(task),
    }
    io = driver.get("io") if isinstance(driver.get("io"), dict) else {}
    stdout_path = Path(str(expand_runtime_value(io.get("stdout") or rel(paths["stdout"], project_root), variables)))
    stderr_path = Path(str(expand_runtime_value(io.get("stderr") or rel(paths["stderr"], project_root), variables)))
    if not stdout_path.is_absolute():
        stdout_path = (project_root / stdout_path).resolve()
    if not stderr_path.is_absolute():
        stderr_path = (project_root / stderr_path).resolve()
    paths["stdout"] = stdout_path
    paths["stderr"] = stderr_path
    heartbeat = driver.get("heartbeat") if isinstance(driver.get("heartbeat"), dict) else {}
    heartbeat_path = Path(str(expand_runtime_value(heartbeat.get("path") or rel(paths["heartbeat"], project_root), variables)))
    if not heartbeat_path.is_absolute():
        heartbeat_path = (project_root / heartbeat_path).resolve()
    paths["heartbeat"] = heartbeat_path
    variables.update(
        {
            "stdout_path": str(paths["stdout"]),
            "stderr_path": str(paths["stderr"]),
            "heartbeat_path": str(paths["heartbeat"]),
            "exit_path": str(paths["exit"]),
        }
    )
    command_spec = driver.get("command") if isinstance(driver.get("command"), dict) else {}
    executable = executable_override or str(expand_runtime_value(command_spec.get("executable") or "", variables))
    args = expand_runtime_value(command_spec.get("args") if isinstance(command_spec.get("args"), list) else [], variables)
    if variables["agent_model"]:
        model_args_raw = command_spec.get("model_args") if "model_args" in command_spec else ["--model", "{agent_model}"]
        if not isinstance(model_args_raw, list):
            raise SystemExit("FAIL: runtime driver command.model_args must be a list when model is set")
        args.extend(expand_runtime_value(model_args_raw, variables))
    env, inherit_env = build_worker_environment(driver, variables)
    working_directory = str(expand_runtime_value(driver.get("working_directory") or "{project_root}", variables))
    command = {
        "schema_version": 1,
        "run_id": run_id,
        "task_id": task_id,
        "attempt": str(attempt),
        "driver_id": str(driver.get("id") or "manual"),
        "agent_model": variables["agent_model"],
        "agent_reasoning_effort": variables["agent_reasoning_effort"],
        "kind": str(driver.get("kind") or "manual"),
        "command": {
            "executable": executable,
            "args": args,
            "argv": [executable, *args] if executable else [],
            "working_directory": working_directory,
            "environment": {str(key): str(value) for key, value in env.items()},
            "environment_inherit": inherit_env,
            "shell": False,
        },
        "paths": {key: rel(path, project_root) for key, path in paths.items() if key != "root"},
        "limits": parse_runtime_driver_limits(driver)[0],
    }
    driver_ref = driver.get("_driver_ref")
    if isinstance(driver_ref, str) and driver_ref.strip():
        command["driver_ref"] = driver_ref.strip()
    return command, paths


def write_agent_run_state(
    project_root: Path,
    task: dict[str, Any],
    driver: dict[str, Any],
    status: str,
    *,
    pid: int | None = None,
    started_at: str | None = None,
    finished_at: str | None = None,
    exit_code: int | None = None,
    failure_reason: str | None = None,
    command: dict[str, Any] | None = None,
    paths: dict[str, Path] | None = None,
    attempt: int | None = None,
) -> dict[str, Any]:
    task_id = safe_id(str(task.get("id") or "task"), "task")
    run_id = safe_id(str(task.get("run_id") or "run"), "run")
    paths = paths or worker_run_paths(project_root, run_id, task_id)
    driver_limits, limit_errors = parse_runtime_driver_limits(driver)
    if limit_errors:
        raise SystemExit("FAIL: runtime driver invalid: " + "; ".join(limit_errors))
    previous_state = json_read(paths["status"])
    if attempt is None:
        try:
            attempt = max(1, int(previous_state.get("attempt") or 1))
        except (TypeError, ValueError):
            attempt = 1
    state = {
        "schema_version": 1,
        "run_id": run_id,
        "task_id": task_id,
        "driver_id": str(driver.get("id") or "manual"),
        "agent_model": normalize_agent_model(task.get("agent_model") or task.get("model") or ""),
        "status": status,
        "pid": pid,
        "started_at": started_at,
        "finished_at": finished_at,
        "exit_code": exit_code,
        "timeout_seconds": driver_limits["timeout_seconds"],
        "attempt": attempt,
        "max_retries": driver_limits["max_retries"],
        "capsule_path": rel(locate_flow_root(project_root) / "contexts" / "assignment-capsules" / f"{task_id}.capsule.yaml", project_root),
        "worker_prompt_path": rel(worker_prompt_path(project_root, run_id, task_id), project_root),
        "expected_report_path": expected_report_artifact(task),
        "stdout_path": rel(paths["stdout"], project_root),
        "stderr_path": rel(paths["stderr"], project_root),
        "heartbeat_path": rel(paths["heartbeat"], project_root),
        "last_heartbeat_at": None,
        "failure_reason": failure_reason,
    }
    if paths["heartbeat"].is_file():
        state["last_heartbeat_at"] = now_utc()
    json_write(paths["status"], state)
    if command:
        json_write(paths["command"], command)
    return state


def load_agent_run_state(project_root: Path, run_id: str, task_id: str) -> dict[str, Any]:
    return json_read(worker_run_paths(project_root, run_id, task_id)["status"])


def worker_process_key(project_root: Path, run_id: str, task_id: str) -> tuple[str, str, str]:
    return (str(project_root.resolve()), safe_id(run_id, "run"), safe_id(task_id, "task"))


def parse_runtime_timestamp(value: Any) -> datetime | None:
    if not value:
        return None
    try:
        text = str(value).replace("Z", "+00:00")
        return datetime.fromisoformat(text)
    except ValueError:
        return None


def terminate_worker_pid(pid: int) -> None:
    if os.name == "nt":
        subprocess.run(["taskkill", "/PID", str(pid), "/T", "/F"], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    else:
        try:
            os.kill(int(pid), signal.SIGTERM)
        except ProcessLookupError:
            return


def process_pid_running(pid: int) -> bool:
    if os.name == "nt":
        result = subprocess.run(["tasklist", "/FI", f"PID eq {pid}", "/FO", "CSV", "/NH"], stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, text=True, shell=False)
        return str(pid) in (result.stdout or "")
    try:
        os.kill(pid, 0)
        return True
    except ProcessLookupError:
        return False
    except PermissionError:
        return True


def observe_worker_run(project_root: Path, task: dict[str, Any], driver: dict[str, Any] | str, state: dict[str, Any]) -> dict[str, Any]:
    task_id = safe_id(str(task.get("id") or state.get("task_id") or "task"), "task")
    run_id = safe_id(str(task.get("run_id") or state.get("run_id") or "run"), "run")
    if isinstance(driver, str):
        driver = runtime_driver_for_worker_state(project_root, task, state, driver)
    paths = worker_run_paths(project_root, run_id, task_id)
    status = str(state.get("status") or "")
    if status != "running":
        return state
    pid = state.get("pid")
    if not isinstance(pid, int):
        return write_agent_run_state(project_root, task, driver, "failed", failure_reason="running state missing pid", paths=paths)
    command = json_read(paths["command"])
    started_at = str(state.get("started_at") or now_utc())
    exit_marker = json_read(paths["exit"])
    if exit_marker:
        marker_status = str(exit_marker.get("status") or "")
        marker_exit_code = exit_marker.get("exit_code")
        exit_code = marker_exit_code if isinstance(marker_exit_code, int) else None
        if marker_status not in AGENT_RUN_STATUSES or marker_status in {"planned", "ready", "starting", "running", "blocked", "manual_required"}:
            marker_status = "completed" if exit_code == 0 else "failed"
        finished_at = str(exit_marker.get("finished_at") or now_utc())
        failure_reason = str(exit_marker.get("failure_reason") or "") or None
        state = write_agent_run_state(project_root, task, driver, marker_status, pid=pid, started_at=started_at, finished_at=finished_at, exit_code=exit_code, failure_reason=failure_reason, command=command, paths=paths)
        DETACHED_WORKER_PROCESSES.pop(worker_process_key(project_root, run_id, task_id), None)
        emit_process_event(project_root, "worker.run.finished", process_id=task_process_id(task), subject=task_id, assignment_id_value=task_id, assignment_path=rel(assignment_yaml_path(project_root, task_id), project_root), payload={"run_id": run_id, "driver_id": driver.get("id"), "status": marker_status, "exit_code": exit_code}, correlation_id=f"run-{run_id}")
        return state
    started_dt = parse_runtime_timestamp(started_at)
    timeout_seconds = int(state.get("timeout_seconds") or ((command.get("limits") if isinstance(command.get("limits"), dict) else {}).get("timeout_seconds") or 30))
    timed_out = bool(started_dt and datetime.now(timezone.utc) > started_dt + timedelta(seconds=timeout_seconds))
    proc = DETACHED_WORKER_PROCESSES.get(worker_process_key(project_root, run_id, task_id))
    exit_code: int | None = proc.poll() if proc else None
    if timed_out and exit_code is None:
        if proc and proc.poll() is None:
            proc.kill()
        else:
            terminate_worker_pid(pid)
        finished_at = now_utc()
        state = write_agent_run_state(project_root, task, driver, "timed_out", pid=pid, started_at=started_at, finished_at=finished_at, exit_code=-1, failure_reason="timeout", command=command, paths=paths)
        json_write(paths["exit"], {"schema_version": 1, "exit_code": -1, "finished_at": finished_at, "status": "timed_out"})
        return state
    if exit_code is None:
        if proc is None and not process_pid_running(pid):
            lost_observed_at = parse_runtime_timestamp(state.get("lost_observed_at"))
            if lost_observed_at is None:
                observed_at = now_utc()
                state = write_agent_run_state(project_root, task, driver, "running", pid=pid, started_at=started_at, failure_reason="pid not alive; waiting for durable exit contract", command=command, paths=paths)
                state["lost_observed_at"] = observed_at
                json_write(paths["status"], state)
                return state
            if datetime.now(timezone.utc) < lost_observed_at + timedelta(seconds=0.25):
                return state
            finished_at = now_utc()
            failure_reason = "process exited without durable exit contract"
            state = write_agent_run_state(project_root, task, driver, "unknown_exit", pid=pid, started_at=started_at, finished_at=finished_at, exit_code=None, failure_reason=failure_reason, command=command, paths=paths)
            json_write(paths["exit"], {"schema_version": 1, "exit_code": None, "finished_at": finished_at, "status": "unknown_exit", "failure_reason": failure_reason})
            emit_process_event(project_root, "worker.run.finished", process_id=task_process_id(task), subject=task_id, assignment_id_value=task_id, assignment_path=rel(assignment_yaml_path(project_root, task_id), project_root), payload={"run_id": run_id, "driver_id": driver.get("id"), "status": "unknown_exit", "exit_code": None, "failure_reason": failure_reason}, correlation_id=f"run-{run_id}")
            return state
        else:
            return write_agent_run_state(project_root, task, driver, "running", pid=pid, started_at=started_at, command=command, paths=paths)
    finished_at = now_utc()
    final_status = "completed" if exit_code == 0 else "failed"
    state = write_agent_run_state(project_root, task, driver, final_status, pid=pid, started_at=started_at, finished_at=finished_at, exit_code=exit_code, command=command, paths=paths)
    json_write(paths["exit"], {"schema_version": 1, "exit_code": exit_code, "finished_at": finished_at, "status": final_status})
    DETACHED_WORKER_PROCESSES.pop(worker_process_key(project_root, run_id, task_id), None)
    emit_process_event(project_root, "worker.run.finished", process_id=task_process_id(task), subject=task_id, assignment_id_value=task_id, assignment_path=rel(assignment_yaml_path(project_root, task_id), project_root), payload={"run_id": run_id, "driver_id": driver.get("id"), "status": final_status, "exit_code": exit_code}, correlation_id=f"run-{run_id}")
    return state


def prepare_worker_run(project_root: Path, task_id: str, driver_arg: str | None = None, executable_override: str | None = None, model_arg: str | None = None, reasoning_effort_arg: str | None = None) -> tuple[dict[str, Any], dict[str, Any], dict[str, Path]]:
    task = load_task(project_root, task_id)
    agent_model = normalize_agent_model(model_arg or task.get("agent_model") or task.get("model") or "")
    agent_reasoning_effort = normalize_agent_reasoning_effort(reasoning_effort_arg or task.get("agent_reasoning_effort") or task.get("reasoning_effort") or "")
    if agent_model and task.get("agent_model") != agent_model:
        task["agent_model"] = agent_model
        save_task(project_root, task)
    if agent_reasoning_effort and task.get("agent_reasoning_effort") != agent_reasoning_effort:
        task["agent_reasoning_effort"] = agent_reasoning_effort
        save_task(project_root, task)
    run_id = safe_id(str(task.get("run_id") or "run"), "run")
    capsule_status, capsule_rel = existing_capsule_status(project_root, task_id)
    if capsule_status in {"fresh", "legacy"}:
        suffix = " (legacy capsule without assignment checksum)" if capsule_status == "legacy" else ""
        print(f"PRESENT: {capsule_rel}{suffix}")
    elif capsule_status == "stale":
        raise SystemExit(f"FAIL: assignment capsule is stale for {task_id}: {capsule_rel}; create a new capsule intentionally before launch")
    else:
        status, output = run_command_capture(
            command_assignment_capsule,
            argparse.Namespace(
                project_root=str(project_root),
                assignment=str(assignment_yaml_path(project_root, task_id)),
                force=assignment_allows_write_scope_overlap(task),
            ),
        )
        print(output, end="")
        if status:
            raise SystemExit(status)
    task = load_task(project_root, task_id)
    workspace_access_path = write_workspace_access_runtime_file(project_root, task)
    print(f"WROTE: {rel(workspace_access_path, project_root)}\n", end="")
    status, output = run_command_capture(command_worker_launch_prompt_create, argparse.Namespace(project_root=str(project_root), task=task_id, output=None, apply=True, dry_run=False))
    print(output, end="")
    if status:
        raise SystemExit(status)
    driver = runtime_driver_for_task(project_root, task, driver_arg)
    start_failures = [
        item.message
        for item in validate_runtime_driver_document(driver, executable_override, include_start_readiness=True)
        if item.level == "FAIL"
    ]
    if start_failures:
        raise SystemExit("FAIL: runtime driver is not start-ready: " + "; ".join(start_failures))
    paths = worker_run_paths(project_root, run_id, task_id)
    previous_state = json_read(paths["status"])
    try:
        attempt = max(1, int(previous_state.get("attempt") or 0) + 1)
    except (TypeError, ValueError):
        attempt = 1
    command, paths = build_worker_process_command(project_root, task, driver, executable_override, attempt=attempt)
    state_status = "manual_required" if str(driver.get("kind")) == "manual" else "ready"
    paths["root"].mkdir(parents=True, exist_ok=True)
    # A deliberate prepare is a new attempt.  An old durable exit contract
    # belongs to the preceding attempt and must not be observed as the result
    # of a newly launched process.
    paths["exit"].unlink(missing_ok=True)
    write_agent_run_state(project_root, task, driver, state_status, command=command, paths=paths, attempt=attempt)
    emit_process_event(project_root, "worker.run.prepared", process_id=task_process_id(task), subject=task_id, assignment_id_value=task_id, assignment_path=rel(assignment_yaml_path(project_root, task_id), project_root), payload={"run_id": run_id, "driver_id": driver.get("id"), "status": state_status, "attempt": attempt}, correlation_id=f"run-{run_id}")
    return task, driver, paths


def command_worker_run_prepare(args: argparse.Namespace) -> int:
    project_root = Path(args.project_root).expanduser().resolve()
    require_flow_root(project_root)
    task_id = safe_id(args.task, "task")
    task = load_task(project_root, task_id)
    run_id = safe_id(str(task.get("run_id") or "run"), "run")
    with worker_run_lifecycle_lock(project_root, run_id, task_id):
        running = existing_running_worker_run(project_root, task, getattr(args, "driver", None))
        if running:
            state, driver, paths = running
            emit_worker_run_skip(project_root, task, driver, state, "worker.run.prepare_skipped")
            print(f"SKIPPED: {task_id} already running pid={state.get('pid')}")
            return 0
        task, driver, paths = prepare_worker_run(project_root, task_id, getattr(args, "driver", None), getattr(args, "executable", None), getattr(args, "model", None), getattr(args, "reasoning_effort", None))
    print(f"PREPARED: {task_id} driver={driver.get('id')} status={json_read(paths['status']).get('status')}")
    return 0


def command_worker_run_start(args: argparse.Namespace) -> int:
    project_root = Path(args.project_root).expanduser().resolve()
    require_flow_root(project_root)
    task_id = safe_id(args.task, "task")
    task = load_task(project_root, task_id)
    run_id = safe_id(str(task.get("run_id") or "run"), "run")
    detach = bool(getattr(args, "detach", False))
    proc: subprocess.Popen[bytes] | None = None
    with worker_run_lifecycle_lock(project_root, run_id, task_id):
        running = existing_running_worker_run(project_root, task, getattr(args, "driver", None))
        if running:
            state, driver, paths = running
            emit_worker_run_skip(project_root, task, driver, state, "worker.run.start_skipped")
            print(f"SKIPPED: {task_id} already running pid={state.get('pid')}")
            return 0
        task, driver, paths = prepare_worker_run(project_root, task_id, getattr(args, "driver", None), getattr(args, "executable", None), getattr(args, "model", None), getattr(args, "reasoning_effort", None))
        run_id = safe_id(str(task.get("run_id") or "run"), "run")
        if str(driver.get("kind")) == "manual":
            print(f"MANUAL: {task_id} prepared at {rel(paths['status'], project_root)}")
            return 0
        command = json_read(paths["command"])
        argv = command.get("command", {}).get("argv") if isinstance(command.get("command"), dict) else []
        if not argv:
            write_agent_run_state(project_root, task, driver, "failed", failure_reason="empty argv", command=command, paths=paths)
            print(f"FAIL: empty command argv for {task_id}")
            return 1
        timeout_seconds = int((command.get("limits") if isinstance(command.get("limits"), dict) else {}).get("timeout_seconds") or 30)
        command_spec = command.get("command") if isinstance(command.get("command"), dict) else {}
        env = materialize_worker_launch_environment(command_spec)
        cwd = command_spec.get("working_directory") or str(project_root)
        paths["stdout"].parent.mkdir(parents=True, exist_ok=True)
        paths["stderr"].parent.mkdir(parents=True, exist_ok=True)
        started_at = now_utc()
        with paths["stdout"].open("wb") as stdout, paths["stderr"].open("wb") as stderr:
            try:
                proc = subprocess.Popen([str(item) for item in argv], cwd=str(cwd), env=env, stdout=stdout, stderr=stderr, shell=False)
            except OSError as exc:
                finished_at = now_utc()
                write_agent_run_state(project_root, task, driver, "failed", started_at=started_at, finished_at=finished_at, exit_code=None, failure_reason=str(exc), command=command, paths=paths)
                print(f"FAIL: start failed for {task_id}: {exc}")
                return 1
        write_agent_run_state(project_root, task, driver, "running", pid=proc.pid, started_at=started_at, command=command, paths=paths)
        json_write(paths["process"], {"schema_version": 1, "pid": proc.pid, "started_at": started_at, "argv": argv})
        if detach:
            DETACHED_WORKER_PROCESSES[worker_process_key(project_root, run_id, task_id)] = proc
            emit_process_event(project_root, "worker.run.started", process_id=task_process_id(task), subject=task_id, assignment_id_value=task_id, assignment_path=rel(assignment_yaml_path(project_root, task_id), project_root), payload={"run_id": run_id, "driver_id": driver.get("id"), "status": "running", "pid": proc.pid}, correlation_id=f"run-{run_id}")
            print(f"RUNNING: {task_id} pid={proc.pid}")
            return 0
    assert proc is not None
    try:
        exit_code = proc.wait(timeout=timeout_seconds)
        finished_at = now_utc()
        final_status = "completed" if exit_code == 0 else "failed"
        write_agent_run_state(project_root, task, driver, final_status, pid=proc.pid, started_at=started_at, finished_at=finished_at, exit_code=exit_code, command=command, paths=paths)
        json_write(paths["exit"], {"schema_version": 1, "exit_code": exit_code, "finished_at": finished_at, "status": final_status})
    except subprocess.TimeoutExpired:
        proc.kill()
        exit_code = -1
        final_status = "timed_out"
        finished_at = now_utc()
        write_agent_run_state(project_root, task, driver, final_status, pid=proc.pid, started_at=started_at, finished_at=finished_at, exit_code=exit_code, failure_reason="timeout", command=command, paths=paths)
        json_write(paths["exit"], {"schema_version": 1, "exit_code": exit_code, "finished_at": finished_at, "status": final_status})
    emit_process_event(project_root, "worker.run.finished", process_id=task_process_id(task), subject=task_id, assignment_id_value=task_id, assignment_path=rel(assignment_yaml_path(project_root, task_id), project_root), payload={"run_id": run_id, "driver_id": driver.get("id"), "status": final_status, "exit_code": exit_code}, correlation_id=f"run-{run_id}")
    print(f"{final_status.upper()}: {task_id} exit_code={exit_code}")
    return 0 if final_status == "completed" else 1


def command_worker_run_status(args: argparse.Namespace) -> int:
    project_root = Path(args.project_root).expanduser().resolve()
    require_flow_root(project_root)
    task_id = safe_id(args.task, "task")
    task = load_task(project_root, task_id)
    run_id = safe_id(str(task.get("run_id") or "run"), "run")
    with worker_run_lifecycle_lock(project_root, run_id, task_id):
        state = load_agent_run_state(project_root, run_id, task_id)
        if state and worker_run_state_requires_reconciliation(project_root, run_id, task_id, state):
            driver = runtime_driver_for_worker_state(project_root, task, state)
            state = observe_worker_run(project_root, task, driver, state)
    if not state:
        print(f"STATUS: not-prepared {task_id}")
        return 1
    print(dump_yaml(state))
    return 0


def command_worker_run_stop(args: argparse.Namespace) -> int:
    project_root = Path(args.project_root).expanduser().resolve()
    require_flow_root(project_root)
    task_id = safe_id(args.task, "task")
    task = load_task(project_root, task_id)
    run_id = safe_id(str(task.get("run_id") or "run"), "run")
    state = load_agent_run_state(project_root, run_id, task_id)
    if not state:
        print(f"STATUS: not-prepared {task_id}")
        return 1
    pid = state.get("pid")
    if pid and state.get("status") == "running":
        if os.name == "nt":
            subprocess.run(["taskkill", "/PID", str(pid), "/T", "/F"], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        else:
            os.kill(int(pid), signal.SIGTERM)
    driver = runtime_driver_for_worker_state(project_root, task, state)
    paths = worker_run_paths(project_root, run_id, task_id)
    if state.get("status") in {"completed", "failed", "timed_out", "unknown_exit", "lost", "cancelled"}:
        print(f"STATUS: already-terminal {task_id} status={state.get('status')}")
        return 0
    write_agent_run_state(project_root, task, driver, "cancelled", pid=pid if isinstance(pid, int) else None, finished_at=now_utc(), failure_reason="stop requested", paths=paths)
    print(f"STOPPED: {task_id}")
    return 0


def command_worker_run_collect(args: argparse.Namespace) -> int:
    project_root = Path(args.project_root).expanduser().resolve()
    require_flow_root(project_root)
    task_id = safe_id(args.task, "task")
    task = load_task(project_root, task_id)
    run_id = safe_id(str(task.get("run_id") or "run"), "run")
    with worker_run_lifecycle_lock(project_root, run_id, task_id):
        state = load_agent_run_state(project_root, run_id, task_id)
        if state and worker_run_state_requires_reconciliation(project_root, run_id, task_id, state):
            driver = runtime_driver_for_worker_state(project_root, task, state)
            state = observe_worker_run(project_root, task, driver, state)
    if not state:
        print(f"FAIL: worker run is not prepared: {task_id}")
        return 1
    if state.get("status") not in {"completed", "manual_required"}:
        print(f"FAIL: worker run is not collectible: {task_id} status={state.get('status', 'unknown')}")
        return 1
    missing: list[str] = []
    for output in normalize_required_outputs(task.get("required_outputs")):
        if not bool(output.get("required", True)):
            continue
        raw_path = output.get("path") if isinstance(output, dict) else ""
        out_path = project_root / normalize_assignment_path(str(raw_path))
        if not out_path.is_file():
            missing.append(normalize_assignment_path(str(raw_path)))
    report_path = project_root / expected_report_artifact(task)
    if not report_path.is_file():
        missing.append(expected_report_artifact(task))
    paths = worker_run_paths(project_root, run_id, task_id)
    lines = [
        f"# Worker Run Collection: {task_id}",
        "",
        f"- status: `{state.get('status', 'unknown')}`",
        f"- expected_report: `{expected_report_artifact(task)}`",
        f"- missing_outputs: `{len(missing)}`",
    ]
    for item in missing:
        lines.append(f"- missing: `{item}`")
    subagent_failures = validate_subagent_policy_outputs(project_root, task)
    lines.append(f"- subagent_policy_failures: `{len(subagent_failures)}`")
    for item in subagent_failures:
        lines.append(f"- subagent_policy_failure: `{item}`")
    paths["collection"].write_text("\n".join(lines) + "\n", encoding="utf-8")
    if missing or subagent_failures:
        driver = runtime_driver_for_worker_state(project_root, task, state)
        reasons = []
        if missing:
            reasons.append("missing outputs: " + ", ".join(missing))
        if subagent_failures:
            reasons.append("subagent policy failures: " + "; ".join(subagent_failures))
        write_agent_run_state(project_root, task, driver, "failed", failure_reason="; ".join(reasons), paths=paths)
        print("FAIL: " + "; ".join(reasons))
        return 1
    report_content = report_path.read_text(encoding="utf-8", errors="replace")
    report_hash = sha256_text(report_content)
    attempt = str(state.get("attempt") or 1)
    expected_report = rel(report_path, project_root)
    session_id = f"pf-worker:{run_id}:{task_id}:attempt:{attempt}"
    envelope = {
        "provider": "processforge",
        "adapter": "pf-codex-exec-worker",
        "native_event_type": "WorkerExpectedReportCaptured",
        "native_event_id": f"worker-output:{run_id}:{task_id}:attempt:{attempt}:{report_hash}",
        "native_id_scope": "project",
        "native_event_id_stable": True,
        "source_session_id": session_id,
        "source_project_ref": str(project_root),
        "payload_version": "1",
        "raw_payload": {
            "run_id": run_id,
            "task_id": task_id,
            "attempt": attempt,
            "expected_report": expected_report,
            "report_content": report_content,
            "report_hash": report_hash,
        },
        "derived_conversation_messages": [{
            "message_role": "assistant",
            "participant": {"id": str(task.get("ownership", {}).get("owner_id") or "worker"), "type": "agent", "role": "worker"},
            "session_id": session_id,
            "turn_id": f"worker-turn:{run_id}:{task_id}:attempt:{attempt}",
            "content": report_content,
            "content_source": {"kind": "pf_codex_exec_output", "provider": "processforge", "adapter": "pf-codex-exec-worker", "native_event_type": "WorkerExpectedReportCaptured", "content_provenance": "pf_owned_output_file"},
            "delivery": {"state": "complete", "sequence": 1, "final": True},
        }],
    }
    from pf_runtime import host as runtime_host
    capture = runtime_host.ingest_event(envelope, None, sys.modules[__name__])
    if not capture.get("accepted") or len(capture.get("chat_message_ids") or []) != 1:
        print("FAIL: collectible expected report was not captured as exactly one assistant transcript message")
        return 1
    status, output = run_command_capture(command_task_complete, argparse.Namespace(project_root=str(project_root), task=task_id, summary=f"Collected worker run output from {state.get('driver_id')}", artifact=[expected_report_artifact(task)], dry_run=False))
    print(output, end="")
    emit_process_event(project_root, "worker.run.collected", process_id=task_process_id(task), subject=task_id, assignment_id_value=task_id, assignment_path=rel(assignment_yaml_path(project_root, task_id), project_root), payload={"run_id": run_id, "report": expected_report_artifact(task)}, correlation_id=f"run-{run_id}")
    return status


def sync_failed_worker_lifecycle(project_root: Path, task: dict[str, Any], state: dict[str, Any]) -> None:
    task_id = safe_id(str(task.get("id") or state.get("task_id") or "task"), "task")
    run_id = safe_id(str(task.get("run_id") or state.get("run_id") or "run"), "run")
    if str(task.get("status")) in {"done", "completed", "failed", "cancelled"}:
        return
    runtime_status = str(state.get("status") or "failed")
    failure_reason = str(state.get("failure_reason") or runtime_status)
    task["status"] = "failed"
    task["result"] = {
        # Assignment result is a semantic delivery outcome; the more granular
        # Inspector runtime status belongs in its durable agent-run record.
        "status": "failed",
        "summary": f"Worker runtime ended with {runtime_status}: {failure_reason}",
        "artifacts": [],
    }
    save_task(project_root, task)
    update_run_task_status(project_root, run_id, task_id, "failed")
    emit_process_event(project_root, "task.failed", process_id=task_process_id(task), subject=task_id, assignment_id_value=task_id, assignment_path=rel(assignment_yaml_path(project_root, task_id), project_root), payload={"run_id": run_id, "task_id": task_id, "runtime_status": runtime_status, "failure_reason": failure_reason}, correlation_id=f"run-{run_id}")


def default_supervisor_profile() -> dict[str, Any]:
    return {
        "schema_version": 1,
        "id": "default",
        "title": "Default Process Supervisor",
        "loop": {"interval_seconds": 1, "max_ticks": 1},
        "scheduling": {"max_parallel_workers": 1, "start_policy": "manual", "default_driver": "manual"},
        "collection": {"auto_collect_completed": True},
        "stop": {"file": ".pf/runtime/supervisor/stop.request"},
    }


def load_supervisor_profile(project_root: Path, profile_ref: str | None = None) -> dict[str, Any]:
    if not profile_ref or profile_ref == "default":
        template = ROOT / "templates" / "supervisor-profile.yaml"
        return read_yaml_file(template) if template.is_file() else default_supervisor_profile()
    path = Path(profile_ref).expanduser()
    if not path.is_absolute():
        path = (project_root / path).resolve()
    return read_yaml_file(path)


def plan_worker_map(plan: dict[str, Any]) -> dict[str, dict[str, Any]]:
    workers = plan.get("workers") if isinstance(plan.get("workers"), list) else []
    result: dict[str, dict[str, Any]] = {}
    for worker in workers:
        if isinstance(worker, dict):
            worker_id = safe_id(str(worker.get("id") or "worker"), "worker")
            result[worker_id] = worker
    return result


def task_dependency_ids(task: dict[str, Any], worker: dict[str, Any] | None = None) -> list[str]:
    values: list[str] = []
    dependencies = task.get("dependencies") if isinstance(task.get("dependencies"), dict) else {}
    values.extend(str(item) for item in as_list(dependencies.get("blocked_by")))
    if worker:
        values.extend(str(item) for item in as_list(worker.get("dependencies")))
        values.extend(str(item) for item in as_list(worker.get("depends_on")))
    return sorted({safe_id(item, "task") for item in values if item})


def task_dependencies_done(project_root: Path, task: dict[str, Any], worker: dict[str, Any] | None = None) -> bool:
    for dep_id in task_dependency_ids(task, worker):
        dep_path = assignment_yaml_path(project_root, dep_id)
        if not dep_path.is_file():
            return False
        dep = read_yaml_file(dep_path)
        if str(dep.get("status")) not in {"done", "completed"}:
            return False
    return True


def load_run_plan_if_present(project_root: Path, run_id: str) -> dict[str, Any]:
    path = orchestrator_plan_path(project_root, run_id)
    return read_yaml_file(path) if path.is_file() else {}


def supervisor_state_path(project_root: Path) -> Path:
    return supervisor_root(project_root) / "state.json"


def write_supervisor_state(project_root: Path, state: dict[str, Any]) -> None:
    state["updated_at"] = now_utc()
    json_write(supervisor_state_path(project_root), state)


def supervisor_pending_drain_task_ids(project_root: Path, run_ids: list[str]) -> list[str]:
    pending: list[str] = []
    for run_id in run_ids:
        run = load_run(project_root, run_id)
        for item in run.get("tasks", []) if isinstance(run.get("tasks"), list) else []:
            if not isinstance(item, dict):
                continue
            task_id = safe_id(str(item.get("id") or "task"), "task")
            state = load_agent_run_state(project_root, run_id, task_id)
            status = str(state.get("status") or "")
            task_status = str(item.get("status") or "")
            if status == "running" or (status == "completed" and task_status not in {"done", "completed"}):
                pending.append(task_id)
    return sorted(set(pending))


def supervisor_final_drain_timeout(project_root: Path, run_ids: list[str], explicit_timeout: float | None = None) -> float:
    if explicit_timeout is not None:
        return max(0.0, float(explicit_timeout))
    worker_timeouts: list[int] = []
    for run_id in run_ids:
        run = load_run(project_root, run_id)
        for item in run.get("tasks", []) if isinstance(run.get("tasks"), list) else []:
            if not isinstance(item, dict):
                continue
            task_id = safe_id(str(item.get("id") or "task"), "task")
            state = load_agent_run_state(project_root, run_id, task_id)
            if str(state.get("status") or "") == "running":
                timeout_seconds = state.get("timeout_seconds")
                if isinstance(timeout_seconds, int) and timeout_seconds > 0:
                    worker_timeouts.append(timeout_seconds)
    return max(1.0, min(float(min(worker_timeouts) if worker_timeouts else 5), 5.0))


def command_supervisor_tick(args: argparse.Namespace) -> int:
    project_root = Path(args.project_root).expanduser().resolve()
    require_flow_root(project_root)
    profile = load_supervisor_profile(project_root, getattr(args, "profile", None))
    run_ids = [safe_id(args.run, "run")] if getattr(args, "run", None) else active_run_ids(project_root)
    started: list[str] = []
    collected: list[str] = []
    skipped: list[str] = []
    failed: list[str] = []
    running: list[str] = []
    observed: list[str] = []
    blocked_overlap: list[str] = []
    scheduling = profile.get("scheduling") if isinstance(profile.get("scheduling"), dict) else {}
    defaults = profile.get("defaults") if isinstance(profile.get("defaults"), dict) else {}
    max_parallel = int(scheduling.get("max_parallel_workers") or defaults.get("max_parallel_workers") or 1)
    start_allowed = bool(getattr(args, "start_allowed", True))
    repo_files = iter_repo_files(project_root)
    running_scopes: dict[str, list[str]] = {}
    for run_id in run_ids:
        run = load_run(project_root, run_id)
        plan = load_run_plan_if_present(project_root, run_id)
        runtime = plan.get("runtime") if isinstance(plan.get("runtime"), dict) else {}
        workers = plan_worker_map(plan)
        run_max_parallel = int(runtime.get("max_parallel_workers") or max_parallel)
        allow_write_scope_overlap = plan_allows_write_scope_overlap(plan)
        default_driver = getattr(args, "driver", None) or str(runtime.get("default_driver") or scheduling.get("default_driver") or defaults.get("runtime_driver") or "manual")
        tasks = sorted([entry for entry in run.get("tasks", []) if isinstance(entry, dict)], key=lambda value: int(value.get("order", 0) or 0))
        task_rows: list[tuple[str, dict[str, Any], dict[str, Any] | None, str]] = []
        for item in tasks:
            task_id = safe_id(str(item.get("id") or "task"), "task")
            task = load_task(project_root, task_id)
            worker = workers.get(task_id)
            state = load_agent_run_state(project_root, run_id, task_id)
            # A prepared run records the concrete driver as durable Inspector
            # state.  A supervisor must observe that driver, not fall back to
            # its run default (commonly `manual`), otherwise it can rewrite a
            # shell worker's timeout and lifecycle while the process is live.
            driver_id = str(state.get("driver_id") or (worker or {}).get("runtime_driver") or task.get("runtime_driver") or default_driver)
            task_rows.append((task_id, task, worker, driver_id))
            if state.get("status") == "running":
                observed_state = observe_worker_run(project_root, task, driver_id, state)
                observed.append(task_id)
                if observed_state.get("status") == "running":
                    running.append(task_id)
                    running_scopes[task_id] = assignment_write_scope(task)
                elif observed_state.get("status") == "completed" and str(task.get("status")) not in {"done", "completed"}:
                    status = command_worker_run_collect(argparse.Namespace(project_root=str(project_root), task=task_id))
                    if status == 0:
                        collected.append(task_id)
                    else:
                        failed.append(task_id)
                elif observed_state.get("status") in AGENT_RUN_FAILURE_TERMINAL_STATUSES:
                    sync_failed_worker_lifecycle(project_root, task, observed_state)
                    failed.append(task_id)
            elif state.get("status") == "completed" and str(task.get("status")) not in {"done", "completed"}:
                status = command_worker_run_collect(argparse.Namespace(project_root=str(project_root), task=task_id))
                if status == 0:
                    collected.append(task_id)
                else:
                    failed.append(task_id)
            elif state.get("status") in AGENT_RUN_FAILURE_TERMINAL_STATUSES:
                sync_failed_worker_lifecycle(project_root, task, state)
                failed.append(task_id)
        if not start_allowed:
            continue
        for task_id, task, worker, driver_id in task_rows:
            active_count = len(running) + len(started)
            if active_count >= run_max_parallel:
                break
            state = load_agent_run_state(project_root, run_id, task_id)
            if state.get("status") in AGENT_RUN_START_SKIP_STATUSES:
                continue
            if str(task.get("status")) not in {"open", "in_progress", "blocked"}:
                skipped.append(task_id)
                continue
            if not task_dependencies_done(project_root, task, worker):
                skipped.append(task_id)
                continue
            if driver_id == "manual":
                prepare_worker_run(project_root, task_id, driver_id, None)
                skipped.append(task_id)
                continue
            current_scope = assignment_write_scope(task)
            conflict = False
            if not allow_write_scope_overlap:
                for other_id, other_scope in running_scopes.items():
                    if assignment_scope_conflicts(task_id, current_scope, other_id, other_scope, repo_files, reason_prefix="supervisor_"):
                        conflict = True
                        break
            if conflict:
                blocked_overlap.append(task_id)
                skipped.append(task_id)
                continue
            try:
                status = command_worker_run_start(argparse.Namespace(project_root=str(project_root), task=task_id, driver=driver_id, executable=None, model=None, detach=True, wait=False))
            except SystemExit as exc:
                status = int(exc.code) if isinstance(exc.code, int) else 1
                print(exc)
            if status == 0:
                started.append(task_id)
                running_scopes[task_id] = current_scope
            else:
                failed.append(task_id)
    report = supervisor_root(project_root) / "last-tick-report.md"
    report.parent.mkdir(parents=True, exist_ok=True)
    report.write_text(
        "\n".join(
            [
                "# Supervisor Tick Report",
                "",
                f"- checked_runs: `{len(run_ids)}`",
                f"- start_allowed: `{str(start_allowed).lower()}`",
                f"- started: `{', '.join(started) if started else 'none'}`",
                f"- running: `{', '.join(running) if running else 'none'}`",
                f"- observed: `{', '.join(observed) if observed else 'none'}`",
                f"- collected: `{', '.join(collected) if collected else 'none'}`",
                f"- skipped: `{', '.join(skipped) if skipped else 'none'}`",
                f"- blocked_overlap: `{', '.join(blocked_overlap) if blocked_overlap else 'none'}`",
                f"- failed: `{', '.join(failed) if failed else 'none'}`",
            ]
        )
        + "\n",
        encoding="utf-8",
    )
    emit_process_event(project_root, "supervisor.tick.completed", process_id="process-supervisor", subject="supervisor", payload={"runs": run_ids, "start_allowed": start_allowed, "started": started, "running": running, "observed": observed, "collected": collected, "skipped": skipped, "blocked_overlap": blocked_overlap, "failed": failed, "report": rel(report, project_root)})
    print(f"TICK: started={len(started)} running={len(running)} observed={len(observed)} collected={len(collected)} skipped={len(skipped)} failed={len(failed)}")
    print(f"WROTE: {rel(report, project_root)}")
    return 1 if failed else 0


def command_supervisor_run(args: argparse.Namespace) -> int:
    project_root = Path(args.project_root).expanduser().resolve()
    require_flow_root(project_root)
    profile = load_supervisor_profile(project_root, getattr(args, "profile", None))
    loop = profile.get("loop") if isinstance(profile.get("loop"), dict) else {}
    interval_arg = getattr(args, "interval", None)
    max_ticks_arg = getattr(args, "max_ticks", None)
    interval = float(interval_arg if interval_arg is not None else (loop.get("interval_seconds") or 1))
    max_ticks = int(max_ticks_arg if max_ticks_arg is not None else (loop.get("max_ticks") or 1))
    run_ids = [safe_id(args.run, "run")] if getattr(args, "run", None) else active_run_ids(project_root)
    final_drain_timeout = supervisor_final_drain_timeout(project_root, run_ids, getattr(args, "final_drain_timeout", None))
    drain_interval = min(max(interval if interval > 0 else 0.05, 0.05), 0.25)
    stop_file = project_root / ".pf" / "runtime" / "supervisor" / "stop.request"
    state = {"schema_version": 1, "id": "default", "status": "running", "project_root": ".", "pid": os.getpid(), "started_at": now_utc(), "updated_at": now_utc(), "stopped_at": None, "tick_count": 0, "drain_tick_count": 0, "final_drain_timeout_seconds": final_drain_timeout, "last_tick_report": ".pf/runtime/supervisor/last-tick-report.md", "stop_requested": False}
    write_supervisor_state(project_root, state)
    failed = False
    for index in range(max_ticks):
        if stop_file.is_file():
            state["stop_requested"] = True
            break
        tick_status = command_supervisor_tick(argparse.Namespace(project_root=str(project_root), run=getattr(args, "run", None), profile=getattr(args, "profile", None), driver=getattr(args, "driver", None)))
        failed = failed or tick_status != 0
        state["tick_count"] = index + 1
        write_supervisor_state(project_root, state)
        if failed:
            break
        if index + 1 < max_ticks:
            time.sleep(interval)
    drain_started_at = time.perf_counter()
    drain_ticks = 0
    pending = supervisor_pending_drain_task_ids(project_root, run_ids)
    while pending and final_drain_timeout > 0 and time.perf_counter() - drain_started_at <= final_drain_timeout:
        tick_status = command_supervisor_tick(argparse.Namespace(project_root=str(project_root), run=getattr(args, "run", None), profile=getattr(args, "profile", None), driver=getattr(args, "driver", None), start_allowed=False))
        failed = failed or tick_status != 0
        drain_ticks += 1
        state["drain_tick_count"] = drain_ticks
        write_supervisor_state(project_root, state)
        if failed:
            break
        pending = supervisor_pending_drain_task_ids(project_root, run_ids)
        if pending and time.perf_counter() - drain_started_at < final_drain_timeout:
            time.sleep(drain_interval)
    pending = supervisor_pending_drain_task_ids(project_root, run_ids)
    if pending:
        print(f"FINAL-DRAIN: pending={', '.join(pending)} timeout={final_drain_timeout:.2f}s")
    elif drain_ticks:
        print(f"FINAL-DRAIN: completed ticks={drain_ticks}")
    state["status"] = "stopped"
    state["stopped_at"] = now_utc()
    state["drain_tick_count"] = drain_ticks
    write_supervisor_state(project_root, state)
    print(f"SUPERVISOR: stopped ticks={state['tick_count']} drain_ticks={state['drain_tick_count']}")
    return 1 if failed else 0


def command_supervisor_status(args: argparse.Namespace) -> int:
    project_root = Path(args.project_root).expanduser().resolve()
    require_flow_root(project_root)
    state = json_read(supervisor_state_path(project_root))
    if not state:
        print("STATUS: not-started")
        return 1
    print(dump_yaml(state))
    return 0


def command_supervisor_stop(args: argparse.Namespace) -> int:
    project_root = Path(args.project_root).expanduser().resolve()
    require_flow_root(project_root)
    stop_file = supervisor_root(project_root) / "stop.request"
    stop_file.parent.mkdir(parents=True, exist_ok=True)
    stop_file.write_text(now_utc() + "\n", encoding="utf-8")
    state = json_read(supervisor_state_path(project_root))
    if state:
        state["status"] = "stopping"
        state["stop_requested"] = True
        write_supervisor_state(project_root, state)
    print(f"STOP REQUESTED: {rel(stop_file, project_root)}")
    return 0


