def load_orchestrator_plan(project_root: Path, plan_arg: str | None = None, run_arg: str | None = None) -> dict[str, Any]:
    if plan_arg:
        path = Path(plan_arg).expanduser()
        if not path.is_absolute():
            path = (project_root / path).resolve()
    elif run_arg:
        path = orchestrator_plan_path(project_root, run_arg)
    else:
        raise SystemExit("FAIL: --plan or --run is required")
    if not path.is_file():
        raise SystemExit(f"FAIL: orchestrator plan not found: {path}")
    data = read_yaml_file(path)
    if not isinstance(data, dict):
        raise SystemExit(f"FAIL: orchestrator plan must be a YAML object: {path}")
    return data


def path_allowed_by_scope(path: str, scopes: list[str]) -> bool:
    key = assignment_path_key(path)
    for scope in scopes:
        scope_key = assignment_path_key(scope)
        if scope_key in {".pf/artifacts/**", ".pf/artifacts/*"} and key.startswith(".pf/artifacts/"):
            return True
        if assignment_has_glob(scope_key) and fnmatch.fnmatch(key, scope_key):
            return True
        if key == scope_key:
            return True
    return False


def worker_dependency_set(worker: dict[str, Any]) -> set[str]:
    result: set[str] = set()
    for key in ["dependencies", "depends_on"]:
        for item in as_list(worker.get(key)):
            if item:
                result.add(safe_id(str(item), "worker"))
    return result


def worker_depends_on(workers_by_id: dict[str, dict[str, Any]], worker_id: str, dependency_id: str, seen: set[str] | None = None) -> bool:
    seen = seen or set()
    if worker_id in seen:
        return False
    seen.add(worker_id)
    worker = workers_by_id.get(worker_id, {})
    dependencies = worker_dependency_set(worker)
    if dependency_id in dependencies:
        return True
    return any(worker_depends_on(workers_by_id, dep_id, dependency_id, seen) for dep_id in dependencies)


ORCHESTRATOR_PLAN_TOP_LEVEL_KEYS = {
    "schema_version",
    "run",
    "orchestrator",
    "runtime",
    "workers",
    "integration",
    "allow_write_scope_overlap",
    "metadata",
}
ORCHESTRATOR_PLAN_RUNTIME_KEYS = {"default_driver", "supervisor_profile", "start_policy", "max_parallel_workers", "model", "reasoning_effort", "metadata"}
ORCHESTRATOR_PLAN_WORKER_KEYS = {
    "id",
    "title",
    "role",
    "process",
    "objective",
    "execution_mode",
    "writer",
    "owner",
    "runtime_driver",
    "model",
    "reasoning_effort",
    "agent_reasoning_effort",
    "allow_subagents",
    "subagent_policy",
    "allowed_files",
    "allowed_read_files",
    "forbidden_files",
    "required_sources",
    "context_artifacts",
    "workspace_access",
    "required_outputs",
    "expected_report_artifact",
    "expected_report_language",
    "dependencies",
    "depends_on",
    "worker_may_rebuild_context",
    "metadata",
}
ORCHESTRATOR_PLAN_SUBAGENT_KEYS = {"allow", "max_subagents", "allowed_roles", "require_reports", "reports_dir", "metadata"}


def config_extension_key(key: str) -> bool:
    return key == "metadata" or key.startswith("x_") or key.startswith("x-")


def unsupported_config_keys(data: dict[str, Any], allowed: set[str]) -> list[str]:
    return sorted(str(key) for key in data if str(key) not in allowed and not config_extension_key(str(key)))


def plan_allows_write_scope_overlap(plan: dict[str, Any]) -> bool:
    return plan.get("allow_write_scope_overlap") is True


def apply_orchestrator_model_override(plan: dict[str, Any], model: str | None) -> dict[str, Any]:
    agent_model = normalize_agent_model(model)
    if not agent_model:
        return plan
    result = copy.deepcopy(plan)
    runtime = result.get("runtime")
    if not isinstance(runtime, dict):
        runtime = {}
        result["runtime"] = runtime
    runtime["model"] = agent_model
    workers = result.get("workers") if isinstance(result.get("workers"), list) else []
    for worker in workers:
        if isinstance(worker, dict):
            worker["model"] = agent_model
    return result


def validate_orchestrator_task_plan(project_root: Path, plan: dict[str, Any]) -> list[Check]:
    checks: list[Check] = []
    run = plan.get("run") if isinstance(plan.get("run"), dict) else {}
    runtime = plan.get("runtime") if isinstance(plan.get("runtime"), dict) else {}
    workers = plan.get("workers") if isinstance(plan.get("workers"), list) else []
    for key in unsupported_config_keys(plan, ORCHESTRATOR_PLAN_TOP_LEVEL_KEYS):
        checks.append(check("FAIL", f"unsupported top-level config field: {key}"))
    if "allow_write_scope_overlap" in plan:
        checks.append(check("PASS" if isinstance(plan.get("allow_write_scope_overlap"), bool) else "FAIL", "allow_write_scope_overlap boolean"))
    if runtime:
        for key in unsupported_config_keys(runtime, ORCHESTRATOR_PLAN_RUNTIME_KEYS):
            checks.append(check("FAIL", f"unsupported runtime config field: {key}"))
        if "max_parallel_workers" in runtime:
            max_parallel = runtime.get("max_parallel_workers")
            checks.append(check("PASS" if type(max_parallel) is int and max_parallel >= 1 else "FAIL", "runtime.max_parallel_workers positive integer"))
        if "model" in runtime:
            checks.append(check("PASS" if normalize_agent_model(runtime.get("model")) else "FAIL", "runtime.model non-empty string when present"))
        if "reasoning_effort" in runtime:
            checks.append(check("PASS" if normalize_agent_reasoning_effort(runtime.get("reasoning_effort")) else "FAIL", "runtime.reasoning_effort valid when present"))
    checks.append(check("PASS" if run.get("id") else "FAIL", "run.id present"))
    checks.append(check("PASS" if run.get("title") else "FAIL", "run.title present"))
    checks.append(check("PASS" if str(run.get("process") or "multi-agent-task-orchestration") == "multi-agent-task-orchestration" else "FAIL", "run process is multi-agent-task-orchestration"))
    checks.append(check("PASS" if workers else "FAIL", "workers present"))
    default_driver = str(runtime.get("default_driver") or "manual")
    start_policy = str(runtime.get("start_policy") or "manual")
    checks.append(check("PASS" if default_driver in {item[0] for item in runtime_driver_id_list(project_root=project_root)} else "FAIL", f"runtime.default_driver registered: {default_driver}"))
    checks.append(check("PASS" if start_policy in {"manual", "prepare", "supervisor"} else "FAIL", f"runtime.start_policy valid: {start_policy}"))
    seen: set[str] = set()
    repo_files = iter_repo_files(project_root)
    write_scopes: list[tuple[str, list[str]]] = []
    workers_by_id = {
        safe_id(str(worker.get("id") or "worker"), "worker"): worker
        for worker in workers
        if isinstance(worker, dict)
    }
    for raw_worker in workers:
        if not isinstance(raw_worker, dict):
            checks.append(check("FAIL", "worker item must be an object"))
            continue
        for key in unsupported_config_keys(raw_worker, ORCHESTRATOR_PLAN_WORKER_KEYS):
            checks.append(check("FAIL", f"unsupported worker config field: {key}"))
        raw_subagent_policy = raw_worker.get("subagent_policy") if isinstance(raw_worker.get("subagent_policy"), dict) else {}
        for key in unsupported_config_keys(raw_subagent_policy, ORCHESTRATOR_PLAN_SUBAGENT_KEYS):
            checks.append(check("FAIL", f"unsupported subagent_policy config field: {key}"))
        worker_id = safe_id(str(raw_worker.get("id") or ""), "worker")
        checks.append(check("PASS" if worker_id and worker_id not in seen else "FAIL", f"worker id unique: {worker_id or 'missing'}"))
        seen.add(worker_id)
        allowed = assignment_scope_items(raw_worker.get("allowed_files"))
        forbidden = assignment_scope_items(raw_worker.get("forbidden_files"))
        read_allowed = assignment_scope_items(raw_worker.get("allowed_read_files"))
        workspace_access = normalize_workspace_access(raw_worker.get("workspace_access"))
        outputs = normalize_required_outputs(raw_worker.get("required_outputs"))
        writer = bool(raw_worker.get("writer", True))
        driver_id = str(raw_worker.get("runtime_driver") or default_driver)
        if "model" in raw_worker:
            checks.append(check("PASS" if normalize_agent_model(raw_worker.get("model")) else "FAIL", f"{worker_id} model non-empty string when present"))
        if "reasoning_effort" in raw_worker or "agent_reasoning_effort" in raw_worker:
            checks.append(check("PASS" if normalize_agent_reasoning_effort(raw_worker.get("reasoning_effort") or raw_worker.get("agent_reasoning_effort")) else "FAIL", f"{worker_id} reasoning_effort valid when present"))
        if writer:
            checks.append(check("PASS" if allowed else "FAIL", f"{worker_id} writer has allowed_files"))
        checks.append(check("PASS" if driver_id in {item[0] for item in runtime_driver_id_list(project_root=project_root)} else "FAIL", f"{worker_id} runtime_driver registered: {driver_id}"))
        for dep_id in worker_dependency_set(raw_worker):
            checks.append(check("PASS" if dep_id in workers_by_id else "FAIL", f"{worker_id} dependency exists: {dep_id}"))
        has_workspace_access = any(workspace_access[key] for key in WORKSPACE_ACCESS_KEYS)
        checks.append(check("PASS" if read_allowed or raw_worker.get("required_sources") or has_workspace_access else "WARN", f"{worker_id} has bounded read/context scope"))
        forbidden_conflicts = assignment_scope_conflicts(worker_id, allowed, worker_id, forbidden, repo_files, reason_prefix="forbidden_wins:")
        checks.append(check("PASS" if not forbidden_conflicts else "FAIL", f"{worker_id} forbidden_files do not overlap allowed_files"))
        subagent_policy = worker_subagent_policy(raw_worker)
        reports_dir = str(subagent_policy.get("reports_dir") or "")
        if "allow_subagents" in raw_worker:
            checks.append(check("PASS" if isinstance(raw_worker.get("allow_subagents"), bool) else "FAIL", f"{worker_id} allow_subagents boolean"))
        if "allow" in raw_subagent_policy:
            checks.append(check("PASS" if isinstance(raw_subagent_policy.get("allow"), bool) else "FAIL", f"{worker_id} subagent_policy.allow boolean"))
        if "require_reports" in raw_subagent_policy:
            checks.append(check("PASS" if isinstance(raw_subagent_policy.get("require_reports"), bool) else "FAIL", f"{worker_id} subagent_policy.require_reports boolean"))
        if "max_subagents" in raw_subagent_policy:
            max_subagents_raw = raw_subagent_policy.get("max_subagents")
            checks.append(check("PASS" if type(max_subagents_raw) is int and max_subagents_raw >= 0 else "FAIL", f"{worker_id} subagent_policy.max_subagents non-negative integer"))
        checks.append(check("PASS" if isinstance(subagent_policy.get("allow"), bool) else "FAIL", f"{worker_id} subagent allow flag valid"))
        if subagent_policy.get("allow") and subagent_policy.get("require_reports"):
            checks.append(check("PASS" if reports_dir.startswith(".pf/artifacts/subagents/") else "FAIL", f"{worker_id} subagent reports_dir inside .pf/artifacts/subagents"))
            checks.append(check("PASS" if int(subagent_policy.get("max_subagents") or 0) > 0 else "FAIL", f"{worker_id} subagent max_subagents positive"))
        for output in outputs:
            out_path = normalize_assignment_path(output.get("path") if isinstance(output, dict) else "")
            checks.append(check("PASS" if out_path else "FAIL", f"{worker_id} required output has path"))
            if out_path:
                allowed_output = path_allowed_by_scope(out_path, allowed) or out_path.startswith(".pf/artifacts/")
                checks.append(check("PASS" if allowed_output else "FAIL", f"{worker_id} required output inside allowed or artifact area: {out_path}"))
        checks.append(check("PASS" if not bool(raw_worker.get("worker_may_rebuild_context", False)) else "FAIL", f"{worker_id} worker_may_rebuild_context false by default"))
        if writer:
            write_scopes.append((worker_id, allowed))
    if not bool(plan.get("allow_write_scope_overlap", False)):
        for index, (left_id, left_scope) in enumerate(write_scopes):
            for right_id, right_scope in write_scopes[index + 1 :]:
                if worker_depends_on(workers_by_id, left_id, right_id) or worker_depends_on(workers_by_id, right_id, left_id):
                    continue
                conflicts = assignment_scope_conflicts(left_id, left_scope, right_id, right_scope, repo_files)
                if conflicts:
                    checks.append(check("FAIL", f"parallel write scopes overlap: {left_id} <-> {right_id}"))
    integration = plan.get("integration") if isinstance(plan.get("integration"), dict) else {}
    if integration.get("required", True):
        checks.append(check("PASS" if integration.get("expected_output") else "FAIL", "integration expected_output present"))
    return checks


def render_worker_launch_prompt(project_root: Path, task_id: str) -> str:
    task_id = safe_id(task_id, "task")
    task = load_task(project_root, task_id)
    run_id = str(task.get("run_id") or "")
    capsule = rel(locate_flow_root(project_root) / "contexts" / "assignment-capsules" / f"{task_id}.capsule.yaml", project_root)
    workspace_access = rel(worker_run_paths(project_root, safe_id(run_id or "run", "run"), task_id)["workspace_access"], project_root)
    requested_workspace_access = normalize_workspace_access(task.get("workspace_access"))
    allowed_files = assignment_scope_items(task.get("allowed_files"))
    allowed_read_files = assignment_scope_items(task.get("allowed_read_files"))
    forbidden_files = assignment_scope_items(task.get("forbidden_files"))
    required_outputs = normalize_required_outputs(task.get("required_outputs"))
    expected_report = task.get("expected_report") if isinstance(task.get("expected_report"), dict) else {}
    subagent_policy = normalize_subagent_policy(task.get("subagent_policy"))
    pf_first_instructions: list[str] = []
    if requested_workspace_access["knowledge_resources"]:
        pf_first_instructions = [
            "This assignment has governed workplace knowledge grants.",
            "Before any shell command, project file read, global memory lookup, or broad search, use the ProcessForge MCP control plane in this order: `pf.context`, `pf.work.start`, `pf.resolve`, then `pf.search`.",
            "Use `pf.resolve` and `pf.search` results as the primary route to knowledge paths and articles; open resolved files only after PF returns them.",
            "If the ProcessForge MCP tools are unavailable or fail, stop and return a blocked report. Do not silently fall back to filesystem discovery.",
        ]
    lines = [
        "# Worker Launch Prompt",
        "",
        "You are a worker agent.",
        "You are not the orchestrator.",
        "Use only the assigned task and the provided assignment capsule.",
        "Do not rebuild full project context unless explicitly allowed.",
        "Do not edit files outside allowed_files.",
        "Do not read files outside allowed_read_files unless explicitly allowed.",
        "Use workspace_access_file for explicitly granted workplace resources.",
        "Do not copy private paths from workspace_access_file into public project artifacts, assignments, capsules, or reports.",
        "Respect forbidden_files.",
        "Produce required_outputs.",
        "Write expected_report.",
        "Stop and report if scope is insufficient.",
        "Invoke subagents only when subagent_policy.allow is true.",
        "When subagent reports are required, write them only under subagent_policy.reports_dir.",
        *pf_first_instructions,
        "",
        "## Assignment",
        "",
        f"- task_id: `{task_id}`",
        f"- run_id: `{run_id}`",
        f"- assignment: `{rel(assignment_yaml_path(project_root, task_id), project_root)}`",
        f"- capsule: `{capsule}`",
        f"- workspace_access_file: `{workspace_access}`",
        "- worker_may_rebuild_context: `false`",
        "",
        "## workspace_access",
        "",
        f"- knowledge_resources: `{len(requested_workspace_access['knowledge_resources'])}`",
        f"- templates: `{len(requested_workspace_access['templates'])}`",
        f"- tools: `{len(requested_workspace_access['tools'])}`",
        f"- mcp: `{len(requested_workspace_access['mcp'])}`",
        "",
        "## allowed_files",
        "",
        *[f"- `{item}`" for item in allowed_files],
        "",
        "## allowed_read_files",
        "",
        *[f"- `{item}`" for item in allowed_read_files],
        "",
        "## forbidden_files",
        "",
        *[f"- `{item}`" for item in forbidden_files],
        "",
        "## required_outputs",
        "",
    ]
    for output in required_outputs:
        lines.append(f"- `{output.get('id')}` -> `{output.get('path', '')}`")
    lines.extend(["", "## expected_report", "", f"- `{expected_report.get('artifact', '')}`"])
    lines.extend(
        [
            "",
            "## subagent_policy",
            "",
            f"- allow: `{str(subagent_policy.get('allow')).lower()}`",
            f"- max_subagents: `{subagent_policy.get('max_subagents')}`",
            f"- require_reports: `{str(subagent_policy.get('require_reports')).lower()}`",
            f"- reports_dir: `{subagent_policy.get('reports_dir')}`",
        ]
    )
    return "\n".join(lines).rstrip() + "\n"


def write_orchestration_summary(project_root: Path, plan: dict[str, Any]) -> None:
    run = plan.get("run") if isinstance(plan.get("run"), dict) else {}
    run_id = safe_id(str(run.get("id") or "run"), "run")
    workers = plan.get("workers") if isinstance(plan.get("workers"), list) else []
    summary = run_root(project_root, run_id) / "orchestration-summary.md"
    task_index = run_root(project_root, run_id) / "orchestration-task-index.md"
    handoff = locate_flow_root(project_root) / "handoffs" / "runs" / f"{run_id}-orchestrator-handoff.md"
    summary_lines = [f"# Orchestration Summary: {run.get('title', run_id)}", "", f"- run_id: `{run_id}`", "- process: `multi-agent-task-orchestration`", "", "## Workers", ""]
    index_lines = [f"# Orchestration Task Index: {run_id}", ""]
    for worker in workers:
        if not isinstance(worker, dict):
            continue
        task_id = safe_id(str(worker.get("id") or "worker"), "worker")
        prompt_rel = rel(worker_prompt_path(project_root, run_id, task_id), project_root)
        capsule_rel = rel(locate_flow_root(project_root) / "contexts" / "assignment-capsules" / f"{task_id}.capsule.yaml", project_root)
        summary_lines.append(f"- `{task_id}`: prompt `{prompt_rel}`, capsule `{capsule_rel}`")
        index_lines.append(f"- `{task_id}` -> `.pf/assignments/{task_id}.yaml`")
    handoff_text = f"""# Handoff: orchestrator -> integration/review

Objective:
Coordinate worker outputs for run `{run_id}`.

Current status:
Initial worker assignments, capsules, and launch prompts were generated.

Input artifacts:
- {rel(orchestrator_plan_path(project_root, run_id), project_root)}
- {rel(summary, project_root)}

Files changed:
- .pf/runs/{run_id}/
- .pf/assignments/
- .pf/contexts/assignment-capsules/

Files not to touch:
- Files outside each worker `allowed_files`.

Known issues:
- Worker outputs are pending.

Required checks:
- `python .pf/runtime/bin/pf.py run-doctor --project-root . --run {run_id}`
- `python .pf/runtime/bin/pf.py task-doctor --project-root . --task <task-id>`

Next recommended action:
Launch workers with the generated prompts, then integrate their required outputs.
"""
    summary.write_text("\n".join(summary_lines) + "\n", encoding="utf-8")
    task_index.write_text("\n".join(index_lines) + "\n", encoding="utf-8")
    handoff.parent.mkdir(parents=True, exist_ok=True)
    handoff.write_text(handoff_text, encoding="utf-8")


def normalized_orchestrator_plan(project_root: Path, plan: dict[str, Any]) -> dict[str, Any]:
    run = plan.get("run") if isinstance(plan.get("run"), dict) else {}
    runtime = plan.get("runtime") if isinstance(plan.get("runtime"), dict) else {}
    default_driver = str(runtime.get("default_driver") or "manual")
    default_model = normalize_agent_model(runtime.get("model") or "")
    default_reasoning_effort = normalize_agent_reasoning_effort(runtime.get("reasoning_effort") or "")
    default_reasoning_effort = normalize_agent_reasoning_effort(runtime.get("reasoning_effort") or "")
    default_reasoning_effort = normalize_agent_reasoning_effort(runtime.get("reasoning_effort") or "")
    normalized_workers: list[dict[str, Any]] = []
    for order, worker in enumerate(plan.get("workers", []) if isinstance(plan.get("workers"), list) else [], start=1):
        if not isinstance(worker, dict):
            continue
        worker_id = safe_id(str(worker.get("id") or f"worker-{order}"), "worker")
        normalized_workers.append(
            {
                "id": worker_id,
                "order": order,
                "runtime_driver": str(worker.get("runtime_driver") or default_driver),
                "model": normalize_agent_model(worker.get("model") or default_model),
                "reasoning_effort": normalize_agent_reasoning_effort(worker.get("reasoning_effort") or worker.get("agent_reasoning_effort") or default_reasoning_effort),
                "allow_subagents": bool(worker.get("allow_subagents", False)),
                "subagent_policy": worker_subagent_policy(worker),
                "allowed_files": assignment_scope_items(worker.get("allowed_files")),
                "allowed_read_files": assignment_scope_items(worker.get("allowed_read_files")),
                "forbidden_files": assignment_scope_items(worker.get("forbidden_files")),
                "required_outputs": normalize_required_outputs(worker.get("required_outputs")),
                "workspace_access": normalize_workspace_access(worker.get("workspace_access")),
                "expected_report_artifact": str(worker.get("expected_report_artifact") or default_expected_report_artifact(worker_id)),
                "depends_on": sorted(worker_dependency_set(worker)),
            }
        )
    return {
        "schema_version": 1,
        "run": {
            "id": safe_id(str(run.get("id") or "run"), "run"),
            "title": str(run.get("title") or run.get("id") or "run"),
            "process": str(run.get("process") or "multi-agent-task-orchestration"),
        },
        "runtime": {
            "default_driver": default_driver,
            "supervisor_profile": str(runtime.get("supervisor_profile") or "default"),
            "start_policy": str(runtime.get("start_policy") or "manual"),
            "max_parallel_workers": int(runtime.get("max_parallel_workers") or 1),
            "model": default_model,
            "reasoning_effort": default_reasoning_effort,
        },
        "allow_write_scope_overlap": plan_allows_write_scope_overlap(plan),
        "workers": normalized_workers,
    }


def build_config_resolution_report(project_root: Path, plan: dict[str, Any]) -> dict[str, Any]:
    normalized = normalized_orchestrator_plan(project_root, plan)
    run_id = str(normalized["run"]["id"])
    runtime = plan.get("runtime") if isinstance(plan.get("runtime"), dict) else {}
    default_model = normalize_agent_model(runtime.get("model") or "")
    default_reasoning_effort = normalize_agent_reasoning_effort(runtime.get("reasoning_effort") or "")
    raw_workers: dict[str, dict[str, Any]] = {}
    for raw_worker in plan.get("workers", []) if isinstance(plan.get("workers"), list) else []:
        if isinstance(raw_worker, dict):
            raw_workers[safe_id(str(raw_worker.get("id") or "worker"), "worker")] = raw_worker
    workers: list[dict[str, Any]] = []
    for worker in normalized["workers"]:
        policy = worker["subagent_policy"] if isinstance(worker.get("subagent_policy"), dict) else {}
        raw_worker = raw_workers.get(str(worker["id"]), {})
        if normalize_agent_model(raw_worker.get("model") if isinstance(raw_worker, dict) else ""):
            model_source = f"workers[{worker['id']}].model"
        elif default_model:
            model_source = "runtime.model"
        else:
            model_source = "default.empty"
        workers.append(
            {
                "id": worker["id"],
                "runtime_driver": {
                    "value": worker["runtime_driver"],
                    "source": f"workers[{worker['id']}].runtime_driver",
                    "behavior": ["worker-run.runtime_driver"],
                },
                "agent_model": {
                    "value": normalize_agent_model(worker.get("model")),
                    "source": model_source,
                    "behavior": ["assignment.agent_model", "capsule.agent_model", "worker-run.PF_AGENT_MODEL", "runtime-driver.command.model_args"],
                },
                "agent_reasoning_effort": {
                    "value": normalize_agent_reasoning_effort(worker.get("reasoning_effort") or default_reasoning_effort),
                    "source": f"workers[{worker['id']}].reasoning_effort" if normalize_agent_reasoning_effort(raw_worker.get("reasoning_effort") if isinstance(raw_worker, dict) else "") else ("runtime.reasoning_effort" if default_reasoning_effort else "default.empty"),
                    "behavior": ["assignment.agent_reasoning_effort", "capsule.agent_reasoning_effort", "worker-run.PF_AGENT_REASONING_EFFORT", "codex-exec.PF_CODEX_REASONING_EFFORT"],
                },
                "subagent_policy": {
                    "allow": bool(policy.get("allow")),
                    "max_subagents": int(policy.get("max_subagents") or 0),
                    "allowed_roles": policy.get("allowed_roles") if isinstance(policy.get("allowed_roles"), list) else [],
                    "require_reports": bool(policy.get("require_reports")),
                    "reports_dir": str(policy.get("reports_dir") or ""),
                    "behavior": ["assignment.subagent_policy", "capsule.subagent_policy", "worker-run.collect.subagent_reports"],
                },
                "required_outputs": worker["required_outputs"],
                "expected_report_artifact": worker["expected_report_artifact"],
            }
        )
    return {
        "schema_version": 1,
        "plan": rel(orchestrator_plan_path(project_root, run_id), project_root),
        "resolved": {
            "allow_write_scope_overlap": {
                "value": bool(normalized["allow_write_scope_overlap"]),
                "source": "plan.allow_write_scope_overlap" if "allow_write_scope_overlap" in plan else "default.deny",
                "behavior": [
                    "assignment.overlap_policy=allow" if normalized["allow_write_scope_overlap"] else "assignment.overlap_policy=deny",
                    "supervisor.write_scope_overlap=allow_for_plan" if normalized["allow_write_scope_overlap"] else "supervisor.write_scope_overlap=block_conflicts",
                ],
            },
            "runtime": normalized["runtime"],
            "workers": workers,
        },
        "warnings": [],
        "unsupported_fields": [],
    }


def write_orchestrator_config_resolution_artifacts(project_root: Path, plan: dict[str, Any]) -> None:
    normalized = normalized_orchestrator_plan(project_root, plan)
    run_id = str(normalized["run"]["id"])
    root = run_root(project_root, run_id)
    root.mkdir(parents=True, exist_ok=True)
    write_yaml_file(root / "orchestrator-shell-plan.normalized.yaml", normalized)
    write_yaml_file(root / "config-resolution-report.yaml", build_config_resolution_report(project_root, plan))


def materialize_plan_overlap_policy(project_root: Path, plan: dict[str, Any]) -> None:
    if not plan_allows_write_scope_overlap(plan):
        return
    for worker in plan.get("workers", []) if isinstance(plan.get("workers"), list) else []:
        if not isinstance(worker, dict):
            continue
        task_id = safe_id(str(worker.get("id") or "worker"), "worker")
        path = assignment_yaml_path(project_root, task_id)
        if not path.is_file():
            continue
        task = load_task(project_root, task_id)
        overlap_check = overlap_allowed_check(validate_assignment_scope_overlaps(project_root, task, assignment_path=path), "plan.allow_write_scope_overlap")
        non_overlap = task.get("non_overlap") if isinstance(task.get("non_overlap"), dict) else {}
        non_overlap.update(
            {
                "policy": "allow_write_scope_overlap",
                "overlap_policy": "allow",
                "overlap_policy_source": "plan.allow_write_scope_overlap",
                "current_write_scope": assignment_write_scope(task),
                "rule": "Write scope overlap is allowed for workers in this resolved plan.",
                "overlap_check": overlap_check,
            }
        )
        task["non_overlap"] = non_overlap
        save_task(project_root, task)


def command_orchestrator_plan_create(args: argparse.Namespace) -> int:
    project_root = Path(args.project_root).expanduser().resolve()
    require_flow_root(project_root)
    run_id = safe_id(args.run, "run")
    path = orchestrator_plan_path(project_root, run_id)
    plan = load_answers(Path(args.answers).expanduser().resolve() if args.answers else None) if args.answers else default_orchestrator_task_plan(run_id, args.title)
    if not plan.get("run"):
        plan["run"] = {"id": run_id, "title": args.title, "process": "multi-agent-task-orchestration"}
    if not args.apply or getattr(args, "dry_run", False):
        print_plan("orchestrator-plan create dry run", [path], project_root)
        return 0
    write_yaml_file(path, plan)
    emit_process_event(project_root, "orchestrator.plan.created", process_id="multi-agent-task-orchestration", subject=run_id, payload={"plan": rel(path, project_root)}, correlation_id=f"run-{run_id}")
    print(f"WROTE: {rel(path, project_root)}")
    return 0


def command_orchestrator_plan_validate(args: argparse.Namespace) -> int:
    project_root = Path(args.project_root).expanduser().resolve()
    require_flow_root(project_root)
    plan = load_orchestrator_plan(project_root, args.plan, getattr(args, "run", None))
    result = print_checks(validate_orchestrator_task_plan(project_root, plan))
    if getattr(args, "write_normalized", None):
        output = Path(args.write_normalized).expanduser()
        if not output.is_absolute():
            output = (project_root / output).resolve()
        output.parent.mkdir(parents=True, exist_ok=True)
        write_yaml_file(output, normalized_orchestrator_plan(project_root, plan))
        print(f"WROTE: {rel(output, project_root)}")
    run = plan.get("run") if isinstance(plan.get("run"), dict) else {}
    emit_process_event(project_root, "orchestrator.plan.reviewed", process_id="multi-agent-task-orchestration", subject=str(run.get("id") or "run"), payload={"result": "fail" if result else "pass"})
    return result


def command_worker_launch_prompt_create(args: argparse.Namespace) -> int:
    project_root = Path(args.project_root).expanduser().resolve()
    require_flow_root(project_root)
    task_id = safe_id(args.task, "task")
    task = load_task(project_root, task_id)
    run_id = str(task.get("run_id") or "")
    output = Path(args.output).expanduser() if getattr(args, "output", None) else worker_prompt_path(project_root, run_id, task_id)
    if not output.is_absolute():
        output = (project_root / output).resolve()
    prompt = render_worker_launch_prompt(project_root, task_id)
    if not args.apply or getattr(args, "dry_run", False):
        print_plan("worker-launch-prompt create dry run", [output], project_root)
        return 0
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(prompt, encoding="utf-8")
    emit_process_event(project_root, "worker.launch_prompt.created", process_id=task_process_id(task), subject=task_id, assignment_id_value=task_id, assignment_path=rel(assignment_yaml_path(project_root, task_id), project_root), payload={"prompt": rel(output, project_root)}, correlation_id=f"run-{run_id}")
    print(f"WROTE: {rel(output, project_root)}")
    return 0


def command_orchestrator_plan_apply(args: argparse.Namespace) -> int:
    project_root = Path(args.project_root).expanduser().resolve()
    require_flow_root(project_root)
    plan = load_orchestrator_plan(project_root, args.plan, getattr(args, "run", None))
    plan = apply_orchestrator_model_override(plan, getattr(args, "model", None))
    checks = validate_orchestrator_task_plan(project_root, plan)
    if any(item.level == "FAIL" for item in checks):
        print_checks(checks)
        return 1
    run = plan.get("run") if isinstance(plan.get("run"), dict) else {}
    run_id = safe_id(str(run.get("id") or "run"), "run")
    title = str(run.get("title") or run_id)
    runtime = plan.get("runtime") if isinstance(plan.get("runtime"), dict) else {}
    default_driver = str(runtime.get("default_driver") or "manual")
    default_model = normalize_agent_model(runtime.get("model") or "")
    default_reasoning_effort = normalize_agent_reasoning_effort(runtime.get("reasoning_effort") or "")
    workers = plan.get("workers") if isinstance(plan.get("workers"), list) else []
    planned = [run_yaml_path(project_root, run_id), orchestrator_plan_path(project_root, run_id), run_root(project_root, run_id) / "worker-prompts", run_root(project_root, run_id) / "config-resolution-report.yaml"]
    if not args.apply or getattr(args, "dry_run", False):
        print_plan("orchestrator-plan apply dry run", planned, project_root)
        return 0
    if not run_yaml_path(project_root, run_id).is_file():
        status, output = run_command_capture(
            command_run_create,
            argparse.Namespace(project_root=str(project_root), id=run_id, title=title, process="multi-agent-task-orchestration", objective=str(run.get("objective") or title), status="in_progress", dry_run=False),
        )
        if status:
            print(output, end="")
            return status
    if runtime:
        with registry_file_lock(run_yaml_path(project_root, run_id)):
            run_doc = load_run(project_root, run_id)
            run_doc["runtime"] = {
                "default_driver": default_driver,
                "supervisor_profile": str(runtime.get("supervisor_profile") or "default"),
                "start_policy": str(runtime.get("start_policy") or "manual"),
            }
            if "max_parallel_workers" in runtime:
                run_doc["runtime"]["max_parallel_workers"] = int(runtime.get("max_parallel_workers") or 1)
            save_run_locked(project_root, run_doc)
    write_yaml_file(orchestrator_plan_path(project_root, run_id), plan)
    for order, worker in enumerate(workers, start=1):
        if not isinstance(worker, dict):
            continue
        task_id = safe_id(str(worker.get("id") or f"worker-{order}"), "worker")
        assignment_path = assignment_yaml_path(project_root, task_id)
        if not assignment_path.is_file():
            status, output = run_command_capture(
                command_task_create,
                argparse.Namespace(
                    project_root=str(project_root),
                    run=run_id,
                    id=task_id,
                    title=str(worker.get("title") or task_id),
                    process=str(worker.get("process") or "task-batch-execution"),
                    objective=str(worker.get("objective") or worker.get("title") or task_id),
                    order=order,
                    execution_mode=str(worker.get("execution_mode") or "implementation"),
                    allowed_file=assignment_scope_items(worker.get("allowed_files")),
                    allowed_glob=[],
                    allowed_read_file=assignment_scope_items(worker.get("allowed_read_files")),
                    read_file=[],
                    context_artifact=normalize_context_artifacts(worker.get("context_artifacts")),
                    required_source=assignment_scope_items(worker.get("required_sources")),
                    workspace_knowledge_resource=normalize_workspace_access(worker.get("workspace_access"))["knowledge_resources"],
                    workspace_template=normalize_workspace_access(worker.get("workspace_access"))["templates"],
                    workspace_tool=normalize_workspace_access(worker.get("workspace_access"))["tools"],
                    workspace_mcp=normalize_workspace_access(worker.get("workspace_access"))["mcp"],
                    forbidden_file=assignment_scope_items(worker.get("forbidden_files")),
                    forbidden_glob=[],
                    owner=str(worker.get("owner") or task_id),
                    role=str(worker.get("role") or "worker"),
                    writer="true" if bool(worker.get("writer", True)) else "false",
                    required_output=normalize_required_outputs(worker.get("required_outputs")),
                    expected_report_language=str(worker.get("expected_report_language") or "en"),
                    expected_report_artifact=str(worker.get("expected_report_artifact") or ""),
                    force_with_handoff=bool(plan.get("allow_write_scope_overlap", False) or as_list(worker.get("dependencies")) or as_list(worker.get("depends_on"))),
                    agent_model=normalize_agent_model(worker.get("model") or default_model),
                    reasoning_effort=normalize_agent_reasoning_effort(worker.get("reasoning_effort") or worker.get("agent_reasoning_effort") or default_reasoning_effort),
                    dry_run=False,
                ),
            )
            if status:
                print(output, end="")
                return status
        task = load_task(project_root, task_id)
        task["worker_may_rebuild_context"] = bool(worker.get("worker_may_rebuild_context", False))
        task["runtime_driver"] = str(worker.get("runtime_driver") or default_driver)
        agent_model = normalize_agent_model(worker.get("model") or default_model)
        if agent_model:
            task["agent_model"] = agent_model
        agent_reasoning_effort = normalize_agent_reasoning_effort(worker.get("reasoning_effort") or worker.get("agent_reasoning_effort") or default_reasoning_effort)
        if agent_reasoning_effort:
            task["agent_reasoning_effort"] = agent_reasoning_effort
        task["workspace_access"] = normalize_workspace_access(worker.get("workspace_access"))
        task["subagent_policy"] = worker_subagent_policy(worker)
        blocked_by = sorted({safe_id(str(item), "task") for item in [*as_list(worker.get("dependencies")), *as_list(worker.get("depends_on"))] if item})
        if blocked_by:
            task.setdefault("dependencies", {})["blocked_by"] = blocked_by
        save_task(project_root, task)
    materialize_plan_overlap_policy(project_root, plan)
    write_orchestrator_config_resolution_artifacts(project_root, plan)
    command_project_context_refresh(argparse.Namespace(project_root=str(project_root)))
    for worker in workers:
        if not isinstance(worker, dict):
            continue
        task_id = safe_id(str(worker.get("id") or "worker"), "worker")
        capsule_status, capsule_rel = existing_capsule_status(project_root, task_id)
        if capsule_status in {"fresh", "legacy"}:
            suffix = " (legacy capsule without assignment checksum)" if capsule_status == "legacy" else ""
            print(f"PRESENT: {capsule_rel}{suffix}")
        elif capsule_status == "stale":
            print(f"FAIL: assignment capsule is stale for {task_id}: {capsule_rel}; create a new capsule intentionally before launch")
            return 1
        else:
            status, output = run_command_capture(command_assignment_capsule, argparse.Namespace(project_root=str(project_root), assignment=str(assignment_yaml_path(project_root, task_id)), force=bool(plan.get("allow_write_scope_overlap", False))))
            print(output, end="")
            if status:
                return status
        status, output = run_command_capture(command_worker_launch_prompt_create, argparse.Namespace(project_root=str(project_root), task=task_id, output=None, apply=True, dry_run=False))
        print(output, end="")
        if status:
            return status
        task_doctor_status = command_task_doctor(argparse.Namespace(project_root=str(project_root), task=task_id))
        if task_doctor_status:
            return task_doctor_status
        if str(runtime.get("start_policy") or "manual") == "prepare":
            prepare_worker_run(project_root, task_id, None, None)
        if getattr(args, "workplace", None):
            command_agent_lease_grant(
                argparse.Namespace(
                    workplace=args.workplace,
                    id=f"lease-{run_id}-{task_id}",
                    agent=task_id,
                    session="",
                    project_id=safe_id(project_root.name, "project"),
                    process=str(worker.get("process") or "task-batch-execution"),
                    run=run_id,
                    task=task_id,
                    capsule=rel(locate_flow_root(project_root) / "contexts" / "assignment-capsules" / f"{task_id}.capsule.yaml", project_root),
                    allowed_file=assignment_scope_items(worker.get("allowed_files")),
                    allowed_read_file=assignment_scope_items(worker.get("allowed_read_files")),
                    forbidden_file=assignment_scope_items(worker.get("forbidden_files")),
                    ttl=3600,
                )
            )
    write_orchestration_summary(project_root, plan)
    if str(runtime.get("start_policy") or "manual") == "supervisor" and bool(getattr(args, "shell_plan", False)):
        supervisor_status = command_supervisor_run(
            argparse.Namespace(
                project_root=str(project_root),
                run=run_id,
                profile=str(runtime.get("supervisor_profile") or "default"),
                driver=None,
                interval=0,
                max_ticks=5,
                final_drain_timeout=5,
            )
        )
        if supervisor_status:
            return supervisor_status
    doctor_status = command_run_doctor(argparse.Namespace(project_root=str(project_root), run=run_id))
    emit_process_event(project_root, "orchestrator.plan.applied", process_id="multi-agent-task-orchestration", subject=run_id, payload={"run_id": run_id, "doctor_status": doctor_status}, correlation_id=f"run-{run_id}")
    print(f"WROTE: {rel(run_root(project_root, run_id) / 'orchestration-summary.md', project_root)}")
    return doctor_status


def command_orchestrator_plan_status(args: argparse.Namespace) -> int:
    project_root = Path(args.project_root).expanduser().resolve()
    require_flow_root(project_root)
    plan = load_orchestrator_plan(project_root, args.plan, getattr(args, "run", None))
    run = plan.get("run") if isinstance(plan.get("run"), dict) else {}
    run_id = safe_id(str(run.get("id") or "run"), "run")
    print(f"RUN: {run_id}")
    print(f"PLAN: {rel(orchestrator_plan_path(project_root, run_id), project_root)}")
    if run_yaml_path(project_root, run_id).is_file():
        return command_run_status(argparse.Namespace(project_root=str(project_root), run=run_id))
    print("STATUS: plan-created")
    return 0


def process_execution_service(project_root: Path, explicit_workplace: str | None = None) -> ProcessExecutionService:
    manifest = resolve_project_workplace_manifest(project_root, explicit_workplace)
    workplace_root = manifest.parent if manifest is not None else None
    return ProcessExecutionService(project_root, workplace_root, sys.modules[__name__])


def print_process_execution_result(payload: dict[str, Any], *, as_json: bool = False) -> None:
    print(json.dumps(payload, ensure_ascii=False, indent=2, sort_keys=True) if as_json else dump_yaml(payload))


def command_work_start(args: argparse.Namespace) -> int:
    project_root = Path(args.project_root).expanduser().resolve()
    require_flow_root(project_root)
    payload = process_execution_service(project_root, getattr(args, "workplace", None)).start(objective=args.objective)
    print_process_execution_result(payload, as_json=bool(getattr(args, "json", False)))
    return 0 if payload.get("action") in {"created_new", "continue_existing"} else 1


def command_work_state(args: argparse.Namespace) -> int:
    project_root = Path(args.project_root).expanduser().resolve()
    require_flow_root(project_root)
    payload = process_execution_service(project_root, getattr(args, "workplace", None)).state(
        run_id=str(getattr(args, "run", None) or ""),
        assignment_id=str(getattr(args, "assignment", None) or ""),
    )
    print_process_execution_result(payload, as_json=bool(getattr(args, "json", False)))
    return 0


def command_work_transition(args: argparse.Namespace) -> int:
    project_root = Path(args.project_root).expanduser().resolve()
    require_flow_root(project_root)
    evidence: list[Any] = []
    evidence_file = str(getattr(args, "evidence_file", None) or "").strip()
    if evidence_file:
        loaded = json.loads(Path(evidence_file).expanduser().read_text(encoding="utf-8"))
        evidence.extend(loaded if isinstance(loaded, list) else [loaded])
    for raw in getattr(args, "evidence", None) or []:
        try:
            evidence.append(json.loads(raw))
        except json.JSONDecodeError:
            evidence.append(raw)
    payload = process_execution_service(project_root, getattr(args, "workplace", None)).transition(
        outcome=args.outcome,
        evidence=evidence,
        notes=str(getattr(args, "notes", None) or ""),
        run_id=str(getattr(args, "run", None) or ""),
        assignment_id=str(getattr(args, "assignment", None) or ""),
    )
    print_process_execution_result(payload, as_json=bool(getattr(args, "json", False)))
    return 0 if payload.get("action") in {"stage_transitioned", "run_completed"} else 1


def command_run_create(args: argparse.Namespace) -> int:
    project_root = Path(args.project_root).expanduser().resolve()
    require_flow_root(project_root)
    run_id = safe_id(args.id, "run")
    process_id = safe_id(args.process, "task-batch-execution")
    require_official_process_active(project_root, process_id)
    path = run_yaml_path(project_root, run_id)
    if path.exists():
        raise SystemExit(f"FAIL: run already exists: {rel(path, project_root)}")
    run = {
        "schema_version": 1,
        "id": run_id,
        "title": args.title,
        "process": process_id,
        "status": args.status,
        "created_at": now_utc(),
        "updated_at": now_utc(),
        "objective": args.objective or "",
        "platform": getattr(args, "platform", None) or "",
        "selected_specializations": [specialization_resource_id(str(item)) for item in as_list(getattr(args, "specialization", []))],
        "scope": {"type": "project", "project_root": "."},
        "tasks": [],
        "final_artifacts": [],
        "events": {"emitted": ["run.created"]},
        "privacy": {"public_safe": True},
    }
    planned = [path, run_root(project_root, run_id) / "plan.md", run_root(project_root, run_id) / "task-index.md"]
    if getattr(args, "dry_run", False):
        print_plan("run-create dry run", planned, project_root)
        return 0
    root = run_root(project_root, run_id)
    root.mkdir(parents=True, exist_ok=True)
    save_run(project_root, run)
    (root / "plan.md").write_text(f"# Run Plan: {args.title}\n\nObjective: {args.objective or 'TBD'}\n", encoding="utf-8")
    emit_process_event(project_root, "run.created", process_id=run["process"], subject=run_id, payload={"run_id": run_id, "path": rel(path, project_root)}, correlation_id=f"run-{run_id}")
    print(f"WROTE: {rel(path, project_root)}")
    return 0


def command_run_list(args: argparse.Namespace) -> int:
    project_root = Path(args.project_root).expanduser().resolve()
    require_flow_root(project_root)
    root = locate_flow_root(project_root) / "runs"
    runs = sorted(root.glob("*/run.yaml")) if root.is_dir() else []
    if not runs:
        print("No runs found.")
        return 0
    for path in runs:
        data = load_yaml_document(path)
        print(f"{data.get('id', path.parent.name)}\t{data.get('status', 'unknown')}\t{data.get('title', '')}")
    return 0


def command_run_status(args: argparse.Namespace) -> int:
    project_root = Path(args.project_root).expanduser().resolve()
    run = load_run(project_root, args.run)
    tasks = [item for item in run.get("tasks", []) if isinstance(item, dict)] if isinstance(run.get("tasks"), list) else []
    counts: dict[str, int] = {}
    for item in tasks:
        counts[str(item.get("status", "unknown"))] = counts.get(str(item.get("status", "unknown")), 0) + 1
    print(f"RUN: {run.get('id')}")
    print(f"TITLE: {run.get('title')}")
    print(f"STATUS: {run.get('status')}")
    print("TASKS: " + ", ".join(f"{key}={value}" for key, value in sorted(counts.items())) if counts else "TASKS: none")
    for item in sorted(tasks, key=lambda value: int(value.get("order", 0) or 0)):
        task = load_yaml_document(assignment_yaml_path(project_root, str(item.get("id", ""))))
        iterations = task.get("iterations") if isinstance(task.get("iterations"), list) else []
        latest = iterations[-1] if iterations and isinstance(iterations[-1], dict) else {}
        latest_text = f" latest={latest.get('id')}:{latest.get('kind')}:{latest.get('status')}" if latest else ""
        print(f"- {item.get('order')}: {item.get('id')} [{item.get('status')}]{latest_text}")
    blockers = [str(item.get("id")) for item in tasks if item.get("blocking", True) is not False and str(item.get("status")) in {"blocked", "failed"}]
    if blockers:
        print("BLOCKERS: " + ", ".join(blockers))
    return 0


def command_run_doctor(args: argparse.Namespace) -> int:
    project_root = Path(args.project_root).expanduser().resolve()
    run_id = safe_id(args.run, "run")
    with registry_file_lock(run_yaml_path(project_root, run_id)):
        checks = validate_run_consistency(project_root, run_id, include_runtime_events=bool(getattr(args, "runtime_events", False)))
    result = print_checks(checks)
    emit_process_event(project_root, "run.doctor.failed" if result else "run.doctor.passed", severity="error" if result else "info", subject=run_id, payload={"run_id": run_id, "result": "fail" if result else "pass"}, correlation_id=f"run-{run_id}")
    return result


